window.__D("text/torat-chaim/c024",{"p":[[2300540947,"בדבר [מה] כמו בדבר מאכל<sup data-n=\"9599\">776</sup> או לבוש [ו]ממון או ריוח גדול במו\"מ וכה\"ג אז יוליד רצון וחשק לדבר זה שהוטבע בשכלו איך שהוא טוב ויפה לו כו' ע\"כ הוא רוצה ומשתוקק לדבר זה רק לפי עצם השגת שכלו והבנתו<sup data-n=\"9600\">777</sup> באיכות הדבר הזה, וא\"כ הרי השכל והטעם הזה שבמוח בינה הוא שהוליד לרצון של מדה זו והוא המנהיג את הרצון הזה בכל בחי'<sup data-n=\"9601\">778</sup> פרטי אופנים והיינו באיזה כלי ולבוש [י]תלבש ולהביאו בפו\"מ (שנק' אור בכלי כידוע) ולכל אשר יחפוץ יט[נו] השכל דוקא, וזהו שנק' מדה בלשון מדה וגבול<sup data-n=\"9602\">779</sup> ממש, כי הרי<sup data-n=\"9603\">780</sup> הרצון הזה שנולד מצד השכל והדעת הוא בא במדה וגבול באותו דבר שהוטב בשכלו לפי אופן הטעם שיש לו בו וכאשר בטל הטעם בטל[ה] האהבה ו[ה]רצון הזה, שזהו [ש]נק' גבול לומר עד פה תבא<sup data-n=\"9604\">781</sup> ולא יותר, כי זהו המקום ששם מסתיים הרצון הזה כי חק וגבול זה נתן<sup data-n=\"9605\">782</sup> לו מן השכל שהולידו בו<sup data-n=\"9606\">783</sup>, ולכך ימצא ברצון זה שבמדות שבלב שינויים גדולים באופן התגלות הרצון כך או כך שהרי אין כל [ה]עיתים שוות אף ברצון א' לד\"א, שפעם רוצה וחושק בו באופן כך ולפעמים רוצה בו באופן אחר היפוכו דוקא (כי כל מדה כלול מזולתו [ה]הפכי כמו חסד שבגבורה וגבו' שבחסד וכה\"ג וריבוי אופני הכלים ולבושים שמ[ת]חלפי' תמיד כו'), והכל רק ע\"פ הוראת השכל וההשגה שבמוח בינה ששרשן במדות דחכ' שנק' [אי\"ן], והוא בחי' ו\"ק דאבא שהוא עצם השכל שמטה כלפי חסד או דין אע\"פ שלא יוכל להביא בטעם וסברא במוח בינה, וכאשר <span data-k=\"pg\">רפו</span> ּ יש לו טעם [ב]שכל והשגה נק' [ז]\"ת דבינה שהן מדות שבשכל והשגה שבמוח בינה שכלולים בה כעובר בבטן אמו עדיין, כמו התפעלו' אוי\"ר שכלי' שכלולי' בהשגה אלקי' עדיין ולא ניכר במציאות מהות בפ\"ע עד שיגלו בלב ממש וזהו שנק' עיבור דו' בה' עילאה שזהו בחי' רגל הקצר שבה\"א כו' (כמ\"ש בזהר ע\"פ כי מראש צורים אראנו ומבואר באריכות בבה\"ז<sup data-n=\"9607\">785</sup> ).\n<b>וכך</b> יובן למעלה במדות עליונות דז\"א דאצי' שנק' יש\"ז שהן מדות שבבינה עילאה כנ\"ל שזהו רצה\"ע שבמדות דאצי' שמורכב בשכל וטעם, שהוא בחי' מוחין דאימא עילאה שנולדים בגילוי מן ההעלם במדה בהתלבשות אורות בכלים כאור החסד דאצי' בכלי דוקא, כמו אמרתי עולם חסד יבנה<sup data-n=\"9608\">786</sup> מע\"ב וכה\"ג חסד שנק' דרועא ימינא<sup data-n=\"9609\">787</sup>, ולא כל העיתים שוות שלפעמי'",[["9599","776","<b>בדבר מאכל</b>: הו: בטוב המאכל."],["9600","777","<b>והבנתו</b>: שם: והכרתו."],["9601","778","<b>בחי'</b>: שם: ליתא."],["9602","779","<b>מדה בלשון מדה וגבול</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קמ. דברים ח\"א ע' לה ובהנסמן בהנ\"ל."],["9603","780","<b>הרי</b>: הו: ליתא."],["9604","781","<b>עד פה תבא</b>: איוב לח, יא."],["9605","782","<b>זה נתן</b>: הו: ומדה נותן."],["9606","783","<b>בו</b>: שם: כו'."],["9607","785","<b>בזהר ע\"פ כי מראש צורים. . בבה\"ז</b>: בלק, כג, ט. זהר שם רג, ב. ביאוה\"ז שם קג, א ואילך. מאמרי אדה\"ז תקס\"ח ח\"א ע' רסט ואילך."],["9608","786","<b>אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["9609","787","<b>חסד. . דרועא ימינא</b>: ת\"ז בהקדמה (יז, א)."]]],[2300540954,"מתחלף מחסד לדין ומדין לחסד כמדה\"ר<sup data-n=\"9610\">788</sup> כו' והיינו רק מצד גבול ומדה דחו\"ב דאצי' המשפיעים במדות באו\"כ שניתן לפי שעה כמו ג' שעות יושב ודן<sup data-n=\"9611\">789</sup> את כל העולם כולו כו' וד\"ל. אך הנה כ\"ז הוא בבחי' מדות דז\"א שנק' יש\"ז כנ\"ל והוא שנק' רצון התחתון כנ\"ל, אבל אית רצון שנק' רצה\"ע שזהו [ב]בחי' המדות שבכתר בכלל שנק' יש[\"ס] שהן בלתי מוגבלים בשיעור ומדה כלל כו'. והיינו בחי' הרצון הפשוט שלמעלה מן השכל והטעם שלא נולד כלל מצד השכל ברצון הנ\"ל אלא [הוא ב]בחי' עצמ[י]ו' וטבעי' כמו מדות הטבעי' שטבועים בטבע בנפש האדם, כמו אהבת האב אל בנ[ו] שהול[י]ד[ו] מעצמותו וכן האם שמרחמת לולדה כו' שזהו רק מצד הטבע[יות] שלמעלה מאיזה שכל וטעם כלל, כי גם אם הבן אינו ראוי לחסד ואהבה מצד הטעם כי אינו בר דעת וכה\"ג עכ\"ז לא תפסוק אהבה עצמי' ממנו כלל. [וכך הוא בכל המדות הטבעיות אף שהוא בדבר שהשכל והטעם הוא לנגדו דווקא עכ\"ז לא יוכל לשנות מכפי מדתו בטבעיות כלל] כמו איש כילי וקמצן [מאד] בטבעו או אכזרי וקשה הלב בטבעו לא יוכל להפך טבעו לפזר או לרחם, אע\"פ שיחייב השכל והטעם כמו על איש עני [ו]חשוב [ו]קרובו או למי שעשה לו טובה רבה וכה\"ג, וכן להיפך מי שהוא בטבעו איש טוב וחסדן ורחמן או פזרן גדול לא יוכל להחליף טבעו להיות אכזרי לא ירחם או לקמץ כו' אף בדבר שהשכל יחייב כמו לשונאו או לאיש רשע ורע ופחות הערך לא ישנה חסדו וטובו, ולא עוד אלא שאנו רואים בחוש שהמדות הטבעי' שהן בבחי' רצון עצמי ופשוט הוא המנהיג ושליט על השכל שבמוח<sup data-n=\"9612\">790</sup> ולא שהשכל מנהיג אותו כמדות שנולדו מן השכל כו', אדרבה הרצון הזה עצמ[ו] הוא המנהיג [ושולט] על השכל שבמוח, והיינו לפי שממנו נתהוה השכל והטעם שע\"י שרצונו העצמי כך דוקא אז יטה לכח השכל למצוא לו טעם ושכל מן ההעלם לגילוי להיות נוטה גם השכל [כ]רצונו דוקא הן לזכות וחסד והן לחוב ודין, וכנודע בענין השוחד שיעוור עיני חכמים<sup data-n=\"9613\">791</sup> שע\"י השוחד שמגיע בעצם רצונו הטבעי לממון יטה הרצון לכח השכל שישכיל מיד למצוא זכות וחסד לזה שנתן לו השוחד כעובדא דר\"י שנתן לו<sup data-n=\"9614\">792</sup> כלכלה דפר[ות] ואמר אי בעי טעין הכי כו', כי עי\"ז מטה רצונו למצוא לו שכל חדש להפוך בזכותו. וכמ\"כ מצד האהבה [ה]עצמי' דבן לאב יהפוך גם את השכל לזכות אף בכל החובות שלו עד שלא יראה עליו [שום] חוב רק זכות כמו לא הביט<sup data-n=\"9615\">793</sup> כו', ולהיפך לשונאו בתכלית יהפך כח השכל מזכות לחוב כו'. ולפ\"ז <span data-k=\"pg\">574</span> ּ עיקר הממשלה על הטיית השכל <sup data-n=\"9616\">794</sup>לחוב שי[ו]צא מן ההעלם דבר<sup data-n=\"9617\">795</sup>",[["9610","788","<b>כמדה\"ר</b>: הו: יה\"ר."],["9611","789","<b>ג' שעות יושב ודן</b>: ראה ע\"ז ג, ב."],["9612","790","<b>המנהיג. . שבמוח</b>: הו: השולט ומנהיג את השכל."],["9613","791","<b>השוחד שיעוור עיני חכמים</b>: פ' שופטים טז, כ. ראה גם מאמרי אדה\"א בראשית ע' קצ. וש\"נ. שע\"ת ט, ג ובהערה 22. לעיל פ' בא קל, ג. לקמן פ' ויקהל תלח, ב."],["9614","792","<b>כעובדא דר\"י שנתן לו</b>: וכ\"ה במאמרי אדה\"ז על מארז\"ל ע' כ. לעיל פ' בא קל, ג: שהביא."],["9615","793","<b>לא הביט</b>: בלק כג, כא."],["9616","794","<b>לחוב</b>: הו: לחו\"ג."],["9617","795","<b>דבר</b>: הו: דכח."]]],[2300540961,"המשכיל ההיולי כו' אינו רק ברצון הטבעי' ועצמי' שבנפש והן שנק' מדות שברצון העצמי כנ\"ל שלמעלה מהג[ב]לת השכל והטעם כנ\"ל וד\"ל.\n<b>ועפי\"ז</b> יובן גם למעלה שבמדות אלה שנק' ימי קדם שהן מדות שבכתר<sup data-n=\"9618\">796</sup> שהוא עצם הרצה\"ע שלמעלה מחכ'<sup data-n=\"9619\">797</sup> דאצי' ונק' ג\"כ בחי' טורי חשוכא<sup data-n=\"9620\">798</sup> הרי קדם<sup data-n=\"9621\">799</sup> שהמדות נק' הרים [ד]בחי' צומח שבדומם<sup data-n=\"9622\">800</sup> כו', והיינו שרש האבות שהיו מרכבה<sup data-n=\"9623\">801</sup> לחג\"ת דז\"א ושרש שרשן הוא בחג\"ת דע\"י וא\"א<sup data-n=\"9624\">*802</sup> שהוא בחי' הכתר בכלל ונק' בחי' טורי חשוכא שבהעלם עצמו' הרצון (ואמנם מדות שנמשכי' מחו\"ב דאצי' כנ\"ל נק' טורי נהורא<sup data-n=\"9625\">802</sup> דהחכ' נק' אור כידוע). וזהו אשר נשבעת לאבותינו מימי<sup data-n=\"9626\">804</sup> קדם<sup data-n=\"9627\">803</sup> שהן מדות דקדושה שבאצי' במקורם הראשון בכת\"ר שנק' ימי קדם קדמונו ש\"ע<sup data-n=\"9628\">805</sup> כו'<sup data-n=\"9629\">806</sup>, שהמדות הללו הן בלתי מוגבלים כלל בשכל וטעם לומר שמגבילים השכל והטעם כשיבוטל הטעם כנ\"ל, אחר שהן בבחי' רצון עצמי וטבעי כאהבת האב אל הבן כנ\"ל שאין בו שינוי ולא תחליף ולא הגבלה בשיעור ומדה [כ]מדות שבלב להיותם בעצמו' הרצון שבעצמו' א\"ס ב\"ה [ממש] וד\"ל (וזהו מ\"ד דזכות אבות לא תמו<sup data-n=\"9630\">807</sup> כלל כי אינם מוגבלים בשכל וטעם כלל). ולכך בחי' המדות שברצה\"ע הנפש<sup data-n=\"9631\">808</sup> נק' יש\"ס בבחי' הגדלת [ד]רצון [ה]עצמ[י] שאין בו שיעור כלל<sup data-n=\"9632\">809</sup> וגבול ומדה ונק' אה\"ר בלי גבול כלל וכן להיפך תכלית שנאה כו', שאין אור שכל וטעם לאה\"ר זו לאמר עד פה תבוא ולא יותר שהוא רק עד מקום שיד השכל והטעם מגעת כמו אה\"ר דאב אל הבן אין השכל והטעם מגבילו כלל, וכמו בגלות [דכנ\"י] שאמר לא מאסתים<sup data-n=\"9633\">810</sup> כו' אף שאינם ראויים ע\"פ השכל והטעם דחכ' דתו' כלל לפי שאה\"ר אהבתנו<sup data-n=\"9634\">811</sup> למעלה ממשפט וטעם דח\"ע דתו', וכן מבקשי' בש\"ע רפאינו ברך עלינו כו', וכן יהי רצון מלפניך שיכבשו רחמיך<sup data-n=\"9635\">812</sup> כו' כמו ביו\"כ שסולח לעוונות ונושא עון שזה מבחי' רעדכ\"ר (כמשי\"ת). ואמנם הנה עדיין י\"ל למה נק' בשם יש\"ס שזהו בבחי' גדלות דחכ' עכ\"פ שנק' ח\"ס כנ\"ל מאחר שמדות הללו עצמי' וטבעי' הוא בעצם הרצון הפשוט שלמעלה מן השכל וטעם לגמרי [כנ\"ל], וזהו שא' אראנו לבחי' יש\"ס זה נפלאות כו' כנ\"ל. אך הנה באמת הרי בחי' שרש הראשון של המדות דז\"א (שהן מדות שבלב) הוא במדות דע\"י עצמן (כמ\"ש דז\"א בע\"י עצמו אחיד כו' שזהו למעלה גם מבחי' מזלות דונוצר ונקה שנמשכים מח\"ס כו').",[["9618","796","<b>ימי קדם שהן מדות שבכתר</b>: ראה גם לעיל פ' בא צ, ג הערה 178. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670388\" data-slug=\"torat-chaim\" data-id=\"2300670388\">תו\"ח בראשית יג, ג</a> ובהערה 16."],["9619","797","<b>מחכ'</b>: הו: מח\"ע."],["9620","798","<b>טורי חשוכא</b>: נסמן לעיל פ' שמות טז, א הערה 680."],["9621","799","<b>הרי קדם</b>: נסמן לעיל פ' בא קכז, ג."],["9622","800","<b>הרים. . צומח שבדומם</b>: ראה גם לעיל פ' וארא עז, ג. מאמרי אדה\"א דברים ח\"ב ע' תרסד-ה. וש\"נ. שע\"ת קד, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670105\" data-slug=\"torat-chaim\" data-id=\"2300670105\">תו\"ח בראשית כ, א</a> ובהערה 3."],["9623","801","<b>האבות. . שהיו מרכבה</b>: נסמן לעיל פ' שמות ה, ג."],["9624","*802","<b>האבות. . בחג\"ת דע\"י וא\"א</b>: נסמן לעיל קנח, ב."],["9625","802","<b>מדות. . טורי נהורא</b>: נסמן לעיל פ' שמות טז, א."],["9626","804","<b>מימי קדם</b>: הו: ליתא."],["9627","803","<b>אשר נשבעת לאבותינו מימי קדם</b>: נסמן לעיל פ' בא צ, ג."],["9628","805","<b>ימי קדם קדמונו ש\"ע</b>: ראה גם לקמן פ' משפטים ש, ד. ש\"א לג, ב."],["9629","806","<b>כו'</b>: הו: ליתא."],["9630","807","<b>דזכות אבות לא תמו</b>: ראה גם לעיל פ' וארא סב, ב. וש\"נ."],["9631","808","<b>הנפש</b>: הו: הנ\"ל."],["9632","809","<b>כלל</b>: שם: ליתא."],["9633","810","<b>לא מאסתים</b>: בחוקותי כו, מד."],["9634","811","<b>שאה\"ר אהבתנו</b>: ברכת ק\"ש נוסח אשכנז."],["9635","812","<b>יה\"ר מלפניך שיכבשו רחמיך</b>: סידור האריז\"ל בסדר תקיעת שופר [בדילוג]."]]],[2300540967,"(ךב) <b>והנה</b> לפעמים א' דאו\"א (שהן מקורים למדות דז\"א שבלב) מלבישי' לזרועות דא\"א<sup data-n=\"9636\">813</sup> וע\"י בלבד (וזהו ויוציאנו ה' אלקינו<sup data-n=\"9637\">814</sup> או\"א משם ביד חזקה ובזרוע נטוי' שהן בחי' זרועות דא\"א כמבואר בכוונות בהגדה) ומבואר במ\"א באריכות, ולפעמים א' דאור אבא דאצי' יונק רק ממזל הח'<sup data-n=\"9638\">815</sup> ונוצר חסד שהוא בוקע ונמשך רק ממותרות מ\"ס דא\"א כו', וי\"ל מהו ההפרש בין בחי' הלבשה זאת דאו\"א דאצי' שמלבישים לזרועות דא\"א ובין אבא יונק<sup data-n=\"9639\">816</sup> ממזל ונוצר חסד<sup data-n=\"9640\">817</sup> כו'. אך הנה י\"ל תחלה בבחי' המדות שברצון עצמו שלמעלה מן השכל ו[ה]טעם כנ\"ל כמו אה\"ר בלי גבול [כלל כנ\"ל], הנה עכ\"ז אנו רואים שגם ברצון שבמ[ד]ות אלה יש בחי' התחלקות ונטיות שונות <span data-k=\"pg\">רפז</span> ּ מאד, ובכלל נחלק הרצון הזה לב' הפכים חסד ודין [כ]אהבה ושנאה, רק שנק' אה\"ר ותכלית שנאה בלי גבול למעלה מהגבלת השכל ו[ה]טעם. וב' מדות אלה דחו\"ג שברצון העצמי יש בחי' ממוצע שנק' ת\"ת, וכן מדת הנצחון העצמי שברצון זה, וכה\"ג כ[ל] פרטי התחלקות המדות שנמצא במדות שנולדי' מן השכל שבלב (ונק' טורי נהורא) שלמטה מן הדעת, כמ\"כ ממש נמצא כל התחלקות זאת במדות שברצה\"ע כנ\"ל שלמעלה מן הדעת (כי שרש מדות שבלב הן במדות האלה שבעצם הרצון כנ\"ל). וגם אנו רואים בחוש שיש שינויים רבים בעיתים שונים שאין כל העיתים שוות באופן גילוי הרצון העצמי הזה כו' שיש עת טוב שנק' עת רצון לטוב שבעת הזאת מתגלה עצם הרצון הכל לטוב למעלה מן הטעם כנ\"ל, ויש עת רצון להיפ[וכו] לדין וחוב בלא טעם כלל, וכן בכמה מיני אופנים שונים הכל תלוי בעיתים שונים. וי\"ל מאיזה סיבה וטעם יש השתנות ברצה\"ע הזה מאחר שהוא למעלה מן השכל והטעם הרי אין דבר שמחלק אותו לב' הפכים כחו\"ג ופרטיהן ולשנות מעת לעת מהיפך להיפך כנ\"ל.\n<b>אך</b> בהכרח צ\"ל שיש איזה טעם שהוא הסיבה להביא גילוי הרצון מן ההעלם באופן כך לחסד או להיפ[וכו] לדין, וע\"כ גם הרצון העצמי הזה משתנה לפרקים ועתים שונים כנ\"ל. והגם שאין הרצון הזה מורכב בשכל וטעם כלל כידוע דאין טעם לרצון כלל, כי עצם הרצון מובדל בערך מבחי' טעם ושכל, עכ\"ז הרי אנו רואים שיש שינויים בגילוי עצם הרצון, דמוכרח לומר מזה דודאי בחי' עצמו' העלם הרצון הטבעי שבעצמות הנפש ממש אין בו שינויים כלל שאינו מתלבש בשום טעם, אבל בחי' גילוי של הרצון העצמי מתגלה הוא באופנים שונים דהיינו בהטיות והתחלקות שונות ומשתנה לפי שינוי הדעת לחסד או לדין כנ\"ל. וזה ודאי מוכרח לומר שיש דבר המטה את גילוי הרצון כך ולא כך והוא שנק' בחי' ד\"ע, שהוא כמו בחי' דעת",[["9636","813","<b>דאו\"א. . מלבישי' לזרועות דא\"א</b>: ראה גם לעיל פט, ב. וש\"נ."],["9637","814","<b>ויוציאנו ה' אלקינו</b>: נסמן לעיל שם."],["9638","815","<b>דאור אבא. . ממזל הח'</b>: נסמן לעיל לו, א."],["9639","816","<b>ההפרש. . דאו\"א. . שמלבישים. . אבא יונק</b>: ראה גם לעיל פט, ב. וש\"נ."],["9640","817","<b>חסד</b>: הו: דח\"ס."]]],[2300540973,"נוטה<sup data-n=\"9641\">818</sup> במדות [שבשכל וטעם הגלוי לחו\"ג ונק' ד\"ת הנגלה בהכרעת הנטי' של השכל וטעם הגלוי לזכות או להטות השכל והטעם הגלוי לחוב ודין] דוקא כידוע שזהו כמו קו המשקולת ששוקל ומכריע לקו ימין<sup data-n=\"9642\">819</sup> או לשמאל, כך הוא ממש בבחי' ד\"ע הנ\"ל<sup data-n=\"9643\">820</sup> שבכתר הוא הרצון העצמי הנ\"ל שהוא כח הנעלם בהעלם עצמו' הרצון שמטה את כח הרצון הנעלם שיבא לידי גילוי לכך ולא לכך, ולפעמים מטה לרצון לבא לגילוי החסד ולפעמים מטה כח הרצון הנעלם העצמי' שיתגלה לדין דוקא (כמו בהטיות ד\"ת [ב]חו\"ג שבשכל הגלוי כבר מן הנעלם, דכח השכל [ש]השכיל לחסד בגילוי או לדין בגילוי שהד\"ע<sup data-n=\"9644\">821</sup> הוא [ה]מכריע לחסד או לדין [או] שישקול בתחלה להטות כח השכל שיבא מן ההעלם לגילוי לזכות או להטות לחוב כו'. ובאמת הטי' זו להטות לכח השכל (שנק' ח\"ס המשפיע כל שכל לזכות או לחוב), זהו תלוי בהטיות דד\"ע שמטה מהעלם כח הרצון לבוא בגילוי לח\"ס<sup data-n=\"9645\">822</sup> אז יטה גם לכח השכל להשפיע שכל וטעם לזכות וחסד והא בהא תליא ממש, כמו שמצינו במ\"ש וירא כי רבה רעת האדם<sup data-n=\"9646\">823</sup> והי' גילוי הטיית [ה]רצה\"ע לדין שעי\"ז הטה כח החכ' לדין ולחוב לשחת כל בשר בימי<sup data-n=\"9647\">824</sup> המבול, ואח\"כ בקרבן נח שנהפך לגילוי רצון להטות השכל ממקורו כלפי חסד וזכות אמר לא אוסיף כו' כי יצר לב האדם רע<sup data-n=\"9648\">825</sup> כו', ונהפך מאותו השכל וטעם<sup data-n=\"9649\">826</sup> <span data-k=\"pg\">576</span> ּ שהי' מח[יי]ב [ל]דין להיות טעם לזכות מצד ההשגה<sup data-n=\"9650\">827</sup> הרצון מעצמו' בעה\"ר [העליון] כו' וד\"ל). וכמו באהבת האב לבנו בעצם הרצון לטוב בהעלם ובכח שממילא יגלה הטייות<sup data-n=\"9651\">828</sup> רק לטוב ויטה כח השכל לדין [בטעם גילוי] מן ההעלם [רק לזכות עליו, ועל שונא יטה רצונו תמיד מן ההעלם לגילוי רק לדין (וממילא יטה גם לכח השכל לדין מן ההעלם] דכח השכל רק לחוב כו'). וכמו\"כ במשל דקבלת שוחד שעי\"ז מטה רצונו מן ההעלם לגילוי לחסד וזכות וממילא י[ו]משך לדין מכח השכל למצוא לו זכות, ולהפוך למצוא דין וחוב ל[כ]שנגדו, וזהו בחי' ד\"ת שתל[ו]י בד\"ע המטה כח הרצון<sup data-n=\"9652\">*829</sup> וכח השכל [הנעלם] לחו\"ג כמ\"ש במ\"א.\n<b>ומעתה</b> הנה [יובן] שרש בחי' התחלקות המדות שברצון [ו]שהוא משתנה מהיפך להיפך הגם שאין טעם לרצון כנ\"ל דזהו מצד בחי' הד\"ע כנ\"ל שהוא המטה לרצון שיאיר בגילוי מן ההעלם לחסד או לדין כנ\"ל, אך גם בחי' ד\"ע הזה מאין בכח לעשות בחי' הטיי' זאת בעצם הרצון, הנה מוכרח לומר דכמו שבחי' ד\"ת שמטה אור השכל הגלוי לחו[\"ג] שזהו במוחין דחו\"ב שנמשך מאין ליש בהשגת שכל וסברא בגילוי שיש שכל מטה כלפי חסד ויש שכל מטה כלפי דין כו', ובחי' הדעת הוא השוקל ומכריע להטות השכל ו[ה]סברא לחסד או",[["9641","818","<b>דעת נוטה</b>: נסמן לעיל פ' שמות מב, א."],["9642","819","<b>לקו ימין</b>: הו: לימין."],["9643","820","<b>הנ\"ל</b>: שם: הזה."],["9644","821","<b>שהד\"ע</b>: שם: שהדעת."],["9645","822","<b>לח\"ס</b>: שם: לחסד."],["9646","823","<b>וירא כי רבה רעת האדם</b>: בראשית ו, ה [בדילוג]."],["9647","824","<b>בימי</b>: הו: במי."],["9648","825","<b>לא אוסיף. . רע</b>: נח ח, כא. הו: לא אוסיף להכות [ושם: ולא אוסיף עוד להכות. בהיפך הסדר]."],["9649","826","<b>מאותו השכל וטעם</b>: ראה גם לעיל פ' בא קל, ג. וש\"נ."],["9650","827","<b>ההשגה</b>: הו: הטיי'."],["9651","828","<b>הטייות</b>: שם: ליתא."],["9652","*829","<b>בד\"ע המטה כח הרצון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670254\" data-slug=\"torat-chaim\" data-id=\"2300670254\">תו\"ח וירא קיב, ב</a>."]]],[2300540978,"לדין כנ\"ל. כך הוא בבחי' ד\"ע דרצון הנ\"ל שהוא המכריע במוחין דחו\"ב שבכת\"ר שהוא הרצון והוא<sup data-n=\"9653\">829</sup> בחי' חו\"ב שברצון, הגם שאין שכל וטעם לרצון שהוא למעלה מן הטעם כנ\"ל זהו שהוא למעלה מן השכל [ו]טעם גלוי בהשגה (ואף לא בהעלם דאין דחכ' שנמשך לבינה), אבל בעצמו' הרצון שנק' כת\"ר ודאי יש גם בחי' חו\"ב<sup data-n=\"9654\">830</sup> ונק' חכ' שבכתר, והוא שאינו נראה ונגלה בהשגה שבשכל וטעם לרצון התחתון שמורכב בשכל בגילוי אלא כמו<sup data-n=\"9655\">831</sup> בחי' טעם זה נק' טעם כמוס להעלם הרצון העליון הנ\"ל ש[י]טה את הרצון לגילוי מן ההעלם לחסד וטוב או להיפך כמו החו\"ב<sup data-n=\"9656\">832</sup> שבשכל וטעם הגלוי רק זהו בהעלם לגמרי מן<sup data-n=\"9657\">833</sup> שכל וטעם גלוי (והיינו ד[ב]כח המעלים<sup data-n=\"9658\">834</sup> השכל שמטה לזכות וחסד שהוא ע\"י בחי' ד\"ע שמטה לרצון וכח השכל כנ\"ל) (וכדוגמא שא' גבי ר\"ע וכי זו תו'<sup data-n=\"9659\">835</sup> כו' ואמר<sup data-n=\"9660\">836</sup> שתוק כך עלה במח'<sup data-n=\"9661\">837</sup> לפני כלומר כך עלה ברצון שאין טעם לרצון הזה בגלוי רק בהעלם בעצמו לבד כענין הלא כמוס עמדי<sup data-n=\"9662\">838</sup> כו' [שהוא טעם כמוס עמדי]. וכמו\"כ יש טעם כמוס לרצון בהעלם עצם הנפש אע\"פ שאינו מרגיש בעצמו רק לומר שכך רצונו בלא טעם כלל כו', כי בעצם העלם בנפשו יש טעם לרצון זה אלא שלא יוכל לבוא בגילוי כלל כו' וד\"ל.\n<b>והנה</b> עכ\"ז יובן ג\"כ למעלה בשרש המדות העליונות דז\"א דאצי' שכלולי' מחו\"ג<sup data-n=\"9663\">839</sup> דאצי' ששרשם הראשון הוא במדות דחו\"ג והממוצע בכל פרטיהן בכתר עצמו [ש]נק' מדות שברצה\"ע שלמעלה מן השכל וטעם הגלוי בחו\"ב דאצי' שנק' או\"א, אלא אעפ\"כ<sup data-n=\"9664\">840</sup> מאחר שאנו רואים בחי' התחלקות דחו\"ג גם בעצמו' אור הכתר מוכרח שיש גם שם מקור להתחלקות זאת ולשנות בעיתים הנ\"ל, והוא בחי' חב\"ד שבכתר (ומה שנק' גלגלתא הוא בחי' כתר שבכתר שלמעלה גם מ[בחי'] ח\"ס כו' כמשי\"ת) והיינו בחי' מוחין<sup data-n=\"9665\">*841</sup> דא\"א, כי א\"א הוא הנק' כתר בכלל (וכלול מב' מדרגות א\"א וע\"י פנימי' וחיצוני' כמשי\"ת), ומה שמתחלק מהעלם עצמו' הכתר לחו\"ב<sup data-n=\"9666\">841</sup> זהו מצד הטי' דחו\"ב שבכתר שהוא בחי' טעם כמוס לרצון העליון שע\"י בחי' ד\"ע הוא המטה להרצון וטעם <span data-k=\"pg\">רפח</span> ּ הכמוס להיות כך ולא כך להיות משתנה לעיתים כו' וד\"ל. וכמ\"ש יהי רצון מלפניך ממש<sup data-n=\"9667\">842</sup> שיכבשו רחמיך את כעסך כו' וכה\"ג, שבודאי כבר יש ב' מדות אלו דחו\"ג רחמים וכעס במדות שבחו\"ג<sup data-n=\"9668\">843</sup> דאצי' שמקבלים מעצמות הכתר שנק' רצה\"ע שגם שם מתחלק לחו\"ג כנ\"ל רק",[["9653","829","<b>והוא</b>: שם: ופי'."],["9654","830","<b>חו\"ב</b>: שם: חכ'."],["9655","831","<b>כמו</b>: שם: ליתא."],["9656","832","<b>החו\"ב</b>: שם: החו\"ג."],["9657","833","<b>רק. . מן</b>: שם: הזה (זהו) רק בהעלם למעלה מן."],["9658","834","<b>המעלים</b>: שם: העלם."],["9659","835","<b>וכי זו תו'</b>: נסמן לעיל פ' שמות י, ב."],["9660","836","<b>ואמר</b>: הו: ליתא."],["9661","837","<b>שתוק כך עלה במח'</b>: ראה הנסמן לעיל פ' בא פט, ד."],["9662","838","<b>הלא כמוס עמדי</b>: האזינו לב, לד [בדילוג]. ראה גם מאמרי אדה\"א נ\"ך ע' רכא."],["9663","839","<b>שכלולי' מחו\"ג</b>: הו: שנולדו מחו\"ב."],["9664","840","<b>אעפ\"כ</b>: שם: עכ\"ז."],["9665","*841","<b>מוחין</b>: שם: מו\"ס."],["9666","841","<b>לחו\"ב</b>: הו: לחו\"ג."],["9667","842","<b>ממש</b>: הו: ליתא. וראה בסמוך (בפנים) שו\"ה והוא."],["9668","843","<b>שבחו\"ג</b>: שם: שבחו\"ב."]]],[2300540983,"שחו\"ג שבעצם הרצון הם בלי גבול כלל כנ\"ל. ואמנם גם הם יכולים להשתנות מהיפך להיפך ע\"י בחי' ד\"ע שמכריע לימין כו', והוא מ\"ש יהי רצון מלפניך ממש שהוא בעה\"ר (ובחי' כשב\"כ) שנק' רעדכ\"ר שיכבשו רחמיך ויגברו על מדה\"ד שברצון עצמו ע\"י טעם כמוס כו' שלמעלה מן השכל וטעם הגלוי בחו\"ב<sup data-n=\"9669\">844</sup> שבתו' כו', כמו שזן את העולם בחן ובחסד וברחמים<sup data-n=\"9670\">845</sup> לפנים משוה\"ד כו', דגם שיושב ועוסק בתו' ויושב ודן ע\"פ מדות דחו\"ג שבח\"ע דתו' שבא לגילוי מן ההעלם להטי' רצה\"ע לדין עכ\"ז זן את העולם ברחמים, וכמו י\"ג מדה\"ר דיו\"כ לסלוח לעוברי רצונו בתומ\"צ כמ\"ש במ\"א ע\"פ ארדה נא<sup data-n=\"9671\">846</sup> כו' [וכענין] פקח עיניך<sup data-n=\"9672\">847</sup> דלית שמאלא בהאי עתיקא<sup data-n=\"9673\">848</sup> כו' וזהו דוקא בבחי' כשב\"כ (כמשי\"ת) וד\"ל.\n(ךג) <b>ובכ\"ז</b> יובן מ\"ש ויוציאנו הוי' אלקינו משם ביד חזקה ובזרוע נטוי' כו' שהן ב' זרועות דא\"א וכמו קחם על זרועותיו<sup data-n=\"9674\">849</sup> כו', והוא ענין מ\"ש בע\"ח דאו\"א מלבישי' לזרועות דא\"א, פי' הלבשה זאת היינו כמבואר למעלה בבחי' התלבשו' המדות העצמ[י]' דרצון העצמי כאה\"ר דאב לבנו וכה\"ג שמתלבש בשכל וטעם לרצון (כמו השוחד שמטה רצונו לטוב ויתלבש דוקא בשכל למצוא לו זכות כו'), שמצד אה\"ר העצמי' ימצא זכות וחסד לבנו עפ\"י החכ' וטעם דוקא, אבל באמת העיקר הוא באמצעות האה\"ר [ה]עצמי' שברצון העצמי' שלמעלה מן הטעם ודעת לגמרי רק שמלב[י]ש הרצון הזה בשכל וטעם לבד שנק' הלבשה חיצוני' בגילוי מבחוץ בלבד (כמו בטעם שמצא<sup data-n=\"9675\">850</sup> כי יצר לב האדם כו'), וכך ביצ\"מ הי' מדה\"ד טוען מה נשתנו אלו מאלו כו' וגבר מדת החסד על מדה\"ד, וכן בקי\"ס א' ויושע ה' את ישראל<sup data-n=\"9676\">851</sup> כו' כענין הושיעה לו ימינו<sup data-n=\"9677\">852</sup>, וכן א' מוליך לימין משה<sup data-n=\"9678\">853</sup> זרוע תפארתו כו' והוא ימינך ה' נאדרי בכח<sup data-n=\"9679\">854</sup> שגובר על מדה\"ד מצד בחי' הארה<sup data-n=\"9680\">855</sup> העצמי' וזהו ביד חזקה כו', רק שמלובש הרצון בחכ' וטעם שהוא הח\"ס<sup data-n=\"9681\">856</sup> דתו' שבכ' ובע\"פ שהיו ראוים לקבלת התו' פב\"פ ובשביל זה הוציאם ביד חזקה כו' (דאע\"פ ששרש התומ\"צ שהוא בשם הוי' אלקינו בחו\"ב דאצי' לבד, אבל אע\"פ דאוריי' מח\"ע נפקת<sup data-n=\"9682\">857</sup> שרשה בעצמו' אור הכתר שהם חו\"ג שברצון הפנימי' ועצמי' כענין אנכי ולא יהי' לך בדבור א' נאמרו<sup data-n=\"9683\">858</sup> כידוע, והוא בחי' יד החזקה וזרוע הנטוי' שהי' בגילוי אור דמ\"ת כמ\"ש מימינו א\"ש ד\"ת למו<sup data-n=\"9684\">859</sup> כו'<sup data-n=\"9685\">860</sup>, וזהו [ו]אנכי<sup data-n=\"9686\">861</sup> זה שא' אנכי הוי' אלקיך<sup data-n=\"9687\">862</sup> אשר",[["9669","844","<b>בחו\"ב</b>: שם: בחכ'."],["9670","845","<b>שזן את העולם. . וברחמים</b>: ע\"פ נוסח ברכת המזון. השוה מאמרי אדה\"א בראשית ע' רפה."],["9671","846","<b>ארדה נא</b>: וירא יח, כא. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670442\" data-slug=\"torat-chaim\" data-id=\"2300670442\">תו\"ח וירא קטז, ג</a>."],["9672","847","<b>פקח עיניך</b>: דניאל ט, יח. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670496\" data-slug=\"torat-chaim\" data-id=\"2300670496\">תו\"ח שם קיח, א</a>."],["9673","848","<b>דלית שמאלא בהאי עתיקא</b>: נסמן לעיל פ' בא פט, ב."],["9674","849","<b>קחם על זרועותיו</b>: ויז: זרועותי — נסמן להלן הערה 863."],["9675","850","<b>שמצא</b>: ו: שאמר. יז: ליתא."],["9676","851","<b>ויושע ה' את ישראל</b>: בשלח יד, ל [בדילוג]. ראה מאמרי אדה\"א בראשית ע' רפא. קונטרסים ע' ג."],["9677","852","<b>הושיעה לו ימינו</b>: תהלים צח, א."],["9678","853","<b>מוליך לימין משה</b>: ישעי' סג, יב."],["9679","854","<b>ימינך ה' נאדרי בכח</b>: בשלח טו, ו."],["9680","855","<b>הארה</b>: ויז: האה\"ר."],["9681","856","<b>שהוא הח\"ס</b>: ו: בחי' החכ'. יז: ליתא."],["9682","857","<b>דאוריי' מח\"ע נפקת</b>: נסמן לעיל פ' שמות יא, א."],["9683","858","<b>אנכי. . בדבור א' נאמרו</b>: נסמן לעיל פ' וארא פו, א."],["9684","859","<b>מימינו א\"ש ד\"ת למו</b>: ברכה לג, ב."],["9685","860","<b>כו'</b>: אוצ\"ל: כו')."],["9686","861","<b>[ו]אנכי</b>: נסמן בהערה 863."],["9687","862","<b>אנכי הוי' אלקיך</b>: יתרו כ, ב."]]],[2300540988,"הוצאתיך מאמ\"צ שהן ב' זרועות דא\"א (כמשי\"ת), ומבואר למעלה שמדות חו\"ג שברצון אין טעם לרצון כלל דגם שאין הבן ראוי לזה אעפ\"כ אוהבו אה\"ר עצמי' וזהו אנכי תרגלתי לאפרים קחם על זרועותיו<sup data-n=\"9688\">863</sup> כאדם המגביה [ל]בנו הגבה למעלה על זרועותיו (כמשי\"ת). אמנם אעפ\"כ יש בחי' טעם כמוס לרצון זה העצמי שהוא כח המטה לרצון זה ולכח השכל להשכיל לח\"ס<sup data-n=\"9689\">864</sup> מן ההעלם לגילוי כו' כנ\"ל. <span data-k=\"pg\">578</span> ּ וזהו ענין שא' בע\"ח דאו\"א<sup data-n=\"9690\">865</sup> יונק ממזל הח' ונוצר דונוצר אותיות רצון בחי' רצון<sup data-n=\"9691\">866</sup>, והוא בחי' רצון העצמי דבחי' פנימי' הכתר עצמו שלמעלה גם מבחי' חכ'<sup data-n=\"9692\">867</sup> שבכתר שנק' [טעם כמוס] להט[ו]ת הרצון [ב]התחלקות המדות שברצון זה עצמו כנ\"ל. והענין הוא שגם דאו\"א שהוא בחי' אור הח\"ע שמאין תמצא שמקבל ויונק מבחי' חכ' שבכתר הנק' מו\"ס דא\"א [ו]זה[ו] רק מבחי' מזל ונוצר אותיות צנור כמו צנור דק הנפתח מחביות הגדולה והמליאה כו', כך אור החכ' בעצם נמשך ממקורה דרך העלם וצמצום גדול כיונק שיונק שדי אמו והיינו מזל ונוצ\"ר דא\"א שנמשך מבחי'<sup data-n=\"9693\">868</sup> שערה לבד ממותרי מו\"ס משם יונק או\"א<sup data-n=\"9694\">869</sup> ו[נ]תגדל מעט מעט ביניקה זאת כו' (כמו יפתח ה'<sup data-n=\"9695\">870</sup> לך כו' כמו צנור הנפתח במפתח<sup data-n=\"9696\">872</sup> כו' אוצרו הטוב<sup data-n=\"9697\">871</sup> בחי' אוצר החכ' דים הקדמוני בחי' חכ' הקדומה שבעצמו' א\"ס ממש דלתבונתו אין מספר<sup data-n=\"9698\">873</sup> כלל, וזהו בימי ת\"ר לחיי נח צ\"ע ש[י]פתח[ו] מבועין דח\"ע וכמו וה' נתן חכמה לשלמה<sup data-n=\"9699\">874</sup> וכה\"ג).\n<b>אמנם</b> ידוע הכלל שברכה<sup data-n=\"9700\">875</sup> זאת שיוציאם בחי' או\"א מח\"ס<sup data-n=\"9701\">876</sup> דא\"א הוא בא מצד עוצם ריבוי [ה]אור בתוס' גדול יותר מכמו שהוא בעצם ע\"כ בוקע ויוצא ממנו בחי' מותרות בשערות וכה\"ג, וכמשל חביות המלאה ביותר שנפתח הצנור ממילא ויוצא מותרות, שהוא מה שלא יוכל להכיל בחביות מפני מילוא[ה] הוא שיוצא בדרך מותרות שפתה ובצנור וכה\"ג, וא\"כ אותיות<sup data-n=\"9702\">877</sup> הללו באין ממה שלא יוכל לבוא לתוך הכלי עוד כו'. וכך יובן במותרי מוחין העליונים [כ]זקן שקנה חכ' שמצד ריבוי האור ממקורו ביותר יוצא ממנו צמחים והשערות<sup data-n=\"9703\">878</sup> להמשיך מותרות השפע, אבל שרשו הוא למעלה מגוף המוחין דח\"ס והוא בעצ[מות] אור הכתר (ודוגמא לזה היינו [מה] שאנו רואים בכח המוליד שבטפה [ש]אינו אלא בריבוי המוחין שבראש [ש]מחמת זה יש בחי' מותרות מוחין אז טפה הרוחני' שבמוח[ו] ראוי להוליד ולד, כמו תינוק בן ט'<sup data-n=\"9704\">879</sup> שנים דוקא ולא פחות מבן ט' שנים אע\"פ שיש טפה רוחני' וגשמי' אינו מוליד כלל לפי שאין בו בחי' מותרי",[["9688","863","<b>אנכי תרגלתי. . זרעותיו</b>: ויז: ואנכי. . זרועותי [וכן לעיל הערה 849] נסמן לעיל פ' בא פט, ב. וראה גם לקמן רד, ג."],["9689","864","<b>לח\"ס</b>: ו: לחסד. יז: ליתא."],["9690","865","<b>דאו\"א</b>: ויז: דאור אבא."],["9691","866","<b>בחי' רצון</b>: יז: ליתא."],["9692","867","<b>מבחי' חכ'</b>: ויז: מחכ'."],["9693","868","<b>מבחי'</b>: יז: בבחי'."],["9694","869","<b>או\"א</b>: ויז: אור אבא."],["9695","870","<b>יפתח ה' לך כו'. . אוצרו הטוב</b>: תבוא כח, יב."],["9696","872","<b>במפתח</b>: ו: כמו פתח ר\"פ. וראה לעיל פ' שמות יב, ב הערה 545."],["9697","871","<b>לך. . הטוב</b>: יז: ליתא."],["9698","873","<b>דלתבונתו אין מספר</b>: תהלים קמז, ה."],["9699","874","<b>וה' נתן חכמה לשלמה</b>: מלכים-א ה, כו."],["9700","875","<b>שברכה</b>: ויז: שסיבה."],["9701","876","<b>שיוציאם בחי' או\"א מח\"ס</b>: ו: שיוצאי' בחי' מותרי המוחין מח\"ס. יז: שיוצאי' מותרי המוחין דמו\"ס."],["9702","877","<b>אותיות</b>: שם: מותרות."],["9703","878","<b>צמחים והשערות</b>: שם: צמיח[ו]ת השערות."],["9704","879","<b>להוליד. . תינוק בן ט'</b>: נסמן לעיל פ' בא קלג, ב."]]],[2300540993,"מוחין עדיין כו', והיינו לפי שמותרות הללו שרשם מלמעלה מן המוחין בעצם (שזהו שנק' מזלא בחי' מקיף דכתר ששם יכול להוליד דבר חוץ [ממנו] בריבוי לאין שיעור כלל משא\"כ בלא מותרות לא יוליד דבר חדש רק כמו שהוא לבד די להפקיע א\"ע ולא יוכל להשפיע [ל]חוץ ממנו בהתחדשות יש מאין [כלל)]. וכך יובן למעלה בבחי' מותרי מו\"ס שמשם מקבל אור החכ' ביניקה דרך מזל ונוצר חסד שזהו נק' בחי' תולדה שנולד ונמשך אור חדש דחכ' מאין ליש, אע\"פ שחכ' זו באה בהשגה דבינה בהגבלה מ\"מ חדש הוא מעיקרו שלא הי' נולד [זה] גם [מ]כח השכל בעצם שנק' ח\"ס עצמו רק מבחי' מותרי המוחין שלו דוקא, כמזל ונוצ\"ר בשערה בצומח לבד לפי ששרשו באור הכתר עצמו שהוא בחי' מקיף דמו\"ס. וזהו הכל תלוי במזל<sup data-n=\"9705\">880</sup> דוקא אפי' ס\"ת בהיכל שזהו יחוד פנימי דאו\"א בתושב\"כ ותושבע\"פ שתלוי רק במזל העליון שהוא למעלה מאו\"פ דח\"ס שבוקע ויוצא בבחי' מותרות כנ\"ל. וזהו שארז\"ל דנובלות חכ' שמ\"ע דוקא תו'<sup data-n=\"9706\">881</sup>, שנובלות הללו למעלה מגופה של חש\"מ מטעם הנ\"ל). וזהו ענין דאו\"א יונק ממזל הח' דונוצר דגם שאינו <span data-k=\"pg\">רפט</span> ּ רק גילוי אור דחכ' דתורה מאין ליש [ו]יניקה זאת באה בהעלם וצמצום גדול ממותרי מו\"ס דא\"א אבל שרשו למעלה מח\"ס מטעם הנ\"ל, וא\"כ יובן ממילא שזהו למעלה גם מבחי' המדות שברצון שהוא כמו אה\"ר העצמי' הנ\"ל שמתלבש בשכל וטעם שאין זה השכל והטעם מתהוה עיקר מציא[ו]ת החסד [ו]אהבה זו רק שמתלבש בלבוש זה הטעם שכבר יצא מן ההעלם דח\"ס לגילוי, אבל הרי שרש[ה] מדות דחו\"ג שבכתר אינו רק מבחי' טעם הכמוס לרצה\"ע הנ\"ל שזהו כמו עצם כח השכל שמטה לרצון למעלה מטעם [גילוי כ]נ\"ל. אבל בחי' מזל זה ונוצר שממנו שרש התהוות עצם אור החכ' מאין ליש אע\"פ שבא בדרך דילוג הערך בבחי' מותרי מוחין דשערות בלבד, מ\"מ הרי שרשו מלמעלה מגוף המו\"ס וכ\"ש מבחי' המדות דחו\"ג שברצון שמתחלקים מכח דח\"ס הנק' טעם כמוס כנ\"ל מטעם הנ\"ל בכח בחי' המוליד כו' וד\"ל (וזהו שרש החכ' דתו' במ\"ת שנדמה להם כזקן<sup data-n=\"9707\">882</sup> כו' (כמשי\"ת), דבחי'<sup data-n=\"9708\">883</sup> חכמת אדם תאיר פניו<sup data-n=\"9709\">884</sup> מאור הכתר דוקא שהוא העלם עצמו' הרצון הפנימי' והתענוג העצמי שבמצות [ש]בבחי' ארחין דגלגלתא<sup data-n=\"9710\">885</sup> שבוקע ויוצא במו\"ס במזל ונוצר בהגדלה וריבוי גדול מאד, והוא חידוש אור החכ' [ובינה] בחידוש גמור מאין ליש שמרבה תולדות רבות לאין שיעור [ב]יחו\"ע דמצות שלא הי' כח זה בגוף המוחין דח\"ס דאוא\"ס<sup data-n=\"9711\">886</sup> גם בחה\"ק דא\"ק עד רום המעלות שזהו ענין נובלות חש\"מ דלשבח קאמר כנ\"ל וד\"ל).",[["9705","880","<b>הכל תלוי במזל</b>: נסמן לעיל פ' שמות יא, א."],["9706","881","<b>דנובלות חכ' שמ\"ע. . תו'</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["9707","882","<b>במ\"ת שנדמה להם כזקן</b>: נסמן לעיל קסח, א."],["9708","883","<b>דבחי'</b>: ויז: דכתיב."],["9709","884","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["9710","885","<b>שבמצות. . ארחין דגלגלתא</b>: ראה גם לעיל פ' שמות ח, א. וש\"נ."],["9711","886","<b>דח\"ס דאוא\"ס</b>: ויז: דחכ' דא\"א."]]],[2300540998,"(ךד) <b>וזהו</b> שארז\"ל דבים נדמה להם כבחור<sup data-n=\"9712\">887</sup> איש<sup data-n=\"9713\">888</sup> מלחמה כמ\"ש ה' איש מלחמה<sup data-n=\"9714\">889</sup> ובמ\"ת נדמה להם כזקן עוסק במלחמה של תו[רה כו']. דהנה אמ' תפארת בחורים כחם<sup data-n=\"9715\">890</sup> והדר זקנים שיבה דעיקר כח וגבורה דבחי' הנ\"ל<sup data-n=\"9716\">891</sup> הוא במדות הטבעי' לבד, וזהו שא' תפארת בחורים הוא בכחם העצמי והטבעי שהן מדות שברצון העצמי הנ\"ל עד שמחמת תוקף כח המדות הללו שקשים ותקיפים מאד כארז יוכל למצוא גם בכח שכלו זכות וחסד לגבור על מדה\"ד לעמוד נגד שונאו המקטרג על אוהבו או בנו, ואמנם אין כח המצאת שכל זה יהי'<sup data-n=\"9717\">892</sup> לחסד לעמוד ולסתור המנגד לו בא מכח עצם שכלו שקטן הוא עדיין [להיות] שהוא בחור עדיין ורך בשנים, וכתי' ימים ידברו ורוב שנים יודיעו חכ'<sup data-n=\"9718\">893</sup> (וע\"כ לא הי' בסנהדרין אלא זקנים<sup data-n=\"9719\">894</sup> דוקא ולא נערים הגם שהן חריפין, כי אין חריפות שכלם בא רק מצד רתיחת תוקף המדות הטבעי' שלהם שמטה את הכח השכל לזכות כנ\"ל). וזהו שבקי\"ס נדמה להם כבחור כו'<sup data-n=\"9720\">895</sup> כמ\"ש ה' איש מלחמה, כי הנה ביצ\"מ נק' בנים [ב]בחי' הקטנות כתינוק בן יומו שנולד כמ\"ש ואעבור עליך<sup data-n=\"9721\">896</sup> [כו'] וכתי' רבבה כצמח השדה כו' ותרבי ותגדלי<sup data-n=\"9722\">897</sup> כו' שאז בצרתם לו צר<sup data-n=\"9723\">898</sup> כבי', וגברו רחמי האב בבחי' תוקף וכח חזק של המדות הטבעי' שברצון כאה\"ר העצמי' הנ\"ל שלמעלה מן הטעם ושרש המדות שבלב הוא במדות העצמי' הנ\"ל, ומחמת תוקף [כח] המדות הללו הכריע גם לבחי' מקור המוחין העליונים דחו\"ב דאצי' במדות דז\"א שנק' איש<sup data-n=\"9724\">899</sup> להיות מטה כלפי חסד יותר ולגבור על מדה\"ד שטען מה נשתנו אלו מאלו [כו'] ואין העיקר בהטי' זו <span data-k=\"pg\">580</span> ּ רק מבחי' האהבה<sup data-n=\"9725\">900</sup> העצמי' רק שמתלבש בלבוש שכל וטעם לזכות הנ\"ל. וזהו תפארת בחורים כחם במדות העצמי' לגבור גם כח השכל מן ההעלם לגילוי כו', וזהו ה' איש מלחמה לגבור בחי' ימין דחסד על השמאל וכמ\"ש ימינך ה' כו' כנ\"ל. אבל במ\"ת נדמה להם כזקן שקנה חכ' ממקורה דהיינו בבחי' המקיף עליון דמו\"ס דא\"א כו' שזהו מקור אור דתו' שיולד<sup data-n=\"9726\">901</sup> בבחי' נובלות דחש\"מ להתלבש בעה\"ד טו\"ר, כמו יו\"ד הדברות שאינו מדבר רק בסו\"מ וע\"ט בעניני' גשמי' שמזה נעשה למעלה יחו\"ע בתוס' אורות באצי' כו' למעלה מכפי מאמר קו המדה. וזהו שנק' גבור במלחמתה של תו' דוקא לגבור כח הח\"ס<sup data-n=\"9727\">902</sup> אף בעצמו' הרצון שנמשך מלמעלה גם מבחי' טעם כמוס לרצון להיות בחי' דעת<sup data-n=\"9728\">903</sup> נוטה לחסד יותר, והוא בחי' ד\"ע דתו' שירדה למטה דוקא",[["9712","887","<b>דבים נדמה להם כבחור</b>: נסמן לעיל קסח, א."],["9713","888","<b>איש</b>: ויז: עושה."],["9714","889","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["9715","890","<b>תפארת בחורים כחם</b>: משלי כ, כט."],["9716","891","<b>דבחי' הנ\"ל</b>: ויז: דבחורים."],["9717","892","<b>יהי'</b>: שם: ליתא."],["9718","893","<b>ימים ידברו. . חכ'</b>: איוב לב, ז."],["9719","894","<b>בסנהדרין אלא זקנים</b>: ראה סנהדרין יז, סע\"א. רמב\"ם הל' סנהדרין פ\"ב, ה\"ו. לקמן פ' משפטים ש, ג. מאמרי אדה\"א ויקרא ח\"א ע' רמד. נ\"ך ע' תקיט. אמ\"ב שער התפילין קל, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670312\" data-slug=\"torat-chaim\" data-id=\"2300670312\">תו\"ח בראשית יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171138\" data-slug=\"likkutei-sichot\" data-id=\"1300171138\">לקו\"ש תזריע (כרך יז) ע' 138</a> הערה 59. כ' מנ\"א (כרך כט) ע' 264 הערה 14."],["9720","895","<b>כו'</b>: ויז: כבי'."],["9721","896","<b>ואעבור עליך</b>: יחזקאל טז, ו."],["9722","897","<b>רבבה. . ותגדלי</b>: יחזקאל שם, ז."],["9723","898","<b>בצרתם לו צר</b>: ראה לעיל פ' וארא נא, ד."],["9724","899","<b>דז\"א שנק' איש</b>: ע\"ח (שער הצלם) שכ\"ו, פ\"ג."],["9725","900","<b>מבחי' האהבה</b>: ויז: מכח אה\"ר."],["9726","901","<b>שיולד</b>: שם: שיוצא."],["9727","902","<b>הח\"ס</b>: שם: החסד."],["9728","903","<b>דעת</b>: שם: ד\"ע."]]],[2300541003,"בגבורה וכח חזק יותר מעצם המוחין שנק' טעם כמוס והיינו בחי' גבו' דע\"י שמלובש בח\"ס<sup data-n=\"9729\">904</sup>, שמזה שרש התו' לברר לעה\"ד טו\"ר דוקא כמו קול ה' בכח<sup data-n=\"9730\">905</sup> כו' ולאכללא שמאלא בימינא<sup data-n=\"9731\">906</sup> להמתיק הגבו' בחסד[ים] דאור תורה שזהו למעלה ממלחמה דכח הבירורים<sup data-n=\"9732\">907</sup> במדות הטבעי' שברצון עצמו. וזהו והדר זקנים שיבה שהוא בחי' הזקנה שבוקע מצד מותרי מוחין שבא מתגבורת האור מבחי' מקיף דנר\"נ כמאמר דסבא דעתיקא סתים<sup data-n=\"9733\">908</sup> למעלה מבחי' הקרומא דאוירא הנ\"ל שע\"כ יתגבר בכח ומקור החכ' להביא כל ההעלם לגילוי כו' שהוא למעלה ממדות שמתחלקי' ברצון ומו\"ס עצמו מטעם הנ\"ל וד\"ל. וזהו מדלג על ההרים כו' דביצ\"מ הי' דילוג גם למעלה ממדות דכתר הנ\"ל אע\"פ שהי' בזה גם זכות אבות ששרשן בחג\"ת דא\"א<sup data-n=\"9734\">909</sup> כו' וכמ\"ש וגם הקימותי<sup data-n=\"9735\">910</sup> כו' אך כדי שיוכלו לבוא למ\"ת שלמעלה מזה כנ\"ל הי' מוכרח לדלג על ההרים כו' והוא מ\"ש [ו]שמי הוי' לא נודעתי כו'<sup data-n=\"9736\">911</sup> כידוע וד\"ל. וזהו רבבה כצמח השדה כו' בבחי' קטנות המוחין שלמטה מן הדעת כמו תינוק שצועק לאביו ולאמו בלי דעת כו' כמ\"ש מתבוססת בדמיך כו', אך במ\"ת בודאי<sup data-n=\"9737\">912</sup> למעלה במקור המו\"ס<sup data-n=\"9738\">913</sup> בגדלות המדות דתו' שנק' גדלות שני דאבא כו' שהוא מה שהי' אור אבא יונק ממזל כו' ונעשה מיניקה זו בבחי' גדלות יותר מבחי' חש\"מ עצמה מטעם הנ\"ל, ועכ\"ז מלחמה דקי\"ס במדות הטבעים הי' בחי' הכנה למלחמתה של תו' [במ\"ת] שנדמה להם כזקן כו', שזהו מ\"ש במט\"ט שרו של עולם נער הייתי גם זקנתי<sup data-n=\"9739\">914</sup> בכלות ו' אלפי שנין<sup data-n=\"9740\">915</sup> בעוה\"ז וגם בקי\"ס שהי' נדמה להם כבחור כו' ואמר זה אלי כו' נעשה כזקן במ\"ת [ו]כמו בכנ\"י דכתי' ותרבי ותגדלי כו' [ו]כמ\"ש גפן ממצרים תסיע<sup data-n=\"9741\">916</sup> כסו הרים צלה<sup data-n=\"9742\">917</sup> וכך הוא במדות<sup data-n=\"9743\">918</sup> דז\"א דאצי' שנק' ישראל דלעילא שזהו בצאת ישראל ממצרים ממיצר מ\"י [ו]ים דחו\"ב דאצי' בבחי' לידה כו' והגדיל בגדלות המוחין דאור אבא במ\"ת אחר גידול דאימא בימי הספי' שהי' בבחי' מוחין דיניקה (כמו שאור אבא יונק ממזל כו' וד\"ל).\n<b>אך</b> הנה אחר כ\"ז עדיין אינו מתיישב בכ\"ז איך הי' קי\"ס הכנה למ\"ת דוקא ובסדר כמו שהי' כמ\"ש <span data-k=\"pg\">רצ</span> ּ ויסע מלאך<sup data-n=\"9744\">919</sup> ויבא ויט כו' אחר שהי' מלחמה זו רק במדות שברצון שנק' מדות טבעים (והן ימי הספירה שהן בז' מדות הטבעים לבררם ועי\"ז דוקא [י]גיע[ו] לגילוי אור פב\"פ במ\"ת כידוע). אך הנה באמת הגם",[["9729","904","<b>גבו' דע\"י שמלובש בח\"ס</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ו-ז."],["9730","905","<b>קול ה' בכח</b>: תהלים כט, ד."],["9731","906","<b>ולאכללא שמאלא בימינא</b>: נסמן לעיל פ' בא קיח, ד."],["9732","907","<b>הבירורים</b>: ויז: בחורים."],["9733","908","<b>דסבא דעתיקא </b>[ו: דעתוהי]<b> סתים</b>: ראה זהר (אד\"ר) נשא קכט, ב. אמ\"ב שער התפילין קל, ד."],["9734","909","<b>אבות ששרשן בחג\"ת דא\"א</b>: נסמן לעיל קנח, ב."],["9735","910","<b>וגם הקימותי</b>: וארא ו, ד."],["9736","911","<b>ושמי ה' לא נודעתי כו' </b>[ויז: להם]: נסמן לעיל פ' שמות א, ג הערה 42."],["9737","912","<b>בודאי</b>: ויז: הגדילו."],["9738","913","<b>המו\"ס</b>: שם: החכמה."],["9739","914","<b>במט\"ט. . נער הייתי גם זקנתי</b>: תהלים לז, כה. ראה יבמות טז, ב ובתוס' שם. מאמרי אדה\"א שמות ח\"א ע' קג. דברים ח\"ג ע' תשפט ובהנסמן בהנ\"ל. ש\"א טו, ב ובהערה 27. לקמן פ' משפטים רצב, ב ואילך."],["9740","915","<b>ו' אלפי שנין</b>: ר\"ה לא, א. ראה הנסמן במאמרי אדה\"א בראשית ע' נג."],["9741","916","<b>גפן ממצרים תסיע</b>: תהלים פ, ט."],["9742","917","<b>כסו הרים צלה</b>: תהלים שם, יא."],["9743","918","<b>במדות</b>: ויז: בגדלות."],["9744","919","<b>מלאך</b>: שם: ליתא."]]],[2300541008,"שבמדות שברצון העצמי הנ\"ל המה מתחלקים מבחי' מו\"ס דא\"א שנק' טעם כמוס לרצה\"ע הזה עכ\"ז שרשן האמיתי הוא למעלה גם מבחי' טעם כמוס הזה, כמו שעצם רצון [העליון] במצות ש[ב]גולגלתא דא\"א כנ\"ל הוא למעלה גם מבחי' טעם כמוס המחלק [ו]מטה לרצון בחו\"ג כו' (כמשי\"ת), והיינו בעצמו' דאור הכתר שנק' גולגלתא דחפיא על מוחא<sup data-n=\"9745\">920</sup> דא\"א כידוע שנק' כתר שבכתר<sup data-n=\"9746\">921</sup> (שע\"ז א' דאפי' אור צח [כו'] אוכם הוא כו' כנ\"ל), ולמטה זהו כמו בחי' יחידה שבנפש עצמה שבה יש ג\"כ בחי' המדות הללו והן בחי' מדות עצמי' ממש (כמשי\"ת). והיינו מ\"ש בקי\"ס מה תצעק אלי בעתיקא עצמו תליא שזהו בחי' עצמו' התענוג ורצון הפשוט הנ\"ל שלמעלה מח\"ס כו', וע\"ז א' בזהר דז\"א בע\"י אחיד ותליא דהיינו בבחי' אור דעתיקא עצמ[ו] והוא שנק' עתיקא סתימאה כמו<sup data-n=\"9747\">922</sup> שלמעלה מבחי' מו\"ס וכ\"ש מבחי' העלם<sup data-n=\"9748\">923</sup> המזלות דמו\"ס שהוא שרש החכ' דתו' אור לגילוי למטה כמו שהי' במ\"ת כנ\"ל וד\"ל, ולזאת ממילא [י]ובן מזה דקי\"ס שהי' מלחמה זו במדות עצמי' ממש דבעתיקא עצמו כמ\"ש בע\"י תליא ע\"כ הי' מלחמה זאת דוקא הכנה רבה למ\"ת שהי' במדות דח\"ע דתורה כנ\"ל (כמשי\"ת).\n(ךה) <b>ולהבין</b> ביאור הענין הזה, הנה ידוע דהנפש עצמה נק' בשם יחידה<sup data-n=\"9749\">924</sup> לשון יחידות שאין [בה] בחי' הטיות כלל ואין בה הסתעפות כח דבר מה במורכב כלל אלא הוא אור פשוט ועצמי וע\"כ אין בה התחלקות קוין לימין ושמאל בגילוי כלל ולכך נק' בשם יחידה, והוא בחי' מקיף דנר\"נ הכללי שז\"ש אך בצלם כו' מ\"ם דצלם<sup data-n=\"9750\">925</sup> כו' (שלמעלה מבחי' מקיף דחי' שנק' צל או מזלא כמו מזלי' חזי<sup data-n=\"9751\">926</sup> שבא בגילוי מן ההעלם). והנה לכאורה אנו רואים שיש גם בחי' מדות בנפש עצמה (כמו שכלול בה כח השכל [ה]עצמ[י] שנק' כח המשכיל [ה]היולי כו' ולכך נק' ג\"כ נפש השכלי'<sup data-n=\"9752\">927</sup> נפש המדברת<sup data-n=\"9753\">928</sup> כידוע) והוא הרצון שהוא שרש המדות שבלב באוירא<sup data-n=\"9754\">929</sup> כו', שהרי הרצון נק' בשם נפש<sup data-n=\"9755\">930</sup> כמו היש את נפשך<sup data-n=\"9756\">931</sup> כלומר רצונ[ך], אין נפשי<sup data-n=\"9757\">932</sup> [א]ל [ה]עם הזה<sup data-n=\"9758\">933</sup> כו', וכן פי' בכל נפשך<sup data-n=\"9759\">934</sup> היינו בכל רצונך כו' כי מדת האהבה בלב [ש]הוא הרצון<sup data-n=\"9760\">935</sup> מגיע עד כל עצמות הנפש ממש כמו כי תדרשנו<sup data-n=\"9761\">936</sup> בכל לבבך ובכל נפשך<sup data-n=\"9762\">937</sup>. והטעם הוא כי התפעלות הרצון אעפ\"י שנק'",[["9745","920","<b>מוחא</b>: שם: מו\"ס."],["9746","921","<b>גולגלתא. . כתר שבכתר</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ג. לקמן פ' תצוה שנה, ב. מאמרי אדה\"א בראשית ס\"ע ריב."],["9747","922","<b>כמו</b>: ויז: כו'."],["9748","923","<b>העלם</b>: שם: ליתא."],["9749","924","<b>דהנפש. . בשם יחידה</b>: ראה ספרי האזינו לב, י."],["9750","925","<b>מ\"ם דצלם</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תצט ואילך."],["9751","926","<b>מזלי' חזי</b>: מגילה ג, א."],["9752","927","<b>נפש השכלי'</b>: ראה גם לעיל פ' בא קא, ג. וש\"נ."],["9753","928","<b>נפש השכלי' נפש המדברת</b>: ראה גם לעיל פ' שמות מז, ב."],["9754","929","<b>באוירא</b>: ויז: כאוי\"ר."],["9755","930","<b>הרצון נק' בשם נפש</b>: נסמן לעיל פ' וארא עט, ג."],["9756","931","<b>היש את נפשך</b>: חיי שרה כג, ח־ מלכים-ב ט, טו [ושם: אם יש (את) נפשכם — ראה לקמן פ' תצוה שעח, א. מאמרי אדה\"א בראשית ע' שלט. וש\"נ. שע\"ת נג, ב ובהערה 28]."],["9757","932","<b>היש את נפשך. . אין נפשי</b>: ראה לקו\"ש לך (כרך ב) ע' 456 בהערה."],["9758","933","<b>אין נפשי [א]ל [ה]עם הזה</b>: ירמי' טו, א ובתרגום־ רש\"י ורד\"ק שם."],["9759","934","<b>בכל נפשך</b>: ואתחנן ו, ה."],["9760","935","<b>האהבה בלב [ש]הוא הרצון</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשמט. לעיל קצט, א ובהערה 769."],["9761","936","<b>כי תדרשנו. . נפשך</b>: ואתחנן ד, כט."],["9762","937","<b>נפשך</b>: ויז: הנפש."]]],[2300541013,"מדה בהתפעלו' הרצון באה\"ר כו' אבל יכולה להתפשט בכל נפשך עצמה דהיינו שכל הנפש תכלה ברצון וחלק<sup data-n=\"9763\">938</sup> זה לדבר האהוב לו ביותר, כמו ביונתן ודוד [ד]כתי' [כי] אהבת נפש[ו] אהבו<sup data-n=\"9764\">939</sup>, וכן ונפשו קשורה בנפשו<sup data-n=\"9765\">940</sup> כו', [ו]כמו ותדבק נפשו בדינה<sup data-n=\"9766\">941</sup> [כו'] כי חפץ בבת יעקב<sup data-n=\"9767\">942</sup> כו' (עד שיחלה חולת אהבה כו'). והוא ענין מרוצה שברצון זה שגובר כח עצם הנפש עד שתחפוץ<sup data-n=\"9768\">943</sup> בכל כח ועוז ממש עד שתכלה כמו כלתה נפשי<sup data-n=\"9769\">944</sup> כו', שזהו פי' רצון לשון מרוצה כמו משכני אחריך נרוצה<sup data-n=\"9770\">945</sup> וכן א' בס\"י אם רץ לבך<sup data-n=\"9771\">946</sup> כו', וזהו מדת עצמי' האהבה הנטוע[ה ו]המושרשת בעצם הנפש ממש שנק' יחידה דוקא <span data-k=\"pg\">582</span> ּ כאהבת האב לבן וכה\"ג מבן לאביו. וממילא מובן שיש בבחי' יחידה זו גם בהיפוכו ממש, והוא מבחי' היראה ופחד שנוגע בעצמו' הנפש ממש כמו מדבר המזיק וממית לנפשו שבורח ממנו בתכלית שאינו חפץ למות כמו שחפץ בחיים ממש בשוה, וכן ישנא הדבר המנגד אליו בתכלית כשונא גמור שכעס<sup data-n=\"9772\">947</sup> עליו [כו'] בתכלית שנאה עצמי' כמו היפוכו באה\"ר כו'. וא\"כ הרי יש עכ\"פ משקל ב' מדות הפכים דחו\"ג ממש רק שהן מושרשים ונטועי' בעצמות הנפש דיחידה ממש. וממילא מובן שיש גם בנפש עצמה שנק' יחידה בחי' הטיית והתחלקו' לב' קוין [ד]חו\"ג עכ\"פ, וא\"כ למה נק' יחידה שאין בה שום הטיי' כלל ולא הסתעפות והתחלקות כלל<sup data-n=\"9773\">948</sup> כנ\"ל, אלא שאין ניכרים במציאות וכלולים בה ממש (כאהבת חיי נפשו שחפץ בחיים ולא ירצה למות שבכלל<sup data-n=\"9774\">949</sup> כא' ממש בנפשו), וזהו בחי' רו\"ש שבעצמות הנפש. וכך הי' באמונה הפשוטה העצמ[י]' שהי[א] בג\"ר דכ[תר] שהי' הדם על המשקוף וב' המזוזות<sup data-n=\"9775\">950</sup> שע\"ז א' בדמייך חיי<sup data-n=\"9776\">951</sup> בחיי האלקי' העצמי' בכנ\"י שעי\"ז קבלו במ\"ת בבחי' התקשרו' העצמו' דבחי' יחידה זו בהתכללות דחו\"ג שבה שהם לחפוץ בחיי החיים במ\"ע ולסור מרע ומות, כמו ואהבת<sup data-n=\"9777\">952</sup> את הוי'<sup data-n=\"9778\">953</sup> כי הוא חייך<sup data-n=\"9779\">954</sup> ממש העצמי כו', והוא אנכי ולא יהי' לך בכלל שכלולי' במ\"ע ול\"ת<sup data-n=\"9780\">955</sup> ששרשם בעצמו' א\"ס ב\"ה ממש<sup data-n=\"9781\">956</sup> שנק' יחיד חי העולמים<sup data-n=\"9782\">957</sup> כו' כמו שכנ\"י מלמטה למעלה נק' יחידה או אחת כמ\"ש אחת היא שהוא כלי לאח\"פ<sup data-n=\"9783\">958</sup> כו', והוא בחי' האמונה בחי' יחידה שבנפש העצמי' הפשוטה כו' שמחמת זה יכולי' למסו\"נ עקה\"ש או שגם הרשע גמור יעשה תשובה ויתהפך מן הקצה אל הקצה במדות הטבעי'",[["9763","938","<b>וחלק</b>: שם: וחשק."],["9764","939","<b>[כי] אהבת נפש[ו] אהבו</b>: שמואל-א כ, יז."],["9765","940","<b>ונפשו קשורה בנפשו</b>: ויגש מד, ל."],["9766","941","<b>ותדבק נפשו בדינה</b>: וישלח לד, ג."],["9767","942","<b>כי חפץ בבת יעקב</b>: וישלח שם, יט."],["9768","943","<b>שתחפוץ</b>: ויז: שתרוץ."],["9769","944","<b>כלתה נפשי</b>: תהלים פד, ג."],["9770","945","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."],["9771","946","<b>בס\"י אם רץ לבך</b>: פ\"א, מ\"ח."],["9772","947","<b>שכעם</b>: ויז: שקם."],["9773","948","<b>כלל</b>: שם: כו'."],["9774","949","<b>שבכלל</b>: שם: שכלול."],["9775","950","<b>הדם על המשקוף וב' המזוזות</b>: בא יב, ז. כב. כג."],["9776","951","<b>שע\"ז א' בדמיך חיי</b>: יחזקאל טז, ו. ראה לעיל פ' בא צא, ד. צב, ב."],["9777","952","<b>ואהבת</b>: ויז: לאהבה."],["9778","953","<b>ואהבת את הוי'</b>: ואתחנן ו, ה. עקב יא, א."],["9779","954","<b>לאהבה. . כי הוא חייך</b>: נצבים ל, כ [בדילוג]."],["9780","955","<b>אנכי ולא יהי' לך. . במ\"ע ול\"ת</b>: נסמן לעיל פ' שמות יז, ג הערה 722."],["9781","956","<b>ממש</b>: ויז: ליתא."],["9782","957","<b>יחיד חי העולמים</b>: נוסח ברכת ברוך שאמר וישתבח."],["9783","958","<b>אחת היא שהוא כלי לאח\"פ</b>: שה\"ש ו, ט. נסמן לעיל פ' שמות יז, ב."]]],[2300541018,"כו', והוא המשקוף המחבר ב' המזוזות דימין ושמאל שכלולי' יחד ומחברם יחד כציור ח'<sup data-n=\"9784\">959</sup> (כמ\"ש במ\"א).\n<b>אך</b> הענין הוא דגם שיש מדות דחו\"ג בנפש עצמה שנק' יחיד\"ה עכ\"ז הם כלולים ובטלי'<sup data-n=\"9785\">960</sup> בעצמות[ה] ממש שהנפש עצמה למעלה גם מב' מדות דחו\"ג העצמי' ממש הכלולים בה, כי הרצון הוא שם התואר למציאת דבר מה, כמו כשרוצה בדבר מה אף שירצה בכל נפשו או [ש]יתענג באיזה דבר בכל עצמו' נפשו אין [זה] רק כחות<sup data-n=\"9786\">961</sup> עצמו' של הנפש אבל לא שזהו מהו\"ע הנפש, שאין הנפש בבחי' מציאות דמזלא<sup data-n=\"9787\">962</sup> בבחי' מהות רצון או עונג רק כמו אור היולי ופשוט (ואע\"פ שא' אין לך למעלה מן העונג<sup data-n=\"9788\">963</sup> [א]ו הרצון זהו במעלות ומדרגות בכח[ות] הנפש בלבד אמנם אין זה מגיע בעצמו' אור פשיטותה בעצמי'<sup data-n=\"9789\">964</sup> כו'. וראי' לזה הוא ממה שאנו רואים שיש בכח הנפש עצמה למשול על הרצון או עונג הטבעי ועצמי ג\"כ לעשות מהיפך להיפך כמו לקבל יסורים וצער לעונג גדול ועונג גדול לצער ויסורים לנפש, כמו שיוכל למאוס בכל תענוגי הנפש ולהסיר הרצון הטבעי מהם עד שכיסורים גמורים הם ו[י]קבל סיגופים לעונג כמו לחבל בעצמו ולהפקיע<sup data-n=\"9790\">965</sup> א\"ע בכדי שיזכה נפשו באור החיים עד שזהו לעינוי<sup data-n=\"9791\">966</sup> גדול בנפש[ו], וכן יכול לשנוא לאוהבו ולאהוב לשונאו בהיפך מטבעו ממש, כמו בעת שיתגדל ויתרומם מאד שיהפך לבבו מן הקצה כו' וישפיל גיאים ויגביה שפלים עד שיוכל לקרב לשונאו ולרחק<sup data-n=\"9792\">967</sup> לאוהבו, כמ\"כ בעת שמחת לבבו <span data-k=\"pg\">רצא</span> ּ ביותר יוכל לאהוב לשונאו כו' לפי שנתרומם נפשו בעצמי' דיחידה ששם יכול להתהפך ג\"כ במדות הטבעים מן הקצה לקצה ממש. וכמו שאנו רואים בחוש באיש כילי וקמצן<sup data-n=\"9793\">968</sup> גדול שנהרג על פחות מש\"פ מפני שנוגע לחיי עצמו' נפשו ממש לפי שממונו חביב עליו מגופו כו' וכל שכלו ומדותיו [הכל] מיוסדים בטבע זו שמוטבע בנפשו בעצם, ועכ\"ז בעת שמחת לבו ביותר כמו בעת חתונת בנו שעושה משתה בנשואי בנו יחידו וכה\"ג אזי נהפך לבו לאיש אחר לשנות מדותיו הטבעים מן הקצה אל הקצה, להיות לבו כמו לב נדיב וחסדן ממש לפזר כל הון ולהפריז על המדה לעשות הוצאה יתירה שישבעו ויאכלו מטובו<sup data-n=\"9794\">*969</sup> אף שזהו נגד טבעו ממש, והוא לפי שנתעלה אז נפשו בעצם התענוג הגדול שמתענג בנפשו בבחי' יחידה שבה שלמעלה מגדר טבעו עד שיוכל להפוך מהותו וטבעו ממש מן הקצה אל הקצה. וזהו מצד בחי' מקיף דתענוג העצמי שבנפש שמקיף לכל סדר השתלשלו' דנר\"נ דמוחין ומדות שלו שכלי' וטבעי' עד שכל מוחו ודעתו",[["9784","959","<b>המשקוף. . כציור ח'</b>: ראה לעיל צא, סע\"ב ואילך."],["9785","960","<b>ובטלי'</b>: ו: ונטועים."],["9786","961","<b>כחות</b>: ו: בחי' התפשטות."],["9787","962","<b>דמזלא</b>: ויז: דבר מה לא."],["9788","963","<b>אין לך למעלה מן העונג</b>: ס\"י פ\"ב, מ\"ב [מנטובא שכ\"ב] בהוספת תיבת לך. ראה הנסמן במאמרי אדה\"א נ\"ך ע' תפ־ קונטרסים ע' תקסט. שעה\"י קכו, ב."],["9789","964","<b>בעצמי'</b>: ויז: בתכלית."],["9790","965","<b>ולהפקיע</b>: שם: ולהפקיר."],["9791","966","<b>לעינוי</b>: שם: לעונג."],["9792","967","<b>ולרחק</b>: שם: ולהשפיל."],["9793","968","<b>באיש כילי וקמצן</b>: ראה גם להלן רה, א. מאמרי אדה\"א נ\"ך ס\"ע לה ואילך."],["9794","*969","<b>מטובו</b>: ויז: ליתא."]]],[2300541023,"ולבו משתנה הכל ברגע א' מהיפך להיפך ממש עד שיכול לאהוב לשונא ולשנוא אוהבו ג\"כ מטעם הנ\"ל<sup data-n=\"9795\">969</sup> וד\"ל.\n(ךו) <b>ובכ\"ז</b> יובן הנמשל למעלה בבחי' הרצון ותענוג העליון שלמעלה מן החכ' שנק' חכ' שבכתר בחי' טעם כמוס לרצון הנ\"ל שבחי' המדות שנק' חו\"ג יש בב' אופנים, א' כפי שמתחלקי' בהטי' דח\"ס בהכתר<sup data-n=\"9796\">970</sup> הנ\"ל שזהו אופן הגילוי רצון מן ההעלם שיש [בה] שינויי' רבים באופנים הפכים ובעיתים שונים כנ\"ל, וע\"כ אין בחי' הרצון הזה שמורכב עכ\"פ בטעם כמוס כנ\"ל נק' בשם רצון הנפש בעצמה ממש אלא רק בחי' התפשטו' אור הרצון בלבד מעצם הנפש אבל לא [שהוא] רצון של עצם הנפש ממש בבחי' יחידה שבה, כי בחי' הרצון הפשוט של עצם הנפש ממש בבחי' יחידה אין בו שינויים כלל ואינו מתחלק<sup data-n=\"9797\">971</sup> להיפוכו להיות[ו] בבחי' עצמיו' ממש כנ\"ל, ועכ\"ז יש בה ג\"כ ב' קוין דחו\"ג אלא שהן בבחי' עצמיות המדות דנפש עצמה כ[י] מתפשטי' בכל הנפש עד שתכלה לגמרי ברצון של אה\"ר בתענוגי' כלל<sup data-n=\"9798\">972</sup> ולהיפך המנגד לעצמי' שלו כמו הרצון בחיים ולא ירצה [ב]מות כנ\"ל<sup data-n=\"9799\">973</sup>. ולמעלה הן ב' מדות דחו\"ג שבעצמו' אור הכתר שנק' כת\"ר שבכת\"ר שהן בבחי' עצמו' ממש שלמעלה מהתחלקו' המדות הטבעי' שברצון לפעמים כך ולפעמים כך כו'<sup data-n=\"9800\">974</sup>. וזהו שנק' בחי' עתיקא סתימאה<sup data-n=\"9801\">975</sup> שלמעלה ממו\"ס כו' או בחי' רדל\"א או בבחי' הרצה\"פ שבעצמו' ממש שנק' רעדכ\"ר שמאיר במצחא<sup data-n=\"9802\">976</sup> כו', וכללותן הן ב' ראשין דאתגליפו<sup data-n=\"9803\">977</sup> כו' שהן ע\"י וא\"א בחי' התענוג והרצון<sup data-n=\"9804\">978</sup> העצמי הפשוט כו', ובחי' רדל\"א (כמ\"ש בסידור<sup data-n=\"9805\">979</sup> בביאור כוונת<sup data-n=\"9806\">980</sup> דב\"ש), שכולם כוללם<sup data-n=\"9807\">981</sup> ענין א' וכלולי' זה בזה שלפעמים בחי' התענוג והרצון<sup data-n=\"9808\">982</sup> בפנימי' הרצון ונק' חסד<sup data-n=\"9809\">983</sup> שהרי מחמת התענוג שמתענג בדבר זה הוא מתעורר ברצון לרצות בו ואם לא התענוג שמתענג בזה לא הי' רוצה כלל וכמו\"כ יש להיפך ממש שאם אין רצון אין תענוג כלל שאם אינו רוצה בדבר אף האהוב כבנו וכה\"ג אינו מתענג בו כלל. ונמצא שהרצון והתענוג דבר א' הוא ממש מאחר שבדבר שרוצה בו מתענג וע\"י שמתענג הוא רוצה ואין ידוע מי <span data-k=\"pg\">584</span> ּ קודם ומי הוא בפנימי', שלפעמים התענוג בפנימי' והרצון בחיצוני' ולפעמי' בהיפך<sup data-n=\"9810\">984</sup> כו' (כמ\"ש במ\"א). ואמנם הנה מבואר למעלה בשרש המדות שבלב שהוא במדות דע\"י עצמו, וז\"ש בקי\"ס מה תצעק אלי כו' (שהוא בחי' ז\"א) בעתיקא תליא כו' (והוא מלחמה שבמדות הטבעי' שברצון העצמי כנ\"ל) שזהו בעצמות התענוג ועצמות הרצה\"פ כנ\"ל",[["9795","969","<b>הנ\"ל</b>: שם: זה."],["9796","970","<b>דח\"ס בהכתר</b>: שם: דחכ' שבכתר."],["9797","971","<b>מתחלק</b>: שם: מתחלף."],["9798","972","<b>כלל</b>: יז: כנ\"ל."],["9799","973","<b>כנ\"ל</b>: ו: כלל."],["9800","974","<b>כך כו'</b>: א: כך ע\"פ תורה כנ\"ל. הויז: ע\"פ תוס' [יז: תו\"מ] כנ\"ל."],["9801","975","<b>עתיקא סתימאה</b>: ראה גם שה\"א סא, ב ובהערה 29."],["9802","976","<b>רעדכ\"ר שמאיר במצחא</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, ב."],["9803","977","<b>ב' ראשין דאתגליפו</b>: ויז: ג' רישין דאתגליפן — ראה זהר (אד\"ז) האזינו רפח, א. ע\"ח (שער א\"א) שי\"ג, פ\"ב. מאמרי אדה\"א שמות ח\"א ע' מב."],["9804","978","<b>ע\"י וא\"א בחי' התענוג והרצון</b>: ראה גם לקמן רד, סע\"ג ואילך. ש\"א כז, ב. שעה\"י קכו, א ובהנסמן במ\"מ לשם."],["9805","979","<b>בסידור</b>: שחרית לט, ג."],["9806","980","<b>כוונת</b>: ויז: ליתא."],["9807","981","<b>כוללם</b>: ו: כלולים. יז: כוללים."],["9808","982","<b>והרצון</b>: שם: ליתא."],["9809","983","<b>חסד</b>: שם: ח\"ס."],["9810","984","<b>מי קודם. . שלפעמים התענוג. . ולפעמי' בהיפך</b>: ראה שעה\"י ע' קכו ואילך. פיה\"מ סב, ג. מאמרי אדה\"א נ\"ך ע' תפ ואילך (וש\"נ בע' תפב)."]]],[2300541028,"[ש]<b>נק'</b> עתיקא סתימאה שלמעלה מבחי' מו\"ס כו'. וכמו שאנו רואים בחוש במדות הטבעים שבלב שלמטה מן השכל וטעם שבמוח ששרשם הוא בעצם המדות דחו\"ג [ש]בבחי' יחידה הנ\"ל ו[ב]מדות הטבעים הנולדים בטבע מבטן אמו שלא יוכל לשנותם כלל מהיפך להיפך כמו מרחמנות לאכזריות ומפזרנות לקמצנות או להיפך כו' עד שמגיע[ים ה]מדות הללו בעצם הנפש ממש כנ\"ל שהוא בלתי שינויים כלל. וזה הי' ענין המלחמה בקי\"ס במדות הללו שבבחי' ע\"י עצמו. ואמנם בהיפך<sup data-n=\"9811\">985</sup> הי' [ה]כח ועוז שיגבר מדת החסד על מדה\"ד מאחר שב' מדות הללו הם בשיקול א' ממש בעצמו כנ\"ל בב' קוין ההפכים ומה גם<sup data-n=\"9812\">986</sup> שכלולים בבחי' יחידה הנ\"ל. הענין הוא כמבואר למעלה [ד]בחי' עצם הנפש דיחידה עצמה למעלה גם מב' המדות הללו ההפכים ומה גם שכלולי' כא' ממש עד שיוכל להפוך המדות העצמי' הללו ג\"כ מן הקצה אל הקצה כמו בעת שמחת לבו כנ\"ל.\n<b>וכך</b> יובן למעלה אע\"פ שאין לו דמיון מציור הנפש אדם כו' כמ\"ש כי לא אדם הוא<sup data-n=\"9813\">987</sup> כו' ועכ\"ז י\"ל בערך ודוגמא בעלמא מבשרי אחזה<sup data-n=\"9814\">988</sup> כו' דבצלם אלקי'<sup data-n=\"9815\">989</sup> כידוע, וזהו [ענין] בחי' יחיד שלמעלה מבחי' אחד<sup data-n=\"9816\">990</sup> כמאמר אנת הוא חד ביחוד הפשוט ולא בחושבן<sup data-n=\"9817\">991</sup> י\"ס, דאחד היינו ע\"ס שמיוחדי' בעצמו' המאציל כידוע, וכללות הע\"ס הוא בחי' הכתר בכלל שהוא בחי' ע\"י וא\"א שהן ב' מדרגות דרצון ועונג כנ\"ל [ו]אע\"פ שהמדות שבכתר עצמו הן בלתי מוגבלים מ\"מ הן ב' בחי' קוין עכ\"פ, אבל בעצמו' המאציל א' לאו מכא\"מ כלל<sup data-n=\"9818\">992</sup> אפי' מדות שברצון ועונג שבעצמו' שלמעלה מן החכ' כי הוא ית' בעצמו מושלל מכל שם ותואר המורכב במציאות<sup data-n=\"9819\">993</sup> דבר מה אף לא בבחי' מציאות עונג ורצון, כמ\"ש כי עמך מקור חיים<sup data-n=\"9820\">994</sup> כו' פי' מקור כל התענוגי' העליונים ואפי' העוה\"ב שהוא העדן (כמאמר ביו\"ד לבד נברא העוה\"ב כידוע וד\"ל). וזהו שנק' יחיד באח\"פ בתכלית כמו שכנ\"י נק' יחידה למטה או אחת כו', ולזאת מה שיש בחי' התחלקות ברצון ועונג העצמי ב' קוין דימין ושמאל בחו\"ג בכלל כנ\"ל נכללים ובטלים בעצמותו ית' ממש, ולפי שמהו\"ע ית' הוא עצ[ם] הטוב והחסד הפשוט ע\"כ משם יומשך כח ועוז לגבור כח החסד שברצה\"ע על כח הדין, והיינו מצד בחי' אה\"ר העצמי' לנש\"י שמתקשראן כו'<sup data-n=\"9821\">995</sup> בבחי' התקשרות עצמ[י]' הנפש ממש כמו למס\"נ עקדה\"ש, כמו באברהם שמצא לבבו נאמן לפניך<sup data-n=\"9822\">996</sup> בנסיון לעמוד על נפשו ולהשלימה<sup data-n=\"9823\">997</sup> נגד רצון ה' כמו לשחוט בנו יחידו שכבש רחמיו<sup data-n=\"9824\">998</sup> לעשות רצון קונו כו' שזהו להפך הטבעי' מצד בחי' התקשרות דיחידה. וכך הי' בכנ\"י בגלות מצרים במס\"נ ממש באמונה פשוטה העצמי' כו' (ש[ז]הו",[["9811","985","<b>בהיפך</b>: ויז: מהיכן."],["9812","986","<b>ההפכים ומה גם</b>: שם: דחו\"ג."],["9813","987","<b>כי לא אדם הוא</b>: שמואל-א טו, כט."],["9814","988","<b>מבשרי אחזה</b>: נסמן לעיל פ' בא צח, ב."],["9815","989","<b>דבצלם אלקי'</b>: בראשית א, כז. נח ט, ו."],["9816","990","<b>יחיד שלמעלה מבחי' אחד</b>: נסמן לעיל פ' שמות מז, א."],["9817","991","<b>אנת הוא חד. . ולא בחושבן</b>: ת\"ז בהקדמה (יז, א)."],["9818","992","<b>לאו מכא\"מ </b>[ו: מכל אינון מדות]<b> כלל</b>: ראה ת\"ז שם (יז, ב)."],["9819","993","<b>במציאות</b>: בתו\"ח כאן ניתוסף: שבכתר עצמו הן בלתי מוגבלים. וכנראה נשתרבב לכאן מלעיל שו\"ה שבכתר."],["9820","994","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה גם לעיל פ' שמות ה, ג. וש\"נ."],["9821","995","<b>שמתקשראן כו'</b>: ויז: שמקושרין (בו) ג\"כ."],["9822","996","<b>באברהם. . נאמן לפניך</b>: נחמי' ט, ז-ח."],["9823","997","<b>ולהשלימה</b>: ויז: ולהשליכה."],["9824","998","<b>לשחוט. . שכבש רחמיו</b>: ע\"פ רבונו של עולם (תפלת השחר)."]]],[2300541033,"המשקוף המחבר ב' המזוזות דב' קוין שכלולי' בו כנ\"ל). וזה הי' ענין המלחמה להוי' בקי\"ס במדות העצמי' דכתר שהוא הרצון שיגבר החסד על הדין אע\"פ שלא קבלו ישראל עדיין התו\"מ כי <span data-k=\"pg\">רצב</span> ּ זהו למעלה מרצון המורכב בתו\"מ להיות[ו] בבחי' עצמי' ממש כנ\"ל, ולזאת הי' מלחמה זאת הכנה [רבה] למ\"ת להיות גם במ\"ת התגלות מבחי' אור העצמו' דא\"ס ממש שלמעלה גם ממדות שברצון ועונג דח\"ע באמרו אנכי ה' אלקיך כו' אנכי מי שאנכי<sup data-n=\"9825\">999</sup> בחי' סדכ\"ס דלית מח' תב\"כ כו', והוא אשר הוצאתיך מאמ\"צ שהוא בכח התקשרות העצמי' [ד]בעל הרצון ע\"כ נוטה לרצו[ת ל]חסד ויבחר לקחת לו גוי מקרב גוי<sup data-n=\"9826\">1000</sup> כו' ו[ל]תן להם התומ\"צ פב\"פ שזהו ג\"כ גילוי אור פנימי' מהו\"ע ית' שמלובש בהם מבעה\"ר העליון<sup data-n=\"9827\">1001</sup> [ד]מצות אלא שיצאו להאיר דרך הח\"ע כמו בטעם כמוס דמצוה כו', וכל התומ\"צ הוא רק להפוך המדות הטבעים בסו\"מ וע\"ט לבטל רצונו מפני רצון ה' בלבד כידוע. וכ\"ז הכח הי' בכנ\"י רק מאמונה הפשוטה שהי' בהם במצרים שעי\"ז נהפך מדות הטבעי', והוא ענין ימי הספירה שקדם למ\"ת שמיד אחר יצ\"מ בליל א' ש\"פ שזהו מצד בחי' התקשרות<sup data-n=\"9828\">1002</sup> העצמי' דיחידה לבד באמונה פשוטה [כ]נ\"ל מיד נצטוו לברר המדות הטבעי' העצמי' שנמשכי' בבחי' יחידה מן ההעלם לגילוי (שזהו מבחי' בעה\"ר<sup data-n=\"9829\">1003</sup> שלמעלה מבחי' מדות דאדם ע\"כ מזה דוקא נתגדלו במוחין דחו\"ב במדות דאדם במ\"ת כידוע), ואז יוכלו לקבל אור העצמו' דא\"ס ב\"ה בפנימי' הכתר בחו\"ב דתו', וכ\"ז [נכלל] בטעם שא' דז\"א בע\"י תליא והוא מה שא' [תרי\"ג מצות כו' העמידן על אחת ] שהוא האמונה דיחידה שבה שורה בחי' יחיד מקור התומ\"צ בציור אדם וד\"ל.\n(ךז) <b>ומעתה</b> י\"ל מ\"ש כימי צאתך מאמ\"צ אראנו נפלאות, ופי' אראנו לישראל סבא כנ\"ל, דהנה מבואר למעלה בכללות [ענין] קי\"ס שהוא רק בבחי' מל' דאצי' בה\"א אחרונה כו', וענין הבקיעה בקי\"ס זהו אור מל' דאצי' בבריאה שלא ע\"י מסך כו', ובדרך עלי' היינו שעלו נשמות דבריאה באצי' שלא ע\"י מסך כנ\"ל (והנה מה<sup data-n=\"9830\">1004</sup> שמבואר למעלה שהי' מלחמה דקי\"ס במדות הטבעים שברצון העצמי [כו'] כמ\"ש בעתיקא תליא כו', אבל בכנ\"י הי' בחי' הקטנות דמדות הטבעי' כמו בתינוק הנולד כמ\"ש בדמייך חיי כו' ו[מ]בחי' הקטנות הוא שעל[ו] לגדלות המוחין דאבא במ\"ת כנ\"ל). והנה ע\"ז א' כימי צאתך מאמ\"צ אראנו נפלאות<sup data-n=\"9831\">1005</sup> כו' דכמו שהי' בקי\"ס שהפך ים ליבשה בבחי' מל' דאצי' לבד כך יהי' לע\"ל במעלה ומדרגה גבוה יותר והוא בבחי' המדות דז\"א דאצי' שנק' יש\"ז כו', והענין [הוא] כמבואר למעלה שיש ג' מיני פרסא א' בין המדות והדבור בחזה",[["9825","999","<b>אנכי מי שאנכי</b>: נסמן לעיל פ' וארא סג, ד."],["9826","1000","<b>לקחת לו גוי מקרב גוי</b>: ואתחנן ד, לד."],["9827","1001","<b>העליון</b>: יז: העצמי."],["9828","1002","<b>התקשרות</b>: ויז: ליתא."],["9829","1003","<b>מבחי' בעה\"ר</b>: שם: בחי' בהמה רבה."],["9830","1004","<b>והנה מה</b>: שם: והגם."],["9831","1005","<b>נפלאות</b>: שם: ליתא."]]],[2300541037,"הלב שבא בקול הגרון (או בחצר הכבד לפסוק בין אברי הנשימה שבלב לאברים החיצונים כו'), והב' בפרסא שבין המדות שבלב לבינה שבמוח שהוא מיצר הגרון [שמ]פסיק ביניהם, והג' [ב]פרסא דקרומא כו' שמפסיק בין כתר לחכ' כו'. והנה בחי' קי\"ס שעבר ה[ו]י' בפרסא המפסק[ת] בין מדות לקול הדבור שיוצא מן ההעלם לגילוי כמו שהוא בלי מסך מבדיל כלל (וזהו כמו שאהוי\"ר שבלב [מ]תגל[ים] בקול ודבור שלא ע\"י צמצום והעלם כלל) וזה שנק' לידה דמדות בגילוי הדבור [ב]לבד בדברים היוצאים מן הלב כו'. וזהו בצאת ישראל בחי' המל' ממיצר הגרון <span data-k=\"pg\">586</span> ּ בקול ודבור במורגש כמו שהוא במדות שבלב ממש, וכמ\"כ בבחי' העלי' בקול ודבור במדות שבלב הוא בצלותא [בלחש] שעולה הדבור בפנימי' הלב וכה\"ג (שלא ע\"י העלם המח'). אך לע\"ל א' בנהר יעברו ברגל כו' שזהו עלי' יותר והוא בחי' עליות המדות שבלב למוח [ה]בינה או בבחי' ירידה וגילוי אור השכל והשגה דבינה במדות שבלב בלי מסך מבדיל ביניהם כלל וכלל והיינו בחי' עליות דישראל זוטא בבינה כו'.\n<b>ויובן</b> זה במה שאנו רואים גם עכשיו דאע\"פ ש[ה]השגה ו[ה]שכל בהתבוננו' באלקות במוח דבינה בטוב טעם ודעת מתמעט ומתקצר בהגיע לתולדות התפעלות המדות אוי\"ר בלב, והיינו במיצר הגרון ששם נתעלם לגמרי אף אהוי\"ר שבשכל (שנק' דו\"ר שכליים ממש) ונעשה בשינוי המהות בהתפעלו' אהוי\"ר בלב, מ\"מ יוכל להיות ש[י]עלה אור התלהבות הלב למעלה במקום השכל וההשגה שבמוח בינה כמו שהוא ממש או שיורד אור התפעלות האהבה והתלהבות שבשכל והשגה ממש כמו שהיא בתוך הלב ולא יהי' בזה שינוי [ה]מהות רק קיצור ותמצית, אבל זהו בחי' הפנימי' של השגה שנק' עומק בינה שהוא תמצית ועומק המושג שלמעלה מן ההסבר בחיצוני' כמו המשלים בדמיון לקרב אל השכל, שזהו עצמו בחי' מסך מבדיל להעלים אור הפנימי' דאלקו' שנתפס בעומק הזה ע\"י חיצוניות שהן הלבושי' דבינה כמו ביד הנביאים אדמה. ולכן נתעלם אמיתי' נקודת השכל במיצר הגרון כשבא להתפעלות הלב ונתקצר לגמרי ולא נשאר רק רושם בעלמא בהעלם במדות דאוי\"ר שבלב, והן אוי\"ר שנוגע רק למעשה בסו\"מ וע\"ט שנשאר מן ההתפעלו' הלב אבל עצם [ה]אוי\"ר שבמוח בינה מצד עצם פנימי' אור המושג נשאר בהעלם והסתלקות (כידוע דזהו בחי' לידה במדות מבטן אמו אימא עילאה שהירכיים מצטננים<sup data-n=\"9832\">1006</sup> כו' ולא נשאר בהעלם<sup data-n=\"9833\">1007</sup> רק הקיצור שנק' בכן כו'). אבל לע\"ל יהי'",[["9832","1006","<b>לידה. . שהירכיים מצטננים</b>: ראה גם שעה\"י קלג, א ובהערה 15."],["9833","1007","<b>בהעלם</b>: ויז: ליתא."]]],[2300541040,"גילוי אור המדות שבבינה בלב כמו שהוא ממש בלי העלם ולבוש כלל (וכמו גם עכשיו יש התפעלות הלב במהות התפעלות השכל עצמו ונק' בינה לבא<sup data-n=\"9834\">1008</sup> כו' והוא הניגון שיוצא מהבל הלב ע\"פ כוונה שכלי' דוקא, ואמנם זהו רק עומק התמצית שבהסבר כידוע), וכמו לבי ובשרי ירננו<sup data-n=\"9835\">1009</sup> כו' רינה זאת יהי' לע\"ל בבחי' הכרה שבלב בגדלות ה' איך שברא הכל מאין ליש כמו שהוא בהכרה שבמוח ממש כמו אברהם הכיר את בוראו בלב ונמצא לבבו נאמן כמו שהכיר במוחו ודעתו בלי שינוי, ולא כמו עכשיו שיש הבדל בין התפעלו' שבמוח להתפעלו' שבלב עד שיש יגיעה רבה בזה ולפעמים יתפעל במוח ואינו נוגע ללבו כלל וכלל כו', שזהו מצד מסך המבדיל בין מוחין שבראש למדות שבלב שהוא מיצר הגרון. וראי' לזה ממה שרואים ב' הפכים בקול הגרון, א' בבחי' מחיצה מבדלת בין המוח והלב והוא ממה שיצעק בקול חיצוני מאד מן השפה ולחוץ שע\"ז אמר נתנה עלי בקולה<sup data-n=\"9836\">1010</sup> ע\"כ שנאתי' כו' להיות מפסיק בחי' הפנימי' לגמרי שע\"כ א' יען נגש העם הזה בפיו ושפתיו כבדוני ולבם<sup data-n=\"9837\">1011</sup> רחק ממני כו' ואבדה חכמת חכמיו<sup data-n=\"9838\">1012</sup> כו' (כמשי\"ת). והב' מה שהקול מעורר הכוונה<sup data-n=\"9839\">1013</sup> שבמוח ללב דוקא כמו קול הרינה בניגון כשיר הלוים שא' עליהם ועבד הלוי הוא כו', שמגיע בשיר הלוים שלהם בפנימי' התענוג שלמעלה <span data-k=\"pg\">רצג</span> ּ מן השכל לגמרי כנ\"ל וד\"ל. וכמ\"כ יש ב' בחי' במדרגה זו עצמה בבחי' העלי' והסתלקו' דהיינו שבחי' אהבה ויראה שבלב עולין למוחין דחו\"ב כמו שהן ממש (וכמ\"ש בע\"ח דלפעמים עולין זו\"נ להיכלות דאו\"א<sup data-n=\"9840\">1014</sup> להתייחד שם מירא[ת ה]חיצוני') וזהו עלי' ז\"א בבינה, וכמבואר לעיל שיש בבקיעת הפרסא ב' אופנים א' בירידה והמשכה מלמעלמ\"ט באו\"י והב' בבחי' עלי' דאו\"ח מלמטלמ\"ע כמ\"ש בקי\"ס וד\"ל.\n<b>וזהו</b> והי' אור הלבנה<sup data-n=\"9841\">1015</sup> כאור החמה ואור החמה כו', פי' אור הלבנה הוא בחי' המל'<sup data-n=\"9842\">1016</sup> שהוא מקבל עכשיו מפני החמה שהן אותיות הדבור<sup data-n=\"9843\">1017</sup> שמקבל מהבל אור המדות שבלב (בחי' ז\"א<sup data-n=\"9844\">1018</sup> ), וע\"י בחי' עליות המל' במדות דז\"א דאצי' שזהו בחי' עלי' ללבנה שתהי' במדריגת החמה כנ\"ל שלא תצטרך להיות בחי' מקבל ממדות עליונות כי האותיות עצמן יהי' בהן בחי' כח של המדות להיות בבחי' מאור בבחי' משפיע, וכמו לע\"ל שא' ונגלה כבוד ה' שהן מדות דאצי' וראו כל בשר כו' כי פי ה' דיבר שאין הדבור מסתיר כלל (וכמו עכשיו אותיות הדבור בד\"ת שנק' משפיע לעולמות כמ\"ש ואשים דברי בפיך<sup data-n=\"9845\">1019</sup> כו' לנטוע שמים כו') (וכמ\"ש במ\"א על ענין ועינינו מאירות כשמש וכירח<sup data-n=\"9846\">1020</sup> בבחי' מאור כמאור השמש ולא בבחי'",[["9834","1008","<b>בינה לבא</b>: ת\"ז בהקדמה (יז, א)."],["9835","1009","<b>לבי ובשרי ירננו</b>: תהלים פד, ג."],["9836","1010","<b>נתנה עלי בקולה</b>: ירמי' יב, ח."],["9837","1011","<b>יען נגש. . ושפתיו. . ולבם</b>: ישעי' כט, יג [ושם: א) יען כי נגש — ראה לקמן רה, ג [ושם: הזה אלי]. לקמן פ' תצוה שלו, ד. שלח, א־ ב הוגה מגוכתי\"ק — [ושם: הזה אלי]. ויקהל שצז, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תסא. דרושי חתונה ח\"ב ע' תמח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670291\" data-slug=\"torat-chaim\" data-id=\"2300670291\">תו\"ח נח נ, ב</a> הערה 23. ב) ובשפתיו — נסמן לעיל פ' בא קח, ב. ג) ולבו [וכ\"ה ביז] — ראה לקמן רכט, ג. מאמרי אדה\"א שמות ח\"ב ע' תסא]."],["9838","1012","<b>ואבדה חכמת חכמיו</b>: ישעי' שם, יד."],["9839","1013","<b>שהקול מעורר הכוונה</b>: ראה לעיל פ' בא קו, ד. וש\"נ."],["9840","1014","<b>עולין זו\"נ להיכלות דאו\"א</b>: ראה ע\"ח (שער העקודים) ש\"ו, ספ\"ח."],["9841","1015","<b>והי' אור הלבנה</b>: ישעי' ל, כו."],["9842","1016","<b>הלבנה. . המל'</b>: ראה פרדס (שער ערה\"כ) שכ\"ג, מערכת לבנה."],["9843","1017","<b>המל'. . הדבור</b>: נסמן לעיל פ' שמות לד, א."],["9844","1018","<b>החמה. . ז\"א</b>: ראה פרדס (שער ערה\"כ) שכ\"ג, מערכת חמה. ע\"ח (שער מיעוט הירח) של\"ו, פ\"ב."],["9845","1019","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["9846","1020","<b>ועינינו מאירות כשמש וכירח</b>: תפלת נשמת. ראה גם תו\"ח ח\"ש קלב, א. ש\"א צז, א. מאמרי אדה\"א נ\"ך ע' תרד. וש\"נ. לקמן פ' ויקהל תג, ב."]]],[2300541043,"אור מקבל). וזה הי' הכנה דקי\"ס למ\"ת לקבל אור דח\"ע דתו' פב\"פ שיאיר בנ\"י במאור דאור דתו' בפני חמה שהוא פני משה ממש אף שהוא בחי' מקבל הי' בחי' משפיע לדורות שאחריהם וכמ\"ש ת\"ר אלף אשר אנכי בקרבו<sup data-n=\"9847\">1021</sup> ממש כו'. וכן יש אוי\"ר שבדבור שעולין בבחי' מדות שבלב כנ\"ל בקול התפלה או קול הדבור שיוצא מקירות הלב שדבריו נשמעים ועושי' רושם בלב זולתו כנ\"ל כמו המדות שבלב עצמה כנ\"ל (וזהו אשרי איש ירא<sup data-n=\"9848\">1022</sup> איש ולא אשה שאינו מבחי' מקבל התעוררו' מלמעלה לעיתים או מזולתו או מיגיעת שכלו להמשיך אוי\"ר אלא מעצמו ומאליו יומשך בבחי' דעת והכרה שבלב כו' כנ\"ל באברהם). וכך יובן בעלי' הב' שזהו שא' [ו]אור החמה שהן בחי' המדות שבלב דז\"א יעלו למעלה יותר מאחר שבחי' המל' תעלה במקום ומדרגה המדות שבלב בבקיעת הפרסא כך יהי' עליות המדות במקום ומדרגה מוח הבינה, אע\"פ שעכשיו המדות מקבלים מבינה נק' אם הבנים<sup data-n=\"9849\">1023</sup> כנ\"ל בחי' אימא עילאה<sup data-n=\"9850\">1024</sup> כנ\"ל אבל בבקיעת הפרסא שבין המוחין למדות שהוא מיצר הגרון יעלו המדות שבלב להיות בבחי' מדות שבבינה שנק' אור ז' הימים<sup data-n=\"9851\">1025</sup> כו' וד\"ל. ופי' שבעת הימים היינו זפ\"ז<sup data-n=\"9852\">1026</sup> שהן מ\"ט ימי הספירה שהן מ\"ט שערי בינה<sup data-n=\"9853\">1027</sup> כידוע וגם<sup data-n=\"9854\">1028</sup> ז' מדות דבינה שכלולים כ\"א מז' והוא אחר הבירור דז' מדות הטבעי' שבלב במוחין דאו\"א<sup data-n=\"9855\">1029</sup> דוקא (שזהו בחי' מוחין דיניקה ש[מ]גדלים המדות שבלב מאור אימא כנ\"ל בגדלות ראשון עד מ\"ת שהוא בחי' גדלות שני דאבא), וכמ\"כ בבחי' ירידה וגילוי ההעלם דז\"ת דאו\"א שיאירו במדות שבלב שזהו ענין בקיעת הפרסא מלמעלמ\"ט לזה יהי' העברה הנ\"ל בנהר יעברו ברגל שהוא עלי' דיש\"ז בבינה שנק' נהר כו' וד\"ל. והנה עלי' [הג' הוא] בבקיעת <span data-k=\"pg\">588</span> ּ הפרסא שבין כתר לחו\"ב והוא בחי' קרומא הנ\"ל היינו בבחי' אין דחכ' שנמשך לבינה בב' בחי' אין הנ\"ל והוא ע\"י העלם וצמצום דחכ' בקרום זה כנ\"ל שנק' חשך שלמעלה מאור דחכ' שמאיר בבינה, אך יהי' עלי' ליש'<sup data-n=\"9856\">1030</sup> שהן מדות דחכ' קודם שיצאו מאין דחכ' לבינה כנ\"ל למעלה בעתיקא עצמו שהן מדות הטבעי' שבעצמות התענוג והרצון שלמעלה גם מח\"ס טעם כמוס כו' וד\"ל. וכך יהי' עלי' עוד למדות דתענוג ורצון העצמי שנק' ע\"י וא\"א כנ\"ל בעצמו' אוא\"ס בפנימי' דאור הכתר (כמו בחי' מדות דיחידה ולמעלה יותר) כי גבוה מעל גבוה אין שיעור לעליות המדרגות בעולם הא\"ס עצמו (שנק' שעשוע המלך בעצמותו שהוא מקור כל הרצונות והתענוגי' שנמשך במדה בהשתלשלו' דקו\"ח שנמשך באבי\"ע כנ\"ל).",[["9847","1021","<b>ת\"ר אלף אשר אנכי בקרבו</b>: בהעלותך יא, כו [בדילוג]."],["9848","1022","<b>אשרי איש ירא</b>: תהלים קיב, א. ע\"ז יט, א. ראה גם מאמרי אדה\"א נ\"ך ע' רסז. וש\"נ. דרושי חתונה ח\"ב ס\"ע תרלא ואילך. שע\"ת מח, סע\"ג ואילך."],["9849","1023","<b>מבינה נק' אם הבנים</b>: נסמן לעיל פ' שמות יז, א."],["9850","1024","<b>מבינה. . אימא עילאה</b>: נסמן לעיל פ' שמות ט, ב."],["9851","1025","<b>אור ז' הימים</b>: ישעי' ל, כו (המשך הכתוב והי' אור הלבנה)."],["9852","1026","<b>זפ\"ז</b>: יז: ז' פעמים ז'."],["9853","1027","<b>מ\"ט. . מ\"ט שערי בינה</b>: נסמן לעיל פ' בא קיא, ד."],["9854","1028","<b>וגם</b>: ויז: נגד."],["9855","1029","<b>דאו\"א</b>: היז: דאימא."],["9856","1030","<b>ליש'</b>: ו: לי\"ס. היז: ליש\"ס."]]],[2300541046,"<b>וזהו</b> אראנו נפלאות לשון רבים והיינו אראנו ליש\"ס דוקא כנ\"ל, דהנה מבואר למעלה שיש ב' מדרגות בישראל א' בחי' הקטנות דישראל בצאתם ממצרים כמ\"ש כי נער ישראל ואוהבהו<sup data-n=\"9857\">1031</sup> וכן א' זכרתי לך חסד נעוריך<sup data-n=\"9858\">1032</sup> כו' והוא כשהי' בקטנות המוחין במדות דאוי\"ר באמונה פשוטה למעלה<sup data-n=\"9859\">1033</sup> מן הדעת והוא מ\"ש לכתך אחרי כו'. והוא מ\"ש וירא ישראל את היד הגדולה פי' יד הגדולה זהו בחי' חסד דא\"א שנק' רב חסד שמתפשט מגבוה לנמוך ביותר כמו וימינך פשוטה<sup data-n=\"9860\">1034</sup> כו', שיש ימין עליון מקרבת עד למטה מטה להשיב בתשובה גם לרשעים שנפלו למטה ב[עומק] רע להוציאם משם, וכך הי' בבחי' יד החזקה וזרוע הנטויה שבהם נעלה<sup data-n=\"9861\">1035</sup> ממצרים כמשל האב הרואה את בנו מושלך בארץ במקום סכנה משפיל קומתו ומושיט ומוריד ידו הגדולה [והחזקה] למטה להגביהו מן הארץ ולהצילו מרודפו ולהכות לכל הנוגע בו כו', וזה [הי'] ג\"כ בקי\"ס שא' וירא ישראל את היד הגדולה שזהו בחי' חסד עליון שיורד מגבוה לנמוך לקרוע הים ולהעביר ישראל בתוכו בחרבה<sup data-n=\"9862\">1036</sup> כמ\"ש מוליך לימין כו' [ימינך ה' כו'], ובימין זה עצמו תרעץ אויב<sup data-n=\"9863\">1037</sup> להטביע למצרים בים שז\"ש היד הגדולה אשר עשה [ה'] במצרים דוקא שזהו כמשל האב המשפיל ידו למטה להציל בנו הקטן שממילא יהי' בכח ידו להרוג לרודפו ולהציל בנו כו'. ונמצא שזהו בחי' [כח] החסד שכלול מבחי' דין להיות בא בבחי' ירידה והשפלה למטה לעמוד נגד אויב כו', אבל לע\"ל בהעברה דנהר שיעברו ברגל לא יהי' [נ]צרך למלחמה [כלל] נגד אויב כי זה יהי' אחר קיבוץ גליות (כמבואר בישעי' י\"א וי\"ב ויצא חוטר<sup data-n=\"9864\">1038</sup> כו' עד יוסיף ידו לקנות<sup data-n=\"9865\">1039</sup> את שאר עמו [מאשור] כו' והחרים ה' [את] לשון ים מצרים והניף ידו על הנהר כנ\"ל) שזה יהי' בשלום ושלוה שע\"ז א' בנהר יעברו ברגל כו', וכן מה שא' בשירת הים עד יעבור להבא כו' כנ\"ל ואמנם זה יהי' בבחי' עליות המדרגות לישראל שלמעלה שיעלו ויעברו בנהר בינה כנ\"ל. וביאור זה מה שנק' יש\"ז זה רק בבחי' מדות שבלב שנולדים מן השכל באוי\"ר שכלים שבאים מן המוח בינה בגילוי בלב שזהו מצות ואהבת כו' להיות <span data-k=\"pg\">רצד</span> ּ בזה יסוד לקיום מ\"ע באהבה ולהיות סו\"מ ע\"י גילוי היראה בלב כידוע שזה יסוד הבירור בכלל במ\"ע ול\"ת בין טו\"ר בפו\"מ כו'. אך כ\"ז [הוא] עכשיו בזמן הבירורי' דעה\"ד ע\"י אהוי\"ר ששייך למעשה שמקבלים מחו\"ב דבחכ' אתברירו למעלה<sup data-n=\"9866\">1040</sup>, אבל בתשלום הבירורי' הללו בימוהמ\"ש שיבוער הרע מן הארץ כמ\"ש לא ירעו ולא ישחיתו<sup data-n=\"9867\">1041</sup> כו' כי מלאה הארץ דעה את ה' כו', אזי יתעלו בנ\"י למעלה להיות בבחי' המדות עליונות דבינה עליונה שנק'",[["9857","1031","<b>כי נער ישראל ואוהבהו</b>: הושע יא, א."],["9858","1032","<b>זכרתי לך חסד נעוריך</b>: ירמי' ב, ב."],["9859","1033","<b>למעלה</b>: אהיז: למטה."],["9860","1034","<b>וימינך פשוטה</b>: ראה גם לעיל פ' וארא עב, ב. וש\"נ."],["9861","1035","<b>נעלה</b>: היז: גאלם."],["9862","1036","<b>ולהעביר ישראל בתוכו בחרבה</b>: תהלים קלו, יד. הגש\"פ (דיינו)."],["9863","1037","<b>ובימין. . תרעץ אויב</b>: בשלח טו, ו."],["9864","1038","<b>ויצא חוטר</b>: ישעי' יא, א."],["9865","1039","<b>יוסיף ידו לקנות</b>: ישעי' שם, יא [בדילוג]."],["9866","1040","<b>למעלה</b>: היז: למעשה."],["9867","1041","<b>לא ירעו ולא ישחיתו</b>: ישעי' יא, ט."]]],[2300541049,"ז\"ת דבינה כמו שה[י'] קודם שיצאו המדות בתולדה בלב וכנ\"ל שהן כמו אוי\"ר שבשכל והשגה מצד עצמו ממש בלי לבוש ומשל כלל, וזהו עליות הב' לבחי' יש\"ז בבינה וכמ\"ש ואור החמה יהי' שבעתיים כו' כנ\"ל וד\"ל.\n(ךח) <b>והנה</b> מ\"ש אראנו נפלאות קאי על בחי' ישראל זה שהי' רואה בחי' יד הגדולה שעשה ה' במצרים בירידה והתפשטו' למטה מטה ביותר כנ\"ל (כמ\"ש אנכי תרגלתי לאפרים<sup data-n=\"9868\">1042</sup> כאב הגדול בקומה שהשפיל ידו למטה לרגלי' להציל בנו הקטן כנ\"ל) כמ\"ש וירא ישראל כו', אראנו לישראל זהו כשיהי' [בעלי'] לע\"ל בימוהמ\"ש ויעלו לבחי' המדות דבינה כשיעברו בנהר ברגל שזהו בנחל מצרים אראנו למעלה לבחי' היד הגדולה הזאת עצמו שראה במצרים למטה בהשפלה הוא שיעלה לישראל סבא זה בבחי' עליות המדרגו' למעלה כמו שמרים האב לבנו ויגבהנו על זרועו כלפי ראשו כמ\"ש קחם על זרועותיו<sup data-n=\"9869\">1043</sup> שהם ב' זרועות דא\"א בחי' יד הגדולה ויד החזקה שהי' נטוי' למטה לגאלם ממצרים זהו עצמו שיהי' מעלה לישראל זה למעלה מעלה להראותו בחי' נפלאות העליונו' פלא אחר פלא (כמו סדכ\"ס כנ\"ל). והיינו בהעברה הב' שיהי' לע\"ל בנהר פרת שהוא נהר שיוצא מעדן<sup data-n=\"9870\">1044</sup> כו', וז\"ש עד יעבור הב' סתם למעלה משם הוי' ואז יהי' נק' יש\"ס שיעבור למעלה בנהר זה שיוצא מעדן לעדן עצמו, ושם א' עם זו קנית<sup data-n=\"9871\">1045</sup> בקנין עצמו ממש לחיי עולם שהוא העוה\"ב עצמו שא' ביום הג' יקימנו ונחי' לפניו<sup data-n=\"9872\">1046</sup> ממש. ונמצא יש כאן ג' עליות לבד קי\"ס, א' שיעברו בנהר דמצרים שזהו עד יעבור הא', והב' בהעברה דנהר הגדול נה\"פ<sup data-n=\"9873\">1047</sup> שזהו עד יעבור הב', והג' עם זו קנית כו' שזהו נפלאות רבים מ\"ש יחיינו מיומים כו' (וכמשי\"ת). וכך הוא גם בפסוק [ד]הפך ים ליבשה לשון עבר בנהר יעברו ברגל כולל ב' העברות כנ\"ל שנז' בתו' בפסוק עד יעבור ושם נשמחה בו ממש וזהו בעוה\"ב בעדן עצמו כו', וכ\"ז נכלל במ\"ש אראנו נפלאות [לשון רבים דהיינו מה שלמעלה נק' נפלאות] פלאי פלאות יהי' נראה לישראל זה בגילוי כמו באורך נראה אור<sup data-n=\"9874\">1048</sup> כו' וד\"ל.\n<b>וביאור</b> כ\"ז הנה יובן בהקדים תחלה בכללות ענין אור הכתר בכלל שנק' פלא כידוע שזהו<sup data-n=\"9875\">1049</sup> ב' עליות, הא' עליות דא\"א במדות שהוא למדות דע\"י (כידוע דא\"א נק' חיצוני' הכתר [בכלל] שנעשה מקור ושרש וראש לנאצלים ובחי' ע\"י בכלל נק' פנימי' הכתר שנחשב מסוף עולם הא\"ס<sup data-n=\"9876\">1050</sup> כו'",[["9868","1042","<b>אנכי תרגלתי לאפרים</b>: נסמן לעיל פ' בא פט, ב. וראה גם לעיל רא, א."],["9869","1043","<b>קחם על זרועותיו</b>: ראה גם לעיל פט, ב."],["9870","1044","<b>בנהר פרת. . שיוצא מעדן</b>: נסמן לעיל פ' שמות א, ב."],["9871","1045","<b>עם זו קנית</b>: בשלח טו, טז (המשך הכתוב עד יעבור)."],["9872","1046","<b>ביום הג' יקימנו ונחי' לפניו</b>: הושע ו, ב."],["9873","1047","<b>נה\"פ</b>: ויז: נהר פרת."],["9874","1048","<b>באורך נראה אור</b>: תהלים לו, י."],["9875","1049","<b>שזהו</b>: היז: שיש בו."],["9876","1050","<b>ע\"י. . מסוף עולם הא\"ס</b>: ראה גם מאמרי אדה\"א קונטרסים ע' ד. וש\"נ. שע\"ת קד, א ובהערה 10. לקמן פ' משפטים שב, א."]]],[2300541052,"כמ\"ש בע\"ח) והוא בחי' הרצון שהוא בחי' א\"א וכלול מיו\"ד ספי' ג\"ר וז\"ת ובחי' ע\"י הוא בחי' התענוג שכלול ג\"כ מי\"ס ג\"ר וז\"ת כידוע. והנה [ענין] עלי' זו דז\"ת דא\"א בז\"ת דע\"י זהו שלא בהדרגה ע\"י [בחי'] ג\"ר דא\"א אלא ג\"ר וז\"ת דא\"א יתעלו בז\"ת דע\"י עצמו דוקא וג\"ר דע\"י יתעלו למעלה יותר (כמשי\"ת). כי הנה ידוע דלפי סדר ההשתל' והתלבשות הפרצופי' הרי בחי' ז\"ת<sup data-n=\"9877\">1051</sup> דע\"י מתלבשי' בג\"ר דא\"א, בחי' חסד דע\"י <span data-k=\"pg\">590</span> ּ מתלבש בגולגלתא דא\"א וגבורה דע\"י במו\"ס<sup data-n=\"9878\">1052</sup> דא\"א ות\"ת דע\"י בבינה דא\"א, וכנגד הכוונה<sup data-n=\"9879\">1053</sup> דש[מו]\"ע בברכה הראשונה דאלקינו ואלקי אבותינו אלקי אברהם אלקי יצחק כו' זהו כתר<sup data-n=\"9880\">1054</sup> דע\"י שזהו אלקינו מל' דא\"ס שמאיר בג\"ר דע\"י וג\"ר דע\"י מאירים בחג\"ת דע\"י שהן האבות ששרשם בחג\"ת דע\"י<sup data-n=\"9881\">1055</sup> שנק' ימי קדם כו' כמו אה\"ר בתענוגים באו\"י דחסד דאברהם ואו\"ח בגבו' שבתענוגים בחי' יצחק ובחי' ת\"ת דע\"י בחי' ממוצע הכוללם יחד שהוא יעקב (וז\"ש במשיח ישכיל כו' ירום מסט' דחסד [ד]ע\"י באברהם<sup data-n=\"9882\">1056</sup> ונשא [ב]בחי' יצחק<sup data-n=\"9883\">1057</sup> גבו' דע\"י וגבה מאד בחי' ת\"ת דע\"י כו'), ואח\"כ א' האל הגדול הגבור והנורא שזהו בבחי' חג\"ת דא\"א<sup data-n=\"9884\">1058</sup> חסד דא\"א שרש הקו הימין חח\"ן נק' אברהם כו'<sup data-n=\"9885\">1060</sup> הגדול בה\"א והגבור בגבו' דא\"א שרש הקו השמאל בג\"ה והנורא בחי' ת\"ת דא\"א קו האמצעי דת\"י<sup data-n=\"9886\">1059</sup> יעקב כו'. נמצא בחי' חג\"ת דע\"י שזהו אלקי אברהם כו' הוא הגבה למעלה בחי' חג\"ת<sup data-n=\"9887\">1061</sup> דא\"א שזהו הגדול כו' דחג\"ת דע\"י הן מלובשי' בג\"ר דא\"א כו' כנ\"ל<sup data-n=\"9888\">1062</sup> שחו\"ב דא\"א למעלה מהתחלקות הג' קוין דאצי' עדיין (כמ\"ש<sup data-n=\"9889\">1063</sup> בפרד\"ס<sup data-n=\"9890\">1064</sup> ), וכשיש עלי' לחג\"ת דא\"א היינו שיתעלו תחלה לג\"ר שלהן בכח\"ב דא\"א ואח\"כ יתעלו בג\"ר דע\"י. אבל לע\"ל יהי' עלי' הג\"ר וז\"ת דא\"א כא' ממש בחג\"ת דע\"י, דהיינו שיהי' במדרגות המדות שבתענוג העצמי [ממש] שנק' תענוג הפשוט המרומם בערך נבדל מבחי' התענוג הנמשך ברצון כנ\"ל, שמחמת התענוג הוא רוצה בדבר [מ]ה שהוא צמצום אור הארת התענוג רק בערך הרצון לבד באה\"ר בתענוגי' שמתצמצם לפ\"ע דבר שמתענג בו באהבה כאיש הנאהב ברצונו תמיד אליו כו' (אם הוא עונג לרצון בחכ' אז הוא בבחי' גבו' וחסד<sup data-n=\"9891\">1065</sup> והתלהבות שזהו נק' גבורה דע\"י שמלובש בחסד<sup data-n=\"9892\">1066</sup> שמשם מקור הבירור שבח\"ס ומשם שרש התחלקות הרצון במצות ובג' קוין כו', וח\"ס<sup data-n=\"9893\">1067</sup> דע\"י הוא באה\"ר וחסד מצד עצם הטוב שמתענג מאד בזה ע\"כ רוצה להשפיע חסד זה שמלובש בגולגלתא שהוא עצם הרצון רק טוב מאד<sup data-n=\"9894\">1068</sup> כו' שבא מחמת",[["9877","1051","<b>ז\"ת</b>: ו: ג\"ר. היז: חג\"ת. וראה בסמוך בפנים. נסמן לעיל פט, ב."],["9878","1052","<b>במו\"ס</b>: היז: בח\"ס."],["9879","1053","<b>וכנגד הכוונה</b>: שם: וכידוע בכוונת."],["9880","1054","<b>כתר</b>: אה: בכח\"ב. יז: כח\"ב."],["9881","1055","<b>האבות ששרשם בחג\"ת דע\"י</b>: נסמן לעיל קנח, ב."],["9882","1056","<b>ירום. . באברהם</b>: ראה תנחומא תולדות יד. שה\"א פט, א ובהערה 18."],["9883","1057","<b>ונשא. . יצחק</b>: ראה תנחומא שם. שה\"א שם ובהערה 19."],["9884","1058","<b>הגדול. . חג\"ת דא\"א</b>: ראה גם לעיל פ' בא קל, ד ובהנסמן שם."],["9885","1060","<b>אברהם כו'</b>: היז: ליתא."],["9886","1059","<b>חח\"ן. . בג\"ה. . דת\"י</b>: נסמן לעיל פ' וארא פד, ד."],["9887","1061","<b>בחי' חג\"ת</b>: ויז: מחג\"ת."],["9888","1062","<b>כו' כנ\"ל</b>: אהיז: כתר."],["9889","1063","<b>שחו\"ב דא\"א. . כמ\"ש בפרד\"ס</b>: ראה גם לעיל צ, א. וש\"נ."],["9890","1064","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — נסמן לעיל צ, א."],["9891","1065","<b>וחסד</b>: היז: וחשק."],["9892","1066","<b>בחסד</b>: שם: בח\"ס."],["9893","1067","<b>וח\"ס</b>: יז: וחסד."],["9894","1068","<b>טוב מאד</b>: היז: לטוב תמיד."]]],[2300541055,"בחי' חסד דא\"א<sup data-n=\"9895\">1069</sup> שהוא כמו אה\"ר בתענוגים כו'). אך הנה בחי' תענוג הפשוט הבלתי מורכב בדבר מה [זהו] כמו התענוג אשר בעצם הנפש דיחידה כמו בעת שמחת לבו מאד מבשורה טובה ונפלאה או במשתה בנו או כש[עו]לה לגדולה יתירה וכה\"ג, שאז [י]הפך לבו ממדותיו<sup data-n=\"9896\">1070</sup> הטבעים מקודם עד שכל הכחות הטבעים מתעלים יחד ברגע א' לעשות היפך טבעו ממש כנ\"ל במשל הכילי שכלי' רעים מאד וממונו חביב עליו כנפשו ממש כו' שבעת שמחתו וטוב לבבו יהפך טבעו להיות פזרן, וכן מי שטבעו אכזרי מאד בעת גדולתו ורוממותו [י]הפך לרחמ[נ]י, וכן מי שרוחו קשה וגבוה מאד בעת רוממותו [או] בעת שמחתו ישפיל א\"ע ביותר ויחפוץ להטיב מטובו לכל אף לשונאו שעמד על נפשו ירבה לסלוח כו', וכ\"ז רק מצד בחי' הרוממות בנפשו בעצם התענוג הנעלם שנפשו מליאה תענוג עצמי (בל\"א גיהייבין<sup data-n=\"9897\">1071</sup> זייער אין גרוש תענוג) (בחדות ועונג של הנפש עצמה דוקא) שמפני רוממות עצמי' הנפש שם כאין וכל\"ח כל מה שהוגדר בגדר טבע מדותיו ושכלו ולא נחשב למאומה כלל, כי במקום גבוה מאד נעלה יתפשט <span data-k=\"pg\">רצה</span> ּ ויתבטל מכל כחות שלו המגודרים בנפשו תחלה, כמו כשבא אדם שפל למעלה [ו]מדרגה גבוה להיות שר ומקורב לפני המלך שאז ישתנו כל טבעיות שלו המגודרים ולא יחשב למאומה, כמו הממון שהי' חומד כל\"ח נגד [הכבוד ב]התקרבותו [ב]מעלה גבוה כזו, וכן לא ידקדק במדת הדין רק בחסד וטוב לכל אף גם לשונאיו כו' מצד שבמקום גבוה שהוגבה ונתרומם הכל כלא וכאין חשיב כו'. וכמו\"כ בהתפעלו' אה\"ר בתענוגי' מעצמו' הנפש דבחי' [יחידה] העצמי' כל התענוגי' ורצונו[ת] ומדות ושכלי' כל\"ח ממש עד שיוכל להפוך טבעו מן הקצה אל הקצה ממש [מ]מהות למהות אחר כנ\"ל וד\"ל.\n(ךט) <b>והנה</b><sup data-n=\"9898\">1072</sup> יובן ג\"כ בבחי' עלי' דרצון במדות הטבעי' שבו כשעולין במעלה ומדרגה גבוה אינו אלא<sup data-n=\"9899\">1073</sup> בחי' התענוג המרומם בחי' פנימי' דע\"י שהן מדות דאה\"ר בתענוגי' שמשם מתבטל ויהופך כל הי\"ס דא\"א ג\"ר וז\"ת ברגע א' לשנות מרצון לרצון היפוכו ממש, כמו שאו' יה\"ר מלפניך שיכבשו רחמיך כו' שזהו בעת רצון דוקא, והוא בעת שמחת ותענוג המרומם בעצמו' המאציל שאז נגלה בחי' סדכ\"ס<sup data-n=\"9900\">1074</sup> כידוע להפוך מרצון של דין לחסד וטוב כמו וירח את ריח הניחוח<sup data-n=\"9901\">1075</sup> כו' וינחם [ה'] על הרעה<sup data-n=\"9902\">1076</sup> ודן בעצמו לזכות והוא כי יצר לב<sup data-n=\"9903\">1077</sup> כו', כי במקום גבוה כזה כל בחי' י\"ס דא\"א בהתחלקות דרצון כחו\"ג כל\"ח ויהופך הכל מטעם הנ\"ל, וע\"כ אין העלי' זו כסדר בהדרגה מז\"ת דא\"א<sup data-n=\"9904\">1078</sup> לג\"ר דא\"א שהוא ח\"ס טעם כמוס לרצון כו' אחר שנתעלה בבחי' התענוג העצמי",[["9895","1069","<b>דא\"א</b>: שם: דע\"י."],["9896","1070","<b>ממדותיו</b>: אהיז: ודעתו."],["9897","1071","<b>גיהייבין</b>: א: ניתוסף: גיהובט. ה: גְיה יב ין גְיה יבט."],["9898","1072","<b>והנה</b>: היז: ובזה."],["9899","1073","<b>אינו אלא</b>: היז: ממנו שהוא."],["9900","1074","<b>סדכ\"ס</b>: שם: רעדכ\"ר — נסמן לעיל פ' שמות ה, ג."],["9901","1075","<b>וירח את ריח הניחוח</b>: נח ח, כא [בדילוג]."],["9902","1076","<b>וינחם [ה'] על הרעה</b>: לשון הכתוב תשא לב, יד."],["9903","1077","<b>כי יצר לב</b>: נח ח, כא."],["9904","1078","<b>דא\"א</b>: היז: ליתא."]]],[2300541058,"שלמעלה מכל בחי' טבעי' הרצון כו' כמובן ממשלים הנ\"ל ה\"ז עולי' כולם כא' כנ\"ל וד\"ל. ולפ\"ז הרי יובן דבחי' ז\"ת דע\"י ששם מתעל[י]ם כל ע\"ס דא\"א הוא למעלה מחג\"ת דע\"י שמלובשי' בצמצום בגולגלתא דמו\"ס<sup data-n=\"9905\">1079</sup> דא\"א כנ\"ל, וא\"כ מובן ממילא דגם בחי' ג\"ר דע\"י שלמעלה מז\"ת דע\"י הנק' תענוג העצמי דמדות המרומם בנפשו (כמו בעת חתונתו [ועת התמנות גדולתו] וכה\"ג) גם זה יתעלה למעלה ממנו, וזהו בחי' עלי' הב' דפנימי' הכתר בכלל [ש]זהו ג\"ר דע\"י שנחשב מסוף עולם הא\"ס שהוא מל' דא\"ס ([ד]מל' דא\"ק נחשב בכלל מל' דא\"ס שמלובש בקו\"ח כו'). וענין עלי' זאת היינו ש[י]עלה [מדריגות] ג\"ר דע\"י שלמעלה גם מאה\"ר בתענוגי' שהן המדות והוא התענוג העצמי שבעצם הנפש בעצם כח השכל להשכיל כל שכל שנק' נפש השכלי' שמכח התענוג העצמי הזה הוא שנתרבה [ונתגדל] כל עיקר כח המשכיל הזה [להשכיל כו'] (כמו שאנו רואים שכל עיקר ומקור הראשון לנביעת מקור החכ' והשכל הוא ממקור התענוג הנעלם שבעצ[ם] הנפש), כמו<sup data-n=\"9906\">1080</sup> בחי' תענוג המרומם הנ\"ל כמו בעת שמחתו וגדולתו או בגמר מלאכתו בבנין וניצוח מלחמה וכה\"ג בבשורה טובה זהו הכל בגילוי אור התענוג המורגש בעצם נפשו, אבל לא בבחי' [ה]העלם ומקור כל הע[ונ]ג הגלוי כו', ואין לעונג המורגש ומורכב בדבר מה ערך כלל לבחי' עונג הנעלם ופשוט בלתי מורכב בדבר [מה] רק שהוא בחי' כח היולי עדיין להיות ממנו מקור מציאות כח נביעת של דבר מה, כמו נביעת השכל וכח האהבה בתענוגי' וכח הטפה הרוחני' המוליד וכה\"ג (בל\"א דער קוועלין<sup data-n=\"9907\">1081</sup> אין מקור התענוג בלחלוחית עונג הרוחני שבמוח בהעלם) כמו שעונג המורגש בבשר וחלב מרצון<sup data-n=\"9908\">1082</sup> העצם ומגדל הבשר בעיד[ון] גשמי' <span data-k=\"pg\">592</span> ּ כך ברוחני' ממש). וזהו ענין עלי' הב' גם בבחי' ג\"ר דע\"י שלמעלה גם מעונג המורגש והוא שנק' עתיקא דעתיקא<sup data-n=\"9909\">1083</sup> שהוא מקור כל התענוגי' [ה]עליונים שמאירים לעולם הנאצלי' כו' (ע\"י<sup data-n=\"9910\">1084</sup> התלבשות ז\"ת דע\"י בא\"א כנ\"ל) כמ\"ש כי עמך מקור חיים מקור כל התענוגי' כו' שגם בחי' המקור החיים הזה (כמו מקור התענוגי' שבעוה\"[ב] וגעה\"ע נמשך למטה ביו\"ד וה' דשם הוי') עמך טפל ובטל, והוא במל' דא\"ס ששם א' נשמחה בו לשון נסתר ונעלם והוא בבחי' שעשועי' העצמי' דעצמו' אוא\"ס כמו שהוא ממש שאפס קצהו יאיר בעוה\"ב דכתי' ונחי' לפניו ממש<sup data-n=\"9911\">1085</sup> (כמשי\"ת) שזהו נשמחה בו ממש והוא בא רק משמחה ש\"מ ותענוגים ש\"מ<sup data-n=\"9912\">1086</sup> דוקא עכשיו [(כמשי\"ת)]. וזהו אראנו נפלאות ל' רבים שהן ב' מיני עליות [עלי'] הא' ליש\"ס זה [ש]הן בחי' מדות דא\"א הנ\"ל בז\"ת דע\"י בעונג המרומם העצמי ממש כנ\"ל, ועלי' הב' ליש\"ס זה בעלי' דג\"ר דע\"י שהוא בחי' עונג הנעלם בהעלם<sup data-n=\"9913\">1087</sup> מקור כל התענוגי' שבשכל ומדות בתענוג",[["9905","1079","<b>דמו\"ס</b>: איז: ומו\"ס. ה: ליתא."],["9906","1080","<b>כמו</b>: אהיז: כי."],["9907","1081","<b>קוועלין</b>: שם: קוועל."],["9908","1082","<b>מרצון</b>: שם: מדשן."],["9909","1083","<b>עתיקא דעתיקא</b>: ראה זהר (אד\"ר) נשא קכח, א."],["9910","1084","<b>ע\"י</b>: ניתוסף ע\"פ: אה."],["9911","1085","<b>ממש</b>: היז: ליתא."],["9912","1086","<b>ש\"מ ותענוגים ש\"מ</b>: שם: ותענוג של מצות."],["9913","1087","<b>בהעלם</b>: שם: והיולי."]]],[2300541061,"ורצון כנ\"ל שזה שם נשמחה בו ממש, והוא ע\"י עלי' דג\"ר דע\"י בעצמו' השעשועי' כנ\"ל.\n<b>אך</b> כ\"ז הוא מחמת שמחה ותענוג בעבודה שבלב בתפלה ובמצות כמ\"ש יען נגש העם הזה [אלי] בפיו ושפתיו כבדוני ולבו כו' שאין בכ\"ז<sup data-n=\"9914\">1088</sup> רוממות ה' בגרונם בשמחה ותענוג העצמי דיחידה ממש הנ\"ל שזהו שנק' שיר פשוט שיר אל<sup data-n=\"9915\">1089</sup> כידוע, וכך במצות רק מצות אנשים מלומדה<sup data-n=\"9916\">1090</sup> בלא שמחה ותענוג כלל כמו תחת אשר לא כו' בשמחה וטוב לבב<sup data-n=\"9917\">1091</sup> דוקא [י]עשה הפלא ופלא כו'<sup data-n=\"9918\">1093</sup> ואבדה חכמת חכמיו ובינת נבונים<sup data-n=\"9919\">1092</sup> כו', כי גם בחי' ח\"ס דא\"א הנ\"ל ע\"ז א' והחכ' מאין תמצא [מאין דבחי'<sup data-n=\"9920\">1094</sup> הכתר] שהוא ג\"ר דע\"י ממקור התענוג כו' וכן בינה דא\"א מקור ההשגה ותפיסא מת\"ת דע\"י (וגבו' דע\"י בח\"ס דא\"א כנ\"ל), ובלא שמחה ותענוג עצמי' בתפלה ובמצות מעשיות שנק' עבודה ואבדה חכמת חכמיו שהוא הסתלקו' המקור הראשון לחו\"ב דא\"א שהוא או\"א ומדות דיש\"ס ויש\"ז אם לא<sup data-n=\"9921\">1095</sup> יאיר מעצמו' ע\"י בחב\"ד דא\"א וממילא יחרב ויבש מעי[נות] דחו\"ב בנש\"י [ל]מטה שלא יהי' גילוי סוד ה' ליריאיו ואף בחכמת חכמיו דתושב\"כ ותושבע\"פ ונק' בינת נבונים תסת[ת]ר. וזהו הפלא ופלא ב' פלאות דחו\"ב [ב]מקורם הראשון דפנימי' דע\"י וגם ענין עליות הנ\"ל<sup data-n=\"9922\">1096</sup> דא\"א בע\"י [ולמעלה] זהו מה שא' ואבדה שבעל[י]תו למעלה ממד[ריג]תו העצמי' [י]תבטל שם במציאות כביטול חכ' בעצם התענוג המרומם וגם מו\"ס דע\"י במל' דא\"ס וכן בינת נבונים מקור דבינה דא\"א תסתתר בבינה שלמעלה בעצם החו\"ב דמל' דא\"ס שנק' חכים ולא בחכ' ידיעא כו' וד\"ל (וכמו בגלות<sup data-n=\"9923\">1097</sup> שנק' בחי'<sup data-n=\"9924\">1098</sup> שינה דקוב\"ה אסתלק [לעילא] לעילא<sup data-n=\"9925\">1099</sup> קוב\"ה הוא בחי' ז\"א<sup data-n=\"9926\">1100</sup> יש\"[ז] וכן ביש\"ס בא\"א עד מל' דא\"ס), אבל אראנו נפלאות זהו שיראה בנפלאות הללו דמל' דא\"ס בג\"ר דע\"י ומג\"ר דע\"י [בז\"ת דע\"י ו]א\"א [ב]גילוי גמור דוקא כמו שיהי' הגילוי בהעלם דים ליבשה בקי\"ס בבקיעת הפרסא מלמעלמ\"ט מאצי' לבריא' כנ\"ל, רק שלע\"ל יהי' זה בדרך עלי' דוקא ש[י]עלה ליש\"ס ברום המעלות בנפלאות הנ\"ל וכנ\"ל בענין קחם על זרועותיו כו' (כמשי\"ת) וד\"ל.",[["9914","1088","<b>בכ\"ז</b>: שם: בקול זה."],["9915","1089","<b>שיר פשוט שיר אל</b>: ראה גם לעיל פ' בא קו, ד ואילך."],["9916","1090","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג (המשך הכתוב יען נגש). ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>). לקמן פ' תצוה שלח, ג. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680208\" data-slug=\"torat-chaim\" data-id=\"2300680208\">תו\"ח ויחי רמב, ג</a> הערה 44."],["9917","1091","<b>תחת. . וטוב לבב</b>: תבוא כח, מז [ושם: ובטוב — ראה גם לקמן פ' תצוה שמג, ג [ושם הוגה מגוכתי\"ק]. שעד, ד. הנסמן במאמרי אדה\"א קונטרסים ס\"ע שיט]."],["9918","1093","<b>כו'</b>: ה: ניתוסף: אז. יז: ואז."],["9919","1092","<b>הפלא ופלא. . ואבדה. . נבונים </b>[ויז: נבוניו]: ישעי' כט, יד."],["9920","1094","<b>דבחי'</b>: אה: דפנימי'."],["9921","1095","<b>אם לא</b>: שם: כו' שלא."],["9922","1096","<b>עליות הנ\"ל</b>: יז: עלי' הג'."],["9923","1097","<b>בגלות. . שינה</b>: נסמן לעיל פ' שמות כה, א."],["9924","1098","<b>בחי'</b>: היז: ליתא."],["9925","1099","<b>דקוב\"ה אסתלק </b>[לעילא]<b> לעילא</b>: נסמן לעיל פ' שמות לט, א."],["9926","1100","<b>קוב\"ה. . ז\"א</b>: נסמן לעיל פ' וארא נד, ג."]]],[2300541064,"<b>וזהו</b> עד יעבור הא' בחי' שם הוי' כי בחי' עלי' הא' הנ\"ל בי\"ס דא\"א זהו בשם הוי' עדיין דקוש\"י כתר<sup data-n=\"9927\">1101</sup> דחכ' [ו]יו\"ד חכ' וה' בינה<sup data-n=\"9928\">1102</sup> וי\"ו מדות כו' שהוא העלם וגילוי דחו\"ב ומדות דאצי' ממש, אבל בג\"ר דע\"י <span data-k=\"pg\">רצו</span> ּ שעולה במל' דא\"ס שם הוא למעלה משם הוי' בגילוי עדיין כנ\"ל שהוא בכח היולי דעונג הנעלם מקור כל התענוגים כו' שלמעלה מהיות מקור לרצון וחכ' ומדות כו' וד\"ל. ועכ\"ז גם זה עולה בעצמו' א\"ס ב\"ה כמ\"ש כי עמך מקו\"ח באורך העצמי ממש נראה אור בעוה\"ז שז\"ש עם זו קנית ממש כו'. והענין הוא כמבואר למעלה בענין קחם על זרועותיו שביצי\"מ הי' השפל' היד הגדולה ויד החזקה<sup data-n=\"9929\">1103</sup> דא\"א כו' ולע\"ל יגביה לישראל ביד הגדולה דחסד דע\"י [וא\"א] למעלה הגבה מאד נעלה מראשו הנק' רדל\"א<sup data-n=\"9930\">1104</sup> כו' (דהיינו למעלה [גם] מג\"ר דא\"ק<sup data-n=\"9931\">1105</sup> כענין וכל קומה לפניך כו' קומת א\"ק<sup data-n=\"9932\">1106</sup> דראשו בקו\"ח וסופו בעשי' כו' ונק' אדם דבריאה לבד [כ]אדה\"ר כו') כמ\"ש במ\"א בענין וישא אהרן את ידיו<sup data-n=\"9933\">1107</sup> שנש[י]את כפים [עו]לה במקיף [הכללי] דיחידה שלמעלה מעלה הרבה [מן הראש]. וזהו שנא' וידינו פרושות כנשרי שמים<sup data-n=\"9934\">1108</sup> כו' והוא שמאיר בידינו דוקא שהרי יכול להגביה ידיו באורך למעלה מראשו והוא שאנו רואים בסיפוק הידים בשמחה גדולה או להיפך בעוצב כו' שמאיר בזה מעצמות המקיף דיחידה (שמתפשט בד\"א שלו<sup data-n=\"9935\">1109</sup> בלבד) (כמשי\"ת<sup data-n=\"9936\">1110</sup> ) שזהו מאמר דבראשית שימצא בחו\"ג דמ\"ה דוקא<sup data-n=\"9937\">1111</sup> וד\"ל. וזהו המשך הפסוקי' תפול עליהם אימתה ממל' דא\"ס [עצמו] לע\"ל, בגדול זרועך בחי' היד הגדולה דא\"א שעולה למעלה מראשו שע\"ז א' אראנו נפלאות ליש\"ס, שישראל זה ראה היד הגדולה הזאת בירידה והשפלה למטה בכח<sup data-n=\"9938\">1112</sup> א[חד] לירידה ע\"ד העלי'<sup data-n=\"9939\">1113</sup> כנ\"ל וד\"ל. עד יעבור בנחל מצרים בז\"ת דבינה עד יעבור עוד בז\"ת דע\"י שלא ע\"י חו\"ב דא\"א מעונג הנעלם במורגש בהעברה הב' בנהר פרת כנ\"ל, עם זו קנית בעוה\"ב שנק' חד חרוב<sup data-n=\"9940\">1114</sup> לעלות למעלה עוד<sup data-n=\"9941\">1115</sup> גם מעונג המורגש דעוה\"ב שנמשך מעונג הנעלם דעדן והוא מה שא' דת\"ח אין להם מנוחה אפי' בעוה\"ב שנא' ילכו<sup data-n=\"9942\">1116</sup> מחיל אל חיל<sup data-n=\"9943\">1117</sup> כו' שזהו שם דוקא נשמחה בו ממש שלמעלה מחיי העוה\"ב כמ\"ש במ\"א וד\"ל.",[["9927","1101","<b>דקוש\"י כתר</b>: נסמן לעיל פ' בא קכב, א."],["9928","1102","<b>[ו]יו\"ד חכ' וה' בינה</b>: נסמן לעיל פ' שמות יב, ד."],["9929","1103","<b>ויד החזקה</b>: היז: ליתא."],["9930","1104","<b>רדל\"א</b>: נסמן לעיל קסז, ב."],["9931","1105","<b>דא\"ק</b>: יז: דע\"י."],["9932","1106","<b>וכל קומה. . קומת א\"ק</b>: נסמן לעיל קמו, ב."],["9933","1107","<b>וישא אהרן את ידיו</b>: נסמן לעיל פ' וארא עב, ב."],["9934","1108","<b>וידינו פרושות כנשרי שמים</b>: נוסח נשמת. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680440\" data-slug=\"torat-chaim\" data-id=\"2300680440\">תו\"ח תולדות קנט, ג</a> הערה 39."],["9935","1109","<b>דיחידה. . בד\"א שלו</b>: נסמן לעיל קעט, ד."],["9936","1110","<b>(כמשי\"ת)</b>: היז: כמ\"ש במ\"א."],["9937","1111","<b>דבראשית שימצא בחו\"ג דמ\"ה דוקא</b>: שם: דרישא דמלכא בחו\"ג דידי' דוקא אתתקן כו' — נסמן לעיל פ' בא צ, ד."],["9938","1112","<b>בכח</b>: שם: ליתא."],["9939","1113","<b>ע\"ד העלי'</b>: שם: עם עלי'."],["9940","1114","<b>חד חרוב</b>: נסמן לעיל פ' שמות כג, א."],["9941","1115","<b>עוד</b>: שם: ליתא."],["9942","1116","<b>דת\"ח אין להם מנוחה. . ילכו</b>: נסמן לעיל פ' שמות ד, ג."],["9943","1117","<b>מחיל אל חיל</b>: שם: ליתא."]]],[2300540073,"<b>בעז\"ה ליל אחרון של פסח</b>\n<span data-k=\"pg\">594</span> ּ<b>להבין</b> שרשן של כל דברים הנ\"ל<sup data-n=\"9944\">1</sup>, צ\"ל תחלה מאמר הזהר פ' בשלח בשעתא דנהורא<sup data-n=\"9945\">2</sup> דעתיקא נהיר ואתגלי' כו' וימא עילאה עביד נימוסי עילאין כו', ואחר זה מיד מזכיר ענין הלידה עד בהאי מלה לא תשאל<sup data-n=\"9946\">3</sup> כו' ע\"ש. הנה ידוע דבשמע\"צ הוא הקליטה<sup data-n=\"9947\">4</sup> ויולדת לז' יולדת למקוטעין<sup data-n=\"9948\">5</sup>, והיינו לו' ועוד<sup data-n=\"9949\">6</sup>, עד שבז' ש\"פ זמן הלידה כו'. וצריך להבין תחלה ענין זווג זו\"נ להוליד נשמות, הנה הדיבור למעלה באלקות אינו כדיבורינו שהרי לא תמצא ענין הדיבור שלנו כ\"א בדיבורים שכבר ישנם בעולם, כמו שידבר האדם בדבר הלכה שכבר אותיות כתובים כו', או שידבר במילי דעלמא שכבר האותיות [ההם] ישנם במציאות כו'. אמנם בדיבור העליון בדבר ה' שמים נעשו<sup data-n=\"9950\">7</sup> הרי אותו הדיבור לא נתגלה עדיין מעולם בשום מציאות שאל\"כ היו השמים במציאות דבר<sup data-n=\"9951\">8</sup> קודם שאמר יהי רקיע<sup data-n=\"9952\">9</sup> וזה אינו כידוע. ולטעם זה יובן ההפרש בין הנשמות להמלאכים בהיות שהמלאכים המה נמשכים מדבר ה'<sup data-n=\"9953\">10</sup> והבל פיו כידוע ע\"כ יש בכחם לפעול פעולת עו\"ע, משא\"כ בנשמה שאינה משפעת מאין ליש כו'. מ\"מ [יש] יתרון מעלה בנשמות להיות שאינה נמשכת מן הדיבור שהוא רק לבוש כידוע אלא היא נמשכת מבחי' עצמות המאציל, כמשל התהוות הולד מטיפה גשמיות שיוצאת מן המוח כו', וכל התהוות עו\"ע אינו אלא מבחי' לבושי' לבד לכך הנשמה שהיא מבחי' עצמיות אינה משפעת כו'. והנה עיקר ההפרש בין הנשמות להמלאכי' שהנשמה נזרעה בבחי' אור זרו\"ע לצדיק ח\"י עלמין<sup data-n=\"9954\">11</sup> בחי' יסוד ז\"א דאצי' שכלול מחו\"ב שבו, וגם מחכ' דאצי' שבו התלבשו' אא\"ס<sup data-n=\"9955\">12</sup> דוקא כידוע, אבל המלאכים אינם בבחי' זריע\"ה כלל כ\"א כמו [התגלות] האותיות מחו\"ד כו'. וע\"כ לא תמצא בחי' ביטול המציאות בנשמות כמו במלאכי'<sup data-n=\"9956\">13</sup> לא מיני' ולא מקצתי'<sup data-n=\"9957\">14</sup> אפי' בנשמות הגבוהות כמו נשמת<sup data-n=\"9958\">*15</sup> אברהם ויצחק שהיו בחי' מרכבה<sup data-n=\"9959\">15</sup> כו', והטעם הוא כנ\"ל שבהיותם א\"ע<sup data-n=\"9960\">16</sup> (אור)<sup data-n=\"9961\">17</sup> זרוע הרי הם כמו העצמות והביטול לא יתכן אלא בדבר הנפרד דוקא, שהרי היד והרגל של אדם לא יתכן לומר עליהם שהם בטלים לגבי האדם מאחר שהם מעצמות האדם אבל [על] הכלי שביד יתכן לומר שהיא בטילה",[["9944","1","<b>להבין שרשן של כל דברים הנ\"ל</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז מליל אחש\"פ תקס\"ב. ד: נרשם בגוכי\"ק כ\"ק אדמו\"ר הצ\"צ: ”ביאור על בה\"ז בשלח ד\"ה עוי\"ל מאמ' הנ\"ל באופן אחר\" [ביאוה\"ז מב, ג. וראה גם מאמרי אדה\"ז תקס\"ב ח\"ב ע' ת ואילך]. נדפס גם במאמרי אדה\"ז תקס\"ב ח\"ב ע' תח. ונדפס בשינויים בביאוה\"ז להצ\"צ כרך א ע' ריז ואילך. וחלק נעתק באוה\"ת (יהל אור) תהלים ע' קמט. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["9945","2","<b>בשעתא דנהורא</b>: אב: דנהירו."],["9946","3","<b>בשעתא דנהורא. . לא תשאל</b>: ראה זהר בשלח נב, ב."],["9947","4","<b>דבשמע\"צ הוא הקליטה</b>: ראה פע\"ח (שער הלולב) שכ\"ט, ספ\"ח. מאמרי אדה\"א ויקרא ח\"א ע' שפז. וש\"נ. דברים ח\"ד ע' א'רעט בשם הע\"ח."],["9948","5","<b>ויולדת לז' יולדת למקוטעין</b>: ראש השנה יא, א."],["9949","6","<b>לו' </b>[ב: ו\"ח]<b> ועוד</b>: ראה מאמרי אדה\"א ויקרא שם בהערה: וז' חדשים."],["9950","7","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["9951","8","<b>דבר</b>: אב: ובביאוה\"ז כאן: כבר."],["9952","9","<b>יהי רקיע</b>: בראשית א, ו."],["9953","10","<b>שהמלאכים. . מדבר ה'</b>: ראה גם לעיל פ' שמות לט, ד. וש\"נ."],["9954","11","<b>אור זרו\"ע לצדיק ח\"י עלמין</b>: תהלים צז, יא. ראה זהר (רע\"מ) פינחס רכז, א."],["9955","12","<b>מחכ'. . התלבשו' אא\"ס</b>: נסמן לעיל פ' שמות ז, ד."],["9956","13","<b>לא תמצא בחי' ביטול המציאות בנשמות כמו במלאכי'</b>: ראה גם ביאוה\"ז בשלח מה, ג."],["9957","14","<b>לא מיני' ולא מקצתי'</b>: סוטה ה, א."],["9958","*15","<b>נשמת</b>: ב: האבות."],["9959","15","<b>אברהם ויצחק. . מרכבה</b>: נסמן לעיל פ' שמות ה, ג."],["9960","16","<b>א\"ע</b>: אור עליון אור עצמי"],["9961","17","<b>(אור)</b>: אב: ליתא."]]],[2300540111,"להניע כרצונו כו'. וכן עיקר טעם ההפרש בין עבד לאדון ובן לאביו שימצא תכלית הביטול בעבד ולא בבן לאביו הוא מטעם זה להיות כי הבן הוא מעצמות האב וכל עצם לא יבוטל מפני עצמות כו', אבל העבד שהוא נפרד מהאדון שייך בו הביטול ממציאותו בהיות שכאשר יתבטל אז יבא לבחי' עצמו' האדון מה שלא הי' כן מתחילה משא\"כ בבן שגם מתחלה הי' מן העצמות וד\"ל. ובזה יובן ענין ביטול המציאות שבמלאכים בעלמא דאתכסי' הנק' נוני ימא<sup data-n=\"9962\">18</sup> כו', משא\"כ בנשמות הגבוהות שאין זה מטעם שהנשמות הן מבחי' ארץ כו' שהרי הנשמות גבוהות מאד נעלה מן המלאכים כידוע. אך הטעם הוא מפני שהנשמות הם מבחי' זריע\"ה שהיו בבחי' <span data-k=\"pg\">רצז</span> ּ עצמיות ע\"כ לא הי'<sup data-n=\"9963\">19</sup> בהם הביטול במציאות כמו במלאכים כו'. אמנם צ\"ל בזה דהנה גם הנשמות כשהיו בבחי' עיבור במעי הנוק' דז\"א כו' היו בתכלית הביטול במציאות כמו נוני ימא ממש, שהרי עובר ירך אמו<sup data-n=\"9964\">20</sup> הוא<sup data-n=\"9965\">21</sup> ואוכל ממה שאמו אוכלת<sup data-n=\"9966\">22</sup> וראשו בין ברכיו<sup data-n=\"9967\">23</sup> בבחי' ביטול מציאותו שהוא כמו ההשתחוו\"א' באדם הנפרד שמרכין ראשו למטה מרגליו של האדם<sup data-n=\"9968\">24</sup>, כן משתחווה הולד ראשו בין ברכיו, פי' אין לו חיים מצד עצמו כלום, והרי הוא כא' מאברי' וגם ראשו מקבל ממה שאמו אוכלת כמו שמקבלים רגליו כו'. וכמו שבנוני ימא הים מובלע בהם מכל צד כנ\"ל, כן חיות הולד מתאחד בתכלית האחדות עם החיות של אמו עד שאינו דבר בפ\"ע כלל, שהרי לא יוכל לסתור דברי אמו בעודינה בבטנה כו', וגם הבטן מכסה עליו מכל צדדיו עד שאינו נראה ליש ודבר בפ\"ע כלל כו', וכמו שהדגים מובלעים בים והים מכסה עליהם כו', וא\"כ גם בחי' עיבור יקרא בשם עלמא דאתכסיא [כמו הים], ולמה יהי' הפרש בין נשמות למלאכים. אך הענין הוא דעיקר ההפרש הוא מטעם הלידה כמשי\"ת בעזר\"ה.\n<b>אמנם</b><sup data-n=\"9969\">25</sup> צריך להקדים שגם בעיבור יש דבר נוסף בנשמות, משא\"כ במלאכים והוא ענין לבושי הנשמות שהוא בחי' צלם, אך בצלם יתהלך איש<sup data-n=\"9970\">26</sup>, דהנה בשעת יצירת הנפש בחיבור הגוף עמה נוצרה בחי' צלם הנפש והוא למעלה מהנפש אפי' מבחי' חי' יחידה שבה. והענין הוא בהיות כי שהנפש והגוף המה ב' הפכים ממש ושיחי' הגוף מחיי הנפש הרוחניות נמשך לזה כח",[["9962","18","<b>שבמלאכים. . נוני ימא</b>: ראה זהר הרקיע שמות יא, ב (מט, א בדפי הספר). ביאוה\"ז בשלח מב, ג. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תא. מאמרי אדה\"א ויקרא ח\"א ע' שעג."],["9963","19","<b>הי'</b>: אב: יש."],["9964","20","<b>עובר ירך אמו הוא</b>: גיטין כג, ב."],["9965","21","<b>הוא</b>: א: ליתא."],["9966","22","<b>ואוכל ממה שאמו אוכלת</b>: נדה ל, ב."],["9967","23","<b>וראשו בין ברכיו</b>: נדה שם."],["9968","24","<b>האדם</b>: אב: האדון."],["9969","25","<b>אמנם</b>: מכאן נעתק באוה\"ת (יהל אור) תהלים ע' קמט (בשינויים קלים)."],["9970","26","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז. ראה גם ע\"ח (שער הצלם) שכ\"ו, פ\"א. מאמרי אדה\"ז תקס\"ד ע' קסה [ושם: בספרי הטבע] וע' קע. תקס\"ו ע' קעט. מארז\"ל ע' לז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380280\" data-slug=\"likkutei-torah\" data-id=\"4001380280\">לקו\"ת בחוקותי מז, ג</a>. שער האמונה מז, ריש ע\"ב. מאמרי אדה\"א הנחות תקע\"ז ע' רג. במדבר ח\"ד ס\"ע א'תו ואילך. לקמן פ' תרומה שיג, ג."]]],[2300540149,"רוחני בפ\"ע שהוא המחבר את הנפש בתוך הגוף<sup data-n=\"9971\">*27</sup> שיתקיים בו להחיותם<sup data-n=\"9972\">27</sup> כו', ואם לא כח רוחני זה המחברם הי' הסתלקות הנפש מן הגוף מיד כו', ומאחר שכח רוחני זה ביכולתו להכריח את הנפש שתצא חוץ לגדרה וטבעה לחיות בחיי בשר הגוף הגשמי כו' מוכרח שיהי' כחו רב ועצום הרבה מכח הנפש עד שתמשול בו. וזהו אשר בצלם זה יתהלך אי\"ש הוא הנר\"ן ח\"י כו', ופי' יתהלך הוא הילוך דרכי החיות הנפש בכלי הגוף בכל פרטי האופנים, אפי' להיות לו רצון כך ולא כך שהוא מבחי' יחידה כידוע, הכל הוא ע\"פ הצל\"ם המכריחו לכך, דהיינו להיות חיבור היחידה בגוף ברצון כך ולא כך כו' וד\"ל. והנה צלמים אלו באים בגילוי באדם לאחר שנולד מעט מעט<sup data-n=\"9973\">28</sup> כנז' בע\"ח עד שבימי הזקנה מתיישבת על בוריו. וזהו ענין מארז\"ל דעת\"[ן] מתיישבת עליהם שנאמר על הזקנים<sup data-n=\"9974\">29</sup> וענוים<sup data-n=\"9975\">30</sup> הוא שהדעת נתחבר היטב עם מזג טבעיות הגוף ואינם מנגדים כ\"כ כמו ברתיחת הילדים כו', והוא מפני גילוי כח המחברם ביותר והוא הצלם כנ\"ל וד\"ל. ואמנם מתגשמים [הצלמים] עד שנראים ומתגלים בבחי' לבושי' לבד, כלשון הר\"מ האי דיוקנא דקיימא עלי' דב\"נ<sup data-n=\"9976\">31</sup> כו', וכל נשמה הוה קיימא בדיוקנה\"א קמי' מלכא קדישא<sup data-n=\"9977\">32</sup>, שהוא בזריעה או\"ר לצדיק כו' עד דלא אצטיירא במעי הנוק' דז\"א כו'. והנה זה הכח המחבר הוא הגורם לאדם להיות יש ודבר כאילו אינו מצטרך לשום מקור כו', וכענין על כרחך אתה חי<sup data-n=\"9978\">33</sup> כו' וד\"ל. אך הנה <span data-k=\"pg\">596</span> ּ כמו\"כ בבחי' אצי' הנשמות בבטן מל' דאצי' נוצרו בחי' צלמי' עמה והם מחיצוני' ע\"י שבבינה, והוא ענין התורה והמצות שמלבישים ומסתירים העונג אלקי שבחכ' הגנוזה בחי' ח\"ס כו' וד\"ל, [עד אשר אפי' תחפוץ הנשמה אלקית לאחר שנולדה לצאת מנרתיק הגוף תתעכב בגוף ע\"י<sup data-n=\"9979\">34</sup> מעשה המצות כנ\"ל וד\"ל].\n<b>והנה</b> צל\"ה<sup data-n=\"9980\">35</sup> עתה ההפרש בין עיבור ללידה, כי הנה אנו רואים כאשר יוולד הולד ויוצא לאויר העולם מיד יהי' בחי' נפרד לעצמו בהיפוך מכמו שהי' בבטן אמו, שהרי יוכל לסתור דברי אמו ולעשות נגד רצונה והעיקר הוא מפני כי איננ[ו] נצרך אליה כלל לקבל עוד שפע ממנה כלל וכלל, בהיות שכאשר הי' בבטן הי' חיותו ממאכל שכבר אכלתו אמו ונעשה דם וחיות אז קיבל הולד דרך טבורו הפתוח לתוך מעיו ולא קבלו דרך פיו כו'. נמצא יש כאן ב' דברים א' שאינו מקבל חיות המאכל עצמו וגם עוד זאת שמקבל דרך טבורו דהיינו שלא בדרך טעימה בפה כו', ואמנם לאחר שנולד יתוספו בו ב' דברים הנ\"ל שמקבל חיות המאכל עצמו וגם הנה אוכלו בפה ולועסו בחיך ושינים שאז הוא מרגיש טעם רוחני שבמאכל כו', ונמצא",[["9971","*27","<b>כח רוחני. . המחבר את הנפש בתוך הגוף</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשנב."],["9972","27","<b>להחיותם</b>: אב: ובאוה\"ת תהלים: להחיותו."],["9973","28","<b>צלמים. . מעט מעט</b>: ראה ע\"ח (שער המוחין) ש\"כ, פ\"ז."],["9974","29","<b>דעת\"[ן] מתיישבת עליהם. . הזקנים</b>: ראה קנים פ\"ג, מ\"ו. לקמן פ' משפטים ש, ג."],["9975","30","<b>וענוים</b>: א: וענינם. ב ואוה\"ת שם: וענינו."],["9976","31","<b>האי דיוקנא דקיימא עלי' דב\"נ</b>: ראה זהר ויחי ריז, ב. תזריע מג, א. ב. אמור קד, ב. (רע\"מ) נשא קכב, ב."],["9977","32","<b>וכל נשמה. . בדיוקנא\"ה קמי' מלכא קדישא</b>: ראה הערה בסה\"מ ה'תש\"ח ע' 182. סה\"מ תרנ\"ד ע' רסג."],["9978","33","<b>על כרחך אתה חי</b>: אבות ספ\"ד."],["9979","34","<b>תתעכב בגוף ע\"י</b>: ניתוסף ע\"פ אוה\"ת כאן. א: מטושטש. . הגוף."],["9980","35","<b>צל\"ה</b>: ב: צריך להבין."]]],[2300540186,"שעיקר היתרון הוא רק שמקבל טעם המאכל, וכענין אין התינוק יודע לקרות או\"א עד שיטעום טע\"ם דגן<sup data-n=\"9981\">36</sup> כו', ומה שהוא טועם טעמי\"ם שבמאכלים הוא הגורם עיקר סיבת הפירוד [שלו מאמו] שאי[ננו] מצטרך אליה כלל והוא נעשה ברי' בפ\"ע לגמרי כו'. אך י\"ל הטעם למה יגרום זה סיבת הפירוד וכי המאכלים בעצם חשובים מהמאכל שכבר אכלתו אמו כו', הענין הוא דידוע שהמאכלים נפלו בשבה\"כ<sup data-n=\"9982\">37</sup> ובהטעם נרגש בהם יש בו מבחי' טע\"ם העליו\"ן הוא העונג האלקי הנרגש בחיצוני' בינה [ש]הוא בחי' חיצוניות ע\"י כו' וכמ\"ש במ\"א בארוכה [וע\"כ כח טעם [ה]מאכל\"י' עצום ורב] עד שהם גורמים הגבהת והתנשאות הולד להיות יש ודבר בפ\"ע לגמר\"י עד שיוכל לומר לי יאורי<sup data-n=\"9983\">38</sup> כו', מפני ששרש הטעמי\"ם ותענוגי עוה\"ז קודם שנפלו בשבירה הוא מבחי' עתיקא סתימאה<sup data-n=\"9984\">39</sup> כו' שלימותא דכולא<sup data-n=\"9985\">40</sup> בחי' היש האמיתי כו' וד\"ל.\n<b>ועד\"ז</b> יובן ברוחניות הנשמות בהולדם מבטן המל' דאצי' שעיקר ההפרש בין עיבור ללידה הוא ענין טעמי תו' ומצות הנגלית שבהן תתענג הנפש אלקי' לאחר שנולדה והוא הגורם להיות יש ודבר בגופה כנ\"ל, מפני שהטעמים המוסתרים בתורה הנגלית הוא מבחי' חיצוניות ע\"י כנ\"ל ובהיותו בבטן מל' דאצי' בבחי' ביטול במציאות הי' אוכל ממה שאמו אוכלת ודרך טבורו פי' שלא טעם טעם העונג האלקי שבחכמת התורה בעצמותה כו' כ\"א ממה שכבר אכלתו אמו הוא בחי' בינה שבמל', שכבר נתהפך בה ההלכה להשיג אלקות ולא לעצמות ומהות התורה כו', ואמנם בהולדו שאע\"פ שנתלבשה ההלכה בלבושי' גשמי' ביותר, כמו פשוטי ההלכות, עכ\"ז הרי עדיין הם מהות חכמתו ית', והטעם שבהם מבחי' הטע\"ם והעונג האלקי [ה]עצמ[י] רק שנתלבש בריבוי הלבושים כו', וה\"ז כמשל המאכלי\"ם ממש וד\"ל. וגם עוד זאת שמברר ההלכה בבחי' חי\"ך ושיניי\"ם כו', פי' בשכל והשגת הנשמה כו' וד\"ל. ונמצא מובן מכל הנ\"ל שגם בבחי' עיבור יש הפרש בין נשמות למלאכים מצד הלבושים והצלמים ואע\"פ שלא יש בהם כ\"א ממה שאמו אוכלת כו', עכ\"ז גדלה וגבהה מעלתו הרבה בזה <span data-k=\"pg\">חצר</span> ּ על המלאכים שלא ניתנה תורה להם כלל כו'. ואמנם עיקר ההפרש הוא מצד הלידה דלאחר שנולדו מקבלים שפעם מחיצוני' ע\"י, ע\"כ הרי הם יש ודבר בפ\"ע כנ\"ל, משא\"כ במלאכים. ומעלת המלאכים בבחי' הביטול גם בנשמות כשהיו בבחי' עיבור כנ\"ל, וכנז' בדברי האריז\"ל ענין ג' מיני עיבור של ז\"ח וט\"ח ויב\"ח<sup data-n=\"9986\">41</sup> שאותן הנשמות שנשתהו י\"ב חדש נתקשרו בקשר אמיץ ביותר בבטן",[["9981","36","<b>אין התינוק יודע. . דגן</b>: נסמן לעיל פ' בא צה, ב."],["9982","37","<b>שהמאכלים נפלו בשבה\"כ</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קכ."],["9983","38","<b>לי יאורי</b>: יחזקאל כט, ג."],["9984","39","<b>עתיקא סתימאה</b>: ראה גם לעיל רב, ד. וש\"נ."],["9985","40","<b>שלימותא דכולא</b>: נסמן לעיל פ' שמות מח, ב."],["9986","41","<b>בדברי האריז\"ל. . עיבור של ז\"ח וט\"ח ויב\"ח</b>: ראה ע\"ח (שער העיבורים) שכ\"ח, פ\"ב. פ\"ג. שער הכללים פ\"ג. שער ההקדמות (דרוש ג' בענין תיקון זעיר ונוקבי') קסב, ב ואילך. כנפי יונה ח\"א פי\"ב."]]],[2300540223,"המל' המה רחוקי' יותר מן הנפילה ברע מפני שנתגבר בהן בחי' הביטול העצמי ע\"י רוב שהיית\"ם כו' כענין נוני ימא כו' אשר מטעם זה נק' הנשמות הגבוהות בשם נוני ימא<sup data-n=\"9987\">42</sup> כמו נשמת רב המנונא סבא<sup data-n=\"9988\">43</sup> וכן במשה [רבינו] ע\"ה כתיב כי מן המים משיתיהו<sup data-n=\"9989\">44</sup> וכמ\"ש במ\"א וד\"ל. ועיבור דט\"ח<sup data-n=\"9990\">*45</sup> שלא נתקשרו כ\"כ בקשר אמיץ אין בהם בחי' הביטול כ\"כ אע\"פ שיכול להיות גבוהים במדריגות השגת החכמה מן הנשמות דעיבור י\"ב חדש כו', אבל בענין הביטול הם נמוכים מהם וכמו אליהו שנהפך גופו למלאך<sup data-n=\"9991\">45</sup> מה שלא הי' ביכולת כן להאבות<sup data-n=\"9992\">46</sup> כו' עד שעיבור י\"ב חדש<sup data-n=\"9993\">47</sup> הם הנפילים אשר היו בארץ<sup data-n=\"9994\">48</sup> כו' כמ\"ש במ\"א וד\"ל.\n<b>ועתה</b> יובן ענין סמיכות מאמר הלידה למאמר הנ\"ל דנהיר\"ו דעתיקא אתגלי' כו', בהיות דמצד הלידה הוא עיקר ההגבהה והתנשאות הנשמה על המלאך ודוקא במה שהוא יש ודבר כנ\"ל. אמנם י\"ל דהא אין התינוק אוכל [ו]ט[ו]עם עד לאחר הלידה הרבה ואז שייך לומר שיהי' עי\"ז יש ודבר, אבל באותו הרגע שנולד [ש]עדיין לא אכל וטעם כלום למה מיד בהוולדו הוא יש ודבר בפ\"ע כו'. אך הענין הוא דבאמת יש הפרש גדול בין [כ]שהוא כבר יש ודבר ע\"י המאכלים שאכל כו' ובין הכח הרוחני אשר עושה אות[ו] באופן זה שיוכל להיות יש ודבר כנ\"ל ביש הנפרד שאותו כח השופע שיהי' יש הוא מהארת היש האמיתי כו'. וזהו ענין ההפרש בין בשעת הלידה לאח\"כ, דבשעת הלידה מאיר בו פנימי' העונ\"ג שהרי במאכלי\"ם הוא בהתלבשות והסת\"ר כו' ובשעת הלידה הוא ענין אותו העונג כמו שהי' קודם שנפל בשביר\"ה שהוא פנימי' הארת היש האמיתי, ולע\"ל תהי' אותה ההארה בגילוי גמור דהיינו שלא יסתירו המסכים והלבושי' של תענוגי עוה\"ז כלל וכלל כו'. ואמנם בשעת הליכתם בים היתה אותה ההאר\"ה פנימ\"י' דע\"י בעלמא דאתכסי' כנ\"ל אך לא בי\"ם לבד כ\"א בהפיכת הים ליבשה כו', והיינו כדוגמת שע\"ת הליד\"ה ממש שאז הוא הכח להיות יש ודבר בלתי טעם המאכלים שהוא רק חיצוניות הארה זו וד\"ל. וזהו דנהי\"ר נהיר\"ו דע\"י דוקא פי' פנימי' עונג העליון המוסתר בתומ\"צ שהן לבושי",[["9987","42","<b>הנשמות. . נוני ימא</b>: ראה גם ביאוה\"ז בשלח מא, ג [ושם: דמשמע בזהר בכמה דוכתי]. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670491\" data-slug=\"torat-chaim\" data-id=\"2300670491\">תו\"ח בראשית מג, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670329\" data-slug=\"torat-chaim\" data-id=\"2300670329\">שה\"א פה, א</a>. לקמן פ' יתרו רסה, א."],["9988","43","<b>נשמת רב המנונא סבא</b>: נסמן לעיל פ' בא צט, ג."],["9989","44","<b>כי מן המים משיתיהו</b>: שמות ב, י. ראה גם לעיל פ' שמות מג, א ובהנסמן שם."],["9990","*45","<b>וכמ\"ש. . דט\"ח</b>: ג: ועיבור דט\"ח וז\"ח."],["9991","45","<b>אליהו שנהפך גופו למלאך</b>: ראה גם לעיל קצו, ג. וש\"נ."],["9992","46","<b>אליהו. . להאבות</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקנד. וש\"נ. דרושי חתונה ח\"א ע' קיד. תו\"ח ויצא קעח, ב. שה\"א ק, ב."],["9993","47","<b>י\"ב חדש</b>: אב: דג\"ח. ג: פחות מז\"ח."],["9994","48","<b>הנפילים אשר היו בארץ</b>: ראה בראשית ו, ד. וראה גם בענין הנפילים פע\"ח (שער הלולב) שכ\"ט, ספ\"ח. (שער חה\"מ) שכ\"א, רפ\"א. מאמרי אדה\"ז תקע\"א ע' קס. שע\"ת מו, ג. שער האמונה ק, א. הנסמן במאמרי אדה\"א קונטרסים ע' רלד."]]],[2300540255,"הנשמות כנ\"ל נתגלה אז אך לא בגילוי גמור כו'<sup data-n=\"9995\">*49</sup> בבחי' יבשה לבד כמו שיהי' לע\"ל כו' לכך סמך לזה ענין הלידה וד\"ל.\n<b>ובכל</b> הנ\"ל יובן יוצר אור ובורא חשך<sup data-n=\"9996\">49</sup>, שהבריא\"ה הוא עלמא דאתכסייא נק' חשך ע\"ש הביטול המופלג כו', ויצ\"י' הוא הליד\"ה נק' אור אשר הארת פנימי' ע\"י כנ\"ל, והיינו המאי\"ר לאר\"ץ<sup data-n=\"9997\">50</sup> דוקא וד\"ל, וזהו בוקע חלוני רקיע<sup data-n=\"9998\">51</sup> מוציא חמה ממקומה ומאיר לעולם כו', פי' כמו שנתבאר למעלה בענין <span data-k=\"pg\">598</span> ּ עיבור ולידה בנשמות כמו\"כ ענין עיבור ולידה בז\"א דאצי' במעי אימא כו'. והיינו בוקע חלוני רקיע שנבקע יסוד אימא בהולדת ז\"א הנק' חמה<sup data-n=\"9999\">52</sup> כידוע, ולכך הוא מאיר לעולם כו', כי בהיות[ו] בבחי' עיבור נק' חושך ולא אור כנ\"ל כי עיקר האור ביצי' כנ\"ל. ובדרך כללות הפרצופים נק' ז\"א דאצי' אדם דעשי', ופרצופי א\"א וע\"י אדם דיצי' וא\"ק אדם דבריאה<sup data-n=\"10000\">53</sup> כו'. ועיקר ענין הארת [האור] העליון ביצי' הוא בבחי' א\"א דכתיב יאר פניו<sup data-n=\"10001\">54</sup> כו' וכשנולד אדם העליון ונפרד מאמו כו' יש בו הארת א\"א וע\"י כנ\"ל. וגם בכל הנ\"ל יובן למה אין קרבן בשביעי של פסח<sup data-n=\"10002\">55</sup> כו' דהקרבן עולת ראי' הוא כשם שבא לראות<sup data-n=\"10003\">56</sup> כך כו' וד\"ל.",[["9995","*49","<b>כו'</b>: ב: היו."],["9996","49","<b>יוצר אור ובורא חשך</b>: נסמן לעיל קמד, ג."],["9997","50","<b>המאי\"ר לאר\"ץ</b>: ברכת יוצר."],["9998","51","<b>בוקע חלוני רקיע</b>: ראה ברכת יוצר לשבת."],["9999","52","<b>ז\"א הנק' חמה</b>: נסמן לעיל רג, ד."],["10000","53","<b>ז\"א. . דעשי'. . דיצי'. . וא\"ק אדם דבריאה</b>: נסמן לעיל קמה, ג הערה 68."],["10001","54","<b>יאר פניו</b>: נשא ו, כה [בדילוג]."],["10002","55","<b>אין קרבן בשביעי של פסח</b>: ראה גם ביאוה\"ז כאן ע' רכז."],["10003","56","<b>כשם שבא לראות</b>: חגיגה ב, א."]]],[2300540074,"<b>יום ה' ל\"ג בעומר בעזרה\"י</b>\n<b>להבין</b> ענין ל\"ג<sup data-n=\"10004\">2</sup> בעומר<sup data-n=\"10005\">1</sup>, הנה בל\"ג בעומר הי' הלולא<sup data-n=\"10006\">4</sup> דרשב\"י<sup data-n=\"10007\">3</sup> כנודע. ולהבין ענינו צריך לידע תחלה ענין מתן תורה שבשבועות<sup data-n=\"10008\">5</sup> דכתיב ביום חתונת\"ו<sup data-n=\"10009\">6</sup> וביום שמחת לבו כו', בהיות כי הלא ידוע שכנ\"י נק' כלה והתורה נק' חתן<sup data-n=\"10010\">7</sup> כמ\"ש תורה צוה לנו משה מאורשה<sup data-n=\"10011\">8</sup> כו' וידוע שיש בתורה ב' מדרגות הנגלה והנסתר כמ\"ש בזוה\"ק דקוב\"ה סתים<sup data-n=\"10012\">9</sup> וגליא<sup data-n=\"10013\">10</sup> כו' ובשבועות הי' התגלות התורה הנגלית בעשרת הדברות כו', ובל\"ג בעומר שהוא תחלה הי' התגלות רזין דאורייתא שהם ע\"ד סתרי הזהר כידוע מפני שבחי' הסתימה שבתורה ירד תחלה",[["10004","2","<b>ל\"ג בעומר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031264\" data-slug=\"likkutei-sichot\" data-id=\"1300031264\">לקו\"ש</a> ל\"ג בעומר (כרך ג) ע' 1002 הערה 3. (כרך ז) ע' 337. (כרך יז) ע' 511."],["10005","1","<b>להבין ענין ל\"ג בעומר</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז משנת תקס\"ב. והנחת הר\"מ בן כ\"ק אדה\"ז נדפסה במאמרי אדה\"ז תקס\"ב ח\"ב ע' תל [ושם ההתחלה: להבין היטב ענין הילולא דרשב\"י]. (וחלק בשינויים נמצא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770406\" data-slug=\"or-hatorah-hb\" data-id=\"8316770406\">אוה\"ת שה\"ש (כרך ב) ע' תו</a>). ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["10006","4","<b>הלולא דרשב\"י</b>: ראה זהר (אד\"ז) האזינו רצו, ב. רצא, סע\"א. ויחי ריח, סע\"א."],["10007","3","<b>בל\"ג בעומר הי' הלולא דרשב\"י</b>: ראה פע\"ח (שער ספה\"ע) שכ\"ב, פ\"ז. מאמרי אדה\"א ויקרא ח\"ב ע' תרסו. וש\"נ."],["10008","5","<b>מתן תורה שבשבועות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081021\" data-slug=\"likkutei-sichot\" data-id=\"1300081021\">לקו\"ש</a> חה\"ש (כרך ח) ע' 21 ובהנסמן שם."],["10009","6","<b>ביום חתונת\"ו</b>: נסמן לעיל פ' בא קיח, ב."],["10010","7","<b>שכנ\"י נק' כלה והתורה נק' חתן</b>: ראה גם מאמרי אדה\"א קונטרסים ע' רעג ובהנסמן שם."],["10011","8","<b>תורה צוה. . מאורשה</b>: ברכה לג, ד. ברכות נז, א. — ראה סידור דרושים לחתונה קכח, א. שה\"א ס, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381102\" data-slug=\"likkutei-torah\" data-id=\"4001381102\">לקו\"ת ברכה צג, סע\"ד</a>."],["10012","9","<b>דקוב\"ה סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א."],["10013","10","<b>וגליא</b>: דיא: ניתוסף: ואורייתא סתים וגליא."]]],[2300540112,"מלמעלה ואח\"כ הגלי' כו', וזהו מלמעלה למטה שאז היותר נעלה במדריגות השפע יורד תחלה אבל מלמטה למעלה דהיינו כשאדם הת\"ח<sup data-n=\"10014\">11</sup> מקבל שפע התורה [בתוכו] כו' לא יוכל להגיע לבחי' הסתימה<sup data-n=\"10015\">12</sup> שבתורה עד שימלא נפשו בגלי' שבה תחלה כידוע וד\"ל.\n<b>והנה</b> ענין החתונה שבשבועות י\"ל ענינה שהוא עד\"מ החתונה של זיווג נשמות שבגופים בעוה\"ז שעל החתן לעשות סעודה<sup data-n=\"10016\">13</sup> ביום החופה בבית הכלה דוקא ואח\"כ כשמביאה לבית[ו] עושה סעודה לבני עירו מחדש, וזהו הנק' סעודת חתן וסעודה שביום החופה היא סעודת הכלה כו', וא\"כ השמחה שביום החופה היא שמחת הכלה והשמחה שלאחר החופה בסעודת החתן בביתו הוא שמחת החתן ועל שמו תקרא כו', וזהו הלשון ביום חתונת\"ו וביום שמחת לב\"ו דוקא וד\"ל. והנה להבין כדוגמת זה למעלה [יובן] עד\"מ מלך בו\"ד כשעושה חתונה לעצמו עם בת זולתו, הנה יוצא הוא מעיר המלוכה עם כ[ל] ב\"ב וכל השרים [ל]בית הכלה לעשות שם הסעודה בבית<sup data-n=\"10017\">14</sup> החופה ואבי הכלה אינו מלך שיעשה סעודה גדולה לפני<sup data-n=\"10018\">15</sup> כבוד המלך והשרים כו', וגם אין לו מקום מכובד כלל כמו פלטרין הנאים כו' להיות כי הוא דר בכפר מן הכפרים [כו'], ואזי עיקר הכבוד בהראות המלך גודל עושרו בזהב וכסף כלים מכ\"ש<sup data-n=\"10019\">16</sup> [ו]אנשיו השרים הגדולים כל אחד מראה כבוד עושרו לפני המלך והכלה בשביל כבוד המלך כו', והכל מתפעלים מאד מעוצם גדולת המלך בעושר מופלג כזה כו', וזה אינו אלא מפני שבכפר לא ראו מעולם אוצרות חמודים וגנזי מלכים ותהי' בעיניהם לפלא גדול כו'. ואמנם לאחר החופה כשבא המלך לעיר המלוכה ועושה סעודה ל[כל] בני עירו וכל שריו שהמה כבר <span data-k=\"pg\">רצט</span> ּ רגילים באוצרי חמודות המלך ולא יהי' בעיניהם לפלא כלל כו', אזי לא יהי' השמחה בהראות העושר והכבוד ולא יהי' ברעם ורעש כלל כ\"א שמחת המלך תהי' בחשאי בעצמותו עם השרים וכו', וגם השרים לא יראו עשרם וכבודם מאחר שהוא כלא חשיב לגבי עושר המלך כו', אך בכפר בבית הכלה היו צריכים לכך בשביל כבוד המלך לבד וד\"ל.\n<b>ועתה</b> ע\"ד כ\"ז יובן ג\"כ למעלה שכנ\"י הם נשמות שהמה נולדים בבחי' אצי' הנק' מל' דאצי' והיא ברתא דמלכא עילאה שהוא ענין מארז\"ל בת היתה לאברהם<sup data-n=\"10020\">17</sup> אבינו ובכל שמה<sup data-n=\"10021\">18</sup> כו' כידוע, והחתן הוא בחי' חב\"ד דז\"א דאצי' שהיא",[["10014","11","<b>הת\"ח</b>: גיא: התחתון."],["10015","12","<b>הסתימה</b>: ג: הסתר. יא: הסתים."],["10016","13","<b>שעל החתן לעשות סעודה</b>: ראה גם לקמן רח, רע\"ג ובהנסמן שם."],["10017","14","<b>בבית</b>: גיא: בליל."],["10018","15","<b>לפני</b>: שם: לפי."],["10019","16","<b>מכ\"ש</b>: יא: מכלים שונים."],["10020","17","<b>בת היתה לאברהם אבינו</b>: ראה בבא בתרא טז, ב. רמב\"ן ח\"ש כד, א. אוה\"ת ח\"ש קכה, ב ואילך."],["10021","18","<b>אבינו ובכל שמה</b>: גיאיב: ובכל שמה. טו: ליתא."]]],[2300540150,"אורייתא מחכ' נפקת<sup data-n=\"10022\">19</sup> כו'. והנה בשעה שירד ה' על ה\"ס היינו עד\"מ יציאת החתן ממקומו שבאצי' בפנימי' האורות דז\"א כו' ולהיות מתגלה בדבר ה' דיבור העליון שהוא מחי' עולמות עד עולם העשי' השפל כו', וזהו ירידה גדולה ועצומה כמ\"ש וירד ה'<sup data-n=\"10023\">20</sup> כו' כידוע שהמל' היא הדבור<sup data-n=\"10024\">21</sup> הוא ראש לשועלים<sup data-n=\"10025\">22</sup> כו'<sup data-n=\"10026\">23</sup> הפועל במוגבלים שאין ערוך לנברא עם הבורא, וזהו כמשל הכפר לגבי עיר המלוכה כו' וד\"ל. אך ענין ירידה זו הי' לעשות סעודת החתן<sup data-n=\"10027\">23</sup> בבית הכלה העליונה דוקא כו', ולכך הי' הרעש הגדול בקולות וברקים כו' מפני שבכפר לא ראו מעולם נימוסי המלוכה הרעש גדול כו', וגם צריכים להראות כבוד המלך כנ\"ל וכמו\"כ האורות עליונים דז\"א דאצי' הנק' מלך<sup data-n=\"10028\">*24</sup> שהמה היו גנוזים באוצרותי\"ו הראם לכבוד הכלה בביתה שהוא דיבור העליון כו', ולפי שאין ערוך לבחי' אצי' עצמה עם הארת אצי' בבי\"ע לכך מאד נתפעלו<sup data-n=\"10029\">24</sup> מן הקולות ופרחה נשמתן<sup data-n=\"10030\">25</sup> על כל דבו\"ר ודיבו\"ר וד\"ל, ומטעם זה הי' הגילוי כ\"כ בהיות שצריך להראות כבוד עשרו כנ\"ל ולכך כל<sup data-n=\"10031\">*26</sup> אחד מהעומדים לפני המלך שבבחי' אצי' הרא[ה] כבוד עשר[ו] ג\"כ כו', וזהו כל הכתרי\"ם עליונים שנמשכו בשעת יו\"ד הדברות<sup data-n=\"10032\">26</sup> כו' וד\"ל. אמנם לאחר החופה כתיב ביום חתונת\"ו ושמחת לב\"ו דוקא, והוא שכבר קבלו התורה ונעשה יחוד זו\"ן דאצי' כו' אזי עשה החתן העליון סעודה לבני עיר\"ו בלא רעם ורעש כלל, כי הלא נגד בחי' פנימי' האורות דז\"א דאצי' כלא חשיבא כל האורות המתפשטי' בשריו ועבדיו כו' הנק' ז' הסריסים המשרתים את פני המלך<sup data-n=\"10033\">27</sup> כידוע וד\"ל, וע\"כ אינם צריכי' להראות כבוד עושר כו' וד\"ל, ואין השמחה אלא בבחי' [ה]עצמי' וזהו ביום שמחת לב\"ו וד\"ל.\n<b>והנה</b> כמו שבשבועות היו ב' מיני שמחות הנ\"ל בסעודת הכלה וסעודת החתן הנ\"ל, כמו\"כ בל\"ג בעומר בס\"ת<sup data-n=\"10034\">28</sup> שבתורה היו ב' מיני שמחות א' בבית הכלה והב' בבית החתן כו' וד\"ל. וביאור הדבר הנה רשב\"י היתה נשמתו מבחי' אצי'<sup data-n=\"10035\">29</sup> עצמו מבלי הסתר בכלים דבריאה, וכן תלמידי ר\"ע כולם היו בהם עיקר מקור התו' כידוע שהתורה נשתכחה וע\"י תלמידי ר\"ע הוחזרה<sup data-n=\"10036\">30</sup> לישראל, וע\"כ הם ב' בחי'<sup data-n=\"10037\">31</sup> החתן שהמה המשפיעי' תורה לכללות נש\"י כו'. אך הם המשפיעי' בחי' גליא שבתו' ורשב\"י הי'<sup data-n=\"10038\">32</sup> המשפיע הנסתר כי כל ימי חייו באמרו רזין דאורייתא הי' ממשיך בחי' הסתום דבאורות דאצי' ש[נ]גנזו בתורה הנגלית בזה העולם. ונמצא <span data-k=\"pg\">600</span> ּ שכל יחודים שהי' מייחד",[["10022","19","<b>אורייתא מחכ' נפקת</b>: נסמן לעיל פ' שמות יא, א."],["10023","20","<b>וירד ה'</b>: יתרו יט, כ."],["10024","21","<b>שהמל' היא הדבור</b>: נסמן לעיל פ' שמות לד, א."],["10025","22","<b>שהמל'. . ראש לשועלים</b>: נסמן לעיל פ' וארא נד, ב. *"],["10026","23","<b>כו'</b>: יבטו: כח."],["10027","23","<b>החתן</b>: גיא: החתונה."],["10028","*24","<b>דז\"א. . מלך</b>: ראה גם לעיל פ' וארא נד, ג הערה 74."],["10029","24","<b>נתפעלו</b>: שם: נתפלאו."],["10030","25","<b>ופרחה נשמתן</b>: נסמן לעיל פ' וארא סט, א."],["10031","*26","<b>כל</b>: טו: גם כל."],["10032","26","<b>הכתרי\"ם. . יו\"ד הדברות</b>: שבת פח, ב."],["10033","27","<b>ז' הסריסים המשרתים את פני המלך</b>: אסתר א, י. ראה ע\"ח (שער כסה\"כ) שמ\"ו, פ\"ו."],["10034","28","<b>בס\"ת</b>: ג: בכתר. יא: בסתים."],["10035","29","<b>רשב\"י היתה נשמתו מבחי' אצי'</b>: ראה גם מאמרי אדה\"ז תקס\"ב כאן (ע' תלא). לקמן פ' משפטים רפ, א. שער האמונה פה, ב ובהערה 8. שערי אורה (שער הפורים) עג, ב."],["10036","30","<b>תלמידי ר\"ע כולם. . נשתכחה. . הוחזרה</b>: ראה יבמות סב, ב וברש\"י שם."],["10037","31","<b>ב' בחי'</b>: יא: בבחי'."],["10038","32","<b>הי'</b>: יבטו: הוא הי'."]]],[2300540187,"הי' בבית הכלה דוקא בכל ימי חייו כנ\"ל וד\"ל, אמנם לאחר הסתלקותו עשה סעודה בביתו בבחי' אצי' עצמו והיינו הילולא דרשב\"י וד\"ל."],[2300540075,"33omer5562_2\n<b>והנה</b> לתוספת ביאור<sup data-n=\"10039\">1</sup> שרשי הדברים צ\"ל תחלה עיקר ענין הסעודה מה היא, כמו שני סעודות השבת בליל שבת נק' סעודתא דחקל תפוחין כו' וביום השבת<sup data-n=\"10040\">2</sup> נק' סעודתא דעתיקא וכמ\"ש וקראת לשבת ענג<sup data-n=\"10041\">3</sup> כו', והיינו ג\"כ ענין סעודת כלה וסעודת חתן כנ\"ל. וביאור הדבר הנה עיקר ענין הסעודה הוא ענין העונג מגמר[ה] של איזה דבר שמחה כמו ויאכלו לחם לפני האלקי'<sup data-n=\"10042\">4</sup> עם יתרו שהי[תה] סעודת שמחה על גמרו של דבר בענין יצ\"מ כו'. וכמו\"כ הסעודה שיעשה המלך בנצחו<sup data-n=\"10043\">5</sup> את שונאו במלחמה שיעשנה אחר גמר המלחמה דוקא וכמ\"ש במ\"א וד\"ל. ועד\"ז כל סעודה שיעשה האדם לשמחה הוא לאחר שיגמור איזה מלאכה או בנין בית וכדומה וד\"ל. וזהו ויכולו השמים והארץ<sup data-n=\"10044\">6</sup> כו' אז היא סעודתא דחקל תפוחין כו', פי' כי הנה כתי' אחר גמר כל ימי המעשה וירא אלקי' את כל אשר עשה והנה טוב מאד<sup data-n=\"10045\">7</sup> היינו מבחי'<sup data-n=\"10046\">8</sup> עונג העליון שהוא מאד בלי גבול<sup data-n=\"10047\">9</sup>.\n<b>והנה</b> י\"ל כי הלא ידוע ששרש דשרש צדיק ח\"י עלמין<sup data-n=\"10048\">10</sup> שהוא גמרה של השפע ביום הז' שהוא בחי' טוב מאד, היינו יסוד דע\"י<sup data-n=\"10049\">11</sup> דבקדמי\"ן ברא<sup data-n=\"10050\">13</sup> כו', וכמ\"ש צדיק כתמר יפרח כארז בלבנו\"ן<sup data-n=\"10051\">12</sup> כו', וא\"כ גם בכל יום מו' ימי המעשה<sup data-n=\"10052\">14</sup> היתה הארת העונג האלקי בחכ' עד סיום המדות שהוא הוי\"ו כו'. אך הענין יובן ע\"פ מ\"ש במ\"א שבגמרה של השפע שם יותר מתגברת העונג<sup data-n=\"10053\">15</sup> כמו בזיווג כו' וזהו הנק' ששון כו'. וכמו\"כ בכלות השפע דתההוות שמים וארץ וכל צבאם דבי\"ע מאור הזרוע לצדיק<sup data-n=\"10054\">16</sup> כו' היתה בגמר הזה תגבורת העונג שבשרש דשרש בחי' ע\"י והוא הנק' טוב מאד, וזהו שאחר גמר כל המעשה דוקא כתיב והנה טוב מאד וד\"ל. והנה לטעם זה תקרא מ\"ד<sup data-n=\"10055\">17</sup> מל' דאצי' המקבלת השפע אור מצדיק ח\"י עלמין בליל שבת בשם כלה<sup data-n=\"10056\">18</sup> ע\"ש כליון כמו כלתה נפשי<sup data-n=\"10057\">19</sup> פי' לפי שאז כליון וגמר השפע במשפיע. וכמו\"כ יש בחי' כליון וגמר במקבל",[["10039","1","<b>והנה לתוספת ביאור</b>: הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז משנת תקס\"ב. והנחת הר\"מ נדפסה במאמרי אדה\"ז תקס\"ב ח\"ב ע' תנג [ושם מתחיל: להבין מארז\"ל אלמלא היו שומרי' ישראל ב' שבתות כהלכתן, ובראשו נרשם: ”ליל שבת פ' נשא\"] וראה בהנסמן במ\"מ לשם. ובשינויים וכו' ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770405\" data-slug=\"or-hatorah-hb\" data-id=\"8316770405\">אוה\"ת שה\"ש ח\"ב ע' תה</a> [ובפתיחה: להבין ענין וביום שמחת לבו]. וראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["10040","2","<b>בליל שבת. . וביום השבת</b>: ראה זהר יתרו פח, ב. סידור אדה\"ז במקומו. המשך תער\"ב ח\"ב ע' א'צז. לקו\"ש בשלח (כרך לא) ע' 247. נדפס גם באג\"ק שלו חט\"ו ע' סז."],["10041","3","<b>וקראת לשבת ענג</b>: ישעי' נח, יג."],["10042","4","<b>ויאכלו לחם לפני האלקי'</b>: יתרו יח, יב [ושם: ויבא. . לאכל לחם עם חותן משה לפני האלקים]."],["10043","5","<b>הסעודה שיעשה המלך בנצחו</b>: ראה סידור שער נט\"י קא, סע\"ב [נדפס גם במאמרי אדה\"ז תקס\"ב ח\"א ס\"ע קז]."],["10044","6","<b>ויכולו השמים והארץ</b>: בראשית ב, א."],["10045","7","<b>וירא אלקי'. . טוב מאד</b>: בראשית א, לא."],["10046","8","<b>היינו מבחי'</b>: גיא: הוא בחי'."],["10047","9","<b>מאד בלי גבול</b>: נסמן לעיל פ' וארא סא, ב."],["10048","10","<b>צדיק ח\"י עלמין</b>: זהר בראשית כה, ב. שם השמטות (רע\"מ) רסו, ב. ועוד. ויקרא (רע\"מ) יז, א."],["10049","11","<b>טוב מאד היינו יסוד דע\"י</b>: ראה גם סידור ערבית לשבת קסט, ב."],["10050","13","<b>דבקדמי\"ן ברא</b>: ת\"א לבראשית א, א."],["10051","12","<b>יסוד דע\"י. . צדיק. . כארז בלבנו\"ן</b>: תהלים צב, יג. ראה גם לקמן פ' יתרו עדר, ב. שעה\"י קכח, א ובהערה 5."],["10052","14","<b>המעשה</b>: ג: בראשית."],["10053","15","<b>שבגמרה של השפע. . העונג</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' נה. מאמרי אדה\"א נ\"ך ע' מט."],["10054","16","<b>מאור הזרוע לצדיק</b>: ע\"פ תהלים צז, יא."],["10055","17","<b>מ\"ד</b>: יא: מדת."],["10056","18","<b>מל'. . כלה</b>: ראה פרדס (שער עה\"כ) שכ\"ג מערכת כל כלה. ע\"ח (שער שבה\"כ) ש\"ט, פ\"א."],["10057","19","<b>כלה. . כלתה נפשי</b>: תהלים פד, ג. ראה לקמן פ' תצוה שמח, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381133\" data-slug=\"likkutei-torah\" data-id=\"4001381133\">לקו\"ת שה\"ש א, א</a> מאמרי אדה\"ז תקע\"א ע' סב (ובהנסמן בריש המאמר שם). נביאים ע' קנה וע' קנו."]]],[2300540113,"השפע, פי' שבגמר קבלת השפע יותר תהי' תגבורת העונג, וזהו ויכולו לשון רבים ע\"ש שכלתה וגמרה ההשפעה במשפיע ומקבל הנק' שמים וארץ כו' שאז גילוי תגבורות העונג ביותר כו'. וזהו שנק' כלה מלשון כלתה נפשי כו' בגמר<sup data-n=\"10058\">*20</sup> קבלתה השפע תתענג על ה' עד שתכלה נפשה בבחי' או\"ח לתגבורת גילוי אור<sup data-n=\"10059\">20</sup> של המשפיע הנק' טוב מאד ולאותו הטוב מאד תכלה נפשה מרוב תגבורת הגילוי כו' וד\"ל. משא\"כ בשאר ימי המעשה [הנה] הגם שהי' העונג בהעלם בכל שפע אור, אבל מאחר שעדיין נשאר באמצע השפע אין העונג בתגבורת ובגילוי כ\"כ ולא תקרא בשם כלה כו'. וכידוע שהשפע הוא דבר בפ\"ע והעונג שבו הוא מובדל ומרומם ממנה כמו עד\"מ המשפיע שכל לתלמידו שעצם ההשפעה היא עבודה וטרח[א] ומה ש[י]תענג בהשפעתו אינו בשעת השפעתו כ\"א אחר השפע שיתענג ממה שקיבל התלמיד כו', אך עכ\"ז הי' גם בשעת השפע עונג רק שהי' בהעלם כו'. כן עד\"מ בכל ו' ימי המעשה, כמו אור החסד דאצי' ביום ראשון וכל פרטיו מאחר שאין בו <span data-k=\"pg\">ש</span> ּ שלימות בלתי שאר האורות דימים הבאים אין בו גילוי העונג עדיין כ\"א בהעלם לבד, ואפי' בחכ' שבכל יום ויום לא הי' בה העונג בגילוי [ו]בתגבורת דידוע דבראשית נמי מאמ\"ר הוא<sup data-n=\"10060\">21</sup> פי' גם החכמה שהיא המוחין למדות בחי' עבודה וטרחא היא להשפיע מוחין לאור חסד כו' וד\"ל, כי כל מאמ\"ר הוא בבחי' עשי' וירידת השפע כידוע. וא\"כ נמצא מכל הנ\"ל שזהו כמשל העושה סעודה אחרי שגמר מלאכתו בנין או כלי וכדומה שבהיות[ו] עדיין באמצע מלאכתו לא קבל עונג ממלאכה אך היתה בהעלם ע\"ש שעתיד להתענג בו כו', ובגמרו ונשלם כל הפעולה בכל פרטי' אזי יתעדן ויתענג בו ויתפאר בו לאוהביו וריעיו ויקראם לסעודה ושמחה כו'. וע\"ד מ\"ש<sup data-n=\"10061\">22</sup> יובן ענין סעודת הכלה דא היא סעודתא דחקל תפוחין כו', פי' חקל תפוחין הוא ענין עונג שימצא בשדה העליונה כו', והיינו ע\"ש שכלתה נפשה אל העונג הגלוי שבמשפיע וד\"ל.\n<b>והנה</b> בסעודת היום החתן בא אל הכלה לסעודה ונק' סעודתא דעתיקא כו', כמ\"ש וקראת לשבת עונג שהוא שהתענוג<sup data-n=\"10062\">23</sup> העליון הוא נק' לסעודה אל הכלה כו'. והנה עיקר שם הסעודה נק' ע\"ש מי שעשאוהו בשבילו דהיינו למי שמזמנים וקוראי' אותו אל הסעודה ולא ע\"ש העושה סעודה כו'. ובזמן שהי' בהמ\"ק קיים",[["10058","*20","<b>בגמר</b>: יביג: כי בגמר."],["10059","20","<b>אור</b>: יא: עונג."],["10060","21","<b>דבראשית נמי מאמ\"ר הוא</b>: ראש השנה לב, א."],["10061","22","<b>וע\"ד מ\"ש</b>: גיא: ועד\"מ זה."],["10062","23","<b>שהתענוג</b>: שם: שהעונג."]]],[2300540151,"הי' המנהג בכל ישראל שהי' החתן עושה סעודת החתונה<sup data-n=\"10063\">24</sup> ועיקר הסעודה הי' בשביל הכלה ונקראת ע\"ש<sup data-n=\"10064\">25</sup> וכן המנהג עכשיו בא\"י, אבל בזמן הגלות נהפוך הוא המנהג שהכלה עושה הסעודה בשביל החתן והסעודה נקראת על שמו כו'. וטעם הדבר כי בזמן בהמ\"ק הי' יחוד פב\"פ והי' עליית [ה]מל' בבחי' אצי' בכל פרצופ[ה], וזהו ביום<sup data-n=\"10065\">26</sup> השמיני שלח המלך<sup data-n=\"10066\">27</sup> את העם ויברכו את המלך כו', וזה הי' בשמע\"צ<sup data-n=\"10067\">28</sup> שאז היא החופה שעיקר סעודת הח[ו]פה הוא בבית החתן דוקא, אבל בזמן הגלות שהכלה בבחי' הסתר והעלם בבי\"ע לא יש בכחה להיות נקראת לסעודה בבית החתן אלא ה[י]א קורא[ה] את החתן אליה בביתה וכמ\"ש באתי לגני אחותי כלה<sup data-n=\"10068\">29</sup> כנ\"י והסעודה נק' ע\"ש החתן. ועד\"ז הי' בשבועות שהי' רק אירוסין<sup data-n=\"10069\">30</sup> עדיין ולא חופה כי עיקר הפי' של חתונת\"ו הוא אירוסין לבד כמו ויתחתן<sup data-n=\"10070\">31</sup> כו', והיינו יו\"ד הדברות שהי' בבחי' טבע\"ת קדושין<sup data-n=\"10071\">32</sup> כמאמר אשר קדשנ\"ו במצותיו<sup data-n=\"10072\">33</sup> כו' היו\"ד<sup data-n=\"10073\">*34</sup> ה[י]א חכ'<sup data-n=\"10074\">34</sup> שעגולה כטבע\"ת<sup data-n=\"10075\">35</sup> כו' ולכך היתה הסעודה בבית הכלה בקולות וברקים כנ\"ל והיתה בשביל החתן ונקראת ע\"ש כו'. וכמו\"כ כתיב ויאסוף לבן את כל אנשי המקום ויעש משתה<sup data-n=\"10076\">36</sup> כו', פי' כי מן הראוי הי' שיעקב יעשה הסעודה שהוא החתן וסעודת חופה בבית החתן דוקא כו', אך לבן הי' רמאי ורצה להחליף את לאה ברחל ולכך עשה הוא את הסעודה שהיא סעודת הכלה כו'. ויובן הדבר למעלה באצי' שבחי' לב\"ן העליון אבי הכלה החליף סעודת החתן דיעקב בעל עולם האצי' לסעודת כלה כדי שתהי' לא\"ה נכנסת תחת רחל וזהו שאסף אנשי המקום המקו\"ם הידוע וד\"ל. ולע\"ל שתתעלה מדת המל' ותהי' עטרת בעלה<sup data-n=\"10077\">37</sup> יהי' כמו בזמן בהמ\"ק שהי' הסעודה בבית <span data-k=\"pg\">602</span> ּ החתן כנ\"ל. וכמו\"כ כתיב במשתה אחשורוש לאסתר שאמרה אליו למחר אעשה כדבר המלך<sup data-n=\"10078\">38</sup>, פי' למחר לע\"ל כשתהי' בעילוי בבחי' אצי' פב\"פ גם כשתעשה היא [ה]סעודה ותקרא להחת\"ן אליה יהי' שוה כדבר המלך עכשיו שהוא קרא אות\"ה<sup data-n=\"10079\">39</sup> אל משת\"ה היי\"ן כו' וד\"ל.\n<b>והנה</b> ע\"ד כל הנ\"ל יובן בב' סעודות שבת שבליל שבת הוא עליות מל' באצי' הסעודה שלאחר גמר השפע באצי'",[["10063","24","<b>שהי' החתן עושה סעודת החתונה</b>: באוה\"ת כאן (ע' תה) מציין: כמ\"ש בש\"ע אה\"ע סי' ס\"ד. וראה גם בענין זה לעיל רז, ג. מאמרי אדה\"ז תקס\"ב ח\"ב ס\"ע תל. אוה\"ת כאן (ע' תו וע' תז). מאמרי אדה\"א דרושי חתונה ח\"א ע' קמו ואילך. וע' קסה."],["10064","25","<b>ע\"ש</b>: יא: על שמה."],["10065","26","<b>ביום</b>: איג: שביום."],["10066","27","<b>ביום השמיני שלח המלך</b>: מלכים-א ח, סו [בהוספת תיבת ”המלך\"]."],["10067","28","<b>ביום השמיני. . בשמע\"צ</b>: ראה מועד-קטן ט, א. מפרשים עה\"פ."],["10068","29","<b>באתי לגני אחותי כלה</b>: שה\"ש ה, א."],["10069","30","<b>בשבועות שהי' רק אירוסין</b>: נסמן לעיל קפ, ב. וראה להלן הערה 32."],["10070","31","<b>ויתחתן</b>: מלכים-א ג, א. דהי\"ב יח, א."],["10071","32","<b>יו\"ד הדברות. . טבע\"ת קדושין</b>: באוה\"ת כאן (ע' תו) מציין לפסיקתא רבתי פסקא ויהי ביום כלת משה."],["10072","33","<b>אשר קדשנ\"ו במצותיו</b>: נוסח ברכת המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לא."],["10073","*34","<b>היו\"ד</b>: יביג: כי ביו\"ד."],["10074","34","<b>היו\"ד ה[י]א חכ'</b>: ראה זהר בראשית לא, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשסד ובהנסמן במ\"מ לשם."],["10075","35","<b>חכ'. . כטבע\"ת</b>: ראה פרדס (שער עה\"כ) שכ\"ג מערכת טבעת."],["10076","36","<b>ויאסוף לבן. . משתה</b>: ויצא כט, כב."],["10077","37","<b>המל'. . עטרת בעלה</b>: משלי יב, ד. ראה גם ש\"א כ, ב ובהערה 33."],["10078","38","<b>למחר אעשה כדבר המלך</b>: אסתר ה, ח [ושם: ומחר — ראה גם מאמרי אדה\"א נ\"ך ע' תקיד. וש\"נ]."],["10079","39","<b>כשתעשה היא [ה]סעודה. . שהוא קרא אות\"ה</b>: ראה מאמרי אדה\"ז תקס\"ב כאן (ע' תנד). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770407\" data-slug=\"or-hatorah-hb\" data-id=\"8316770407\">אוה\"ת שה\"ש כאן (ע' תז</a>)."]]],[2300540188,"עצמו כו', וביום השבת<sup data-n=\"10080\">40</sup> הוא השפלת עונג דדכורא בנוק' וה[י]א העושה סעודה בשבילו והסעודה נקראת על שמו סעודתא דעתיקא כו'. וזהו מארז\"ל אלו שמרו בנ\"י שתי שבתות<sup data-n=\"10081\">41</sup> הנ\"ל כהלכתן דוקא דהיינו הא'<sup data-n=\"10082\">*42</sup> מלמטה למעלה והב' ביומא שהוא מלמעלה למטה כו' מיד היו נגאלין כו', והטעם ששבת דיומא גבוה במדרגה מן שבת דמעלי שבתא כו' [לפי המובן ממשל גמר הפעולה של הכלי שיהי' אז תגבורת העונג כו']. אמנם יש עוד הפרש בין עונג זה שגמר מלאכתו ומתפאר בו למריעיו<sup data-n=\"10083\">42</sup> כו' לעיקר העונג שמקבל אח\"כ בדירתו בביתו הנאה או בכלי כסף המהודר כששותה בו לאחר ימים כו', ועיקר ההפרש שזה העונג שמקבל אחר זמן הוא מבחי' עצמיות העונג הכללי שביחידה שבנפשו הוא מתפשט באותו העונג פרטי של גמר ושלימות הפעולה שנמצא נשלם עונג פרטי זה בכללות עצמות העונג כו' שאם הי' נאבד הכלי ולא הי' משתעשע בו אין שלימות כלל בעונג שקיבל בגמר מלאכתו כו', וא\"כ חוזר הדבר למקורו בשעה שמשתעשע בו והיינו עונג הנשפע בעת הגמר בא לעצמות העונג כו' וד\"ל. ובזה יובן הפסוק וקראת לשבת ענג פי' שעצמות העונג יהי' נמשך אל התענוג<sup data-n=\"10084\">43</sup> שבליל שבת הנ\"ל ובזה ישלימנו וד\"ל וכמ\"ש במ\"א.",[["10080","40","<b>השבת</b>: גיא: ליתא."],["10081","41","<b>אלו שמרו בנ\"י שתי שבתות</b>: ראה שבת קיח, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. מאמרי אדה\"א שמות ח\"א ס\"ע קפט ואילך. וש\"נ. הנחות תקע\"ז ע' קכג. וש\"נ. לקמן ריט, א. פ' יתרו רסו, א. תצוה שכב, ג. ויקהל תלו, ג."],["10082","*42","<b>הא'</b>: יביג: הא' בלילה."],["10083","42","<b>ומתפאר. . למריעיו</b>: איג: ומתהדר. . לריעיו."],["10084","43","<b>התענוג</b>: שם: העונג."]]],[2300540076,"<b>בעז\"ה פ' פרה מאדמו\"ר ר' דובער נבג\"ם תקע\"ה.</b>\n<b>להבין</b> כללות ענין מצות פרה אדומה<sup data-n=\"10085\">1</sup>, הנה תחלה צריך להבין כלל הכלול בכל מצוה שהוא רק כדי להמשיך אור חדש באצי'<sup data-n=\"10086\">2</sup> כידוע, והנה יש להבין ענין ג\"ע העליון שהרי הוא נברא מאין ליש מכבר מששת ימי בראשית כמ\"ש ויטע ה' גן בעדן<sup data-n=\"10087\">3</sup> מקדם כו', והלא עיקר ענין העד\"ן והעונג מבחי' זיו השכינה בגן הזה נעשה ע\"י מעש\"ט<sup data-n=\"10088\">4</sup> בעוה\"ז כי שכר מצוה מצוה<sup data-n=\"10089\">5</sup>, ומי שלא עשה טוב בימיו הרי חסר חלק העדן והזיו שמחמת מע\"ט שהי' עושה כו', וא\"כ קודם ש[נ]ברא האדם אין מקום להשראת העד\"ן",[["10085","1","<b>להבין כללות ענין מצות פרה אדומה</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז מש\"פ פרה תקס\"ב. ונדפסה בתוס' הגהות וכו' באוה\"ת חוקת ע' תשפג. והנחת הר\"מ בן כ\"ק אדה\"ז נדפסה במאמרי אדה\"ז תקס\"ב ח\"ב ע' שסח. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["10086","2","<b>כלל הכלול בכל מצוה. . אור חדש באצי'</b>: נסמן לעיל קנו, ב."],["10087","3","<b>ויטע ה' גן בעדן</b>: בראשית ב, ח [ושם: ה\"א — וכ\"ה בסמוך בפנים]."],["10088","4","<b>העדן. . נעשה ע\"י מעש\"ט</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' שצח. וש\"נ. ח\"ד ע' א'רפד. שמות ח\"ב ס\"ע שטו ואילך. וראה גם לקמן פ' פקודי תנ, א על יד הערה 79."],["10089","5","<b>שכר מצוה מצוה</b>: נסמן לעיל פ' שמות ז, ב."]]],[2300540114,"והעונג בזמן<sup data-n=\"10090\">6</sup> הזה ולמה יקרא גן עדן כו'. אך הענין הוא דבודאי נמשך עד\"ן עילאה בגן הזה בבחי' אצי' מוימ\"ב במדה וקצבה כדרך כל בריאה מאין ליש והוא ענין זי\"ו השכינ\"ה שבתמידות שופע בגן הזה כידוע, והוא עד\"מ הידוע כמו שאין עשב למטה שאין לו מזל מלמעלה המכה בו ואומר לו גדל<sup data-n=\"10091\">7</sup> כו'. כמו\"כ ענין שפע העונג האלקי הנק' עד\"ן עילאה בג\"ן הזה שהג\"ן הוא כדוגמת העשב לגבי המזל המגדלו ומצמיחו מאין ליש, וכמו העונג הנרגש בהאדם מדבר החכמה שמתענג בה, שלא יתענג עד שמבין בהשגה דוקא כמ\"ש במ\"א שהוא תענוג הנרגש בבינה<sup data-n=\"10092\">8</sup> דוקא אבל בחכ' הוא בבחי' אי\"ן בלא הרגשה כלל כו'. כמו\"כ בחי' גן שבעד\"ן הוא העונג הנשכל<sup data-n=\"10093\">9</sup> בבינה שבמל' דאצי' שהוא הרקיע שעל ראשי החיות<sup data-n=\"10094\">10</sup> כו', והעד\"ן הוא התענו\"ג העליון <span data-k=\"pg\">שא</span> ּ שבחכ' דאצי' הוא מקורו האמיתי שאינו בבחי' הרגשה כו' שזהו כמ[של] העשב לגבי המזל רוחני המצמיחו וד\"ל. אך ענין שפע העד\"ן בגן הזה הוא במדה וקצבה מו' ימים<sup data-n=\"10095\">11</sup> דאצי', פי' כמ\"ש ויטע ה' אלקי' גן בעדן שהושפל והורגש העונג אלקי כמשל נטיעת גן גשמי ע\"פ אופן העונג רוחני שבמוח[י'] כו', כן נמדד ע\"פ עד\"ן עילאה אופן ואיכות הגן שהוא השפלות העונג כו', וע\"כ גם קודם שנברא אדה\"ר הי' ג\"ע העליון כבר נברא מאין ליש בבחי' בינה שבמל' דאצי' בעולם הבריאה<sup data-n=\"10096\">12</sup> כו' כמ\"ש ונה\"ר שהוא בינה<sup data-n=\"10097\">13</sup> עילאה דאצי' יוצא מעד\"ן להשקות את הגן<sup data-n=\"10098\">14</sup> שהוא העונג הנרגש כו' וד\"ל.\n<b>אך</b> משם יפרד והי' לארבע ראשים<sup data-n=\"10099\">15</sup> כו', פי' שאת זלעו\"ז עשה האלקי'<sup data-n=\"10100\">16</sup>, ומבחי' עונג זה שבנהר כו' יומשך ג\"כ שפע עונג להיכלות הנפרדי' מעה\"ד טו\"ר שהן הפרות הרעות והן הד' ראשים ד' גליות<sup data-n=\"10101\">17</sup> כמ\"ש במדרש על ענין פ' אדומה שהוא ענין הד' מלכיות<sup data-n=\"10102\">18</sup> כו', וידוע שהטוב שבנוג\"ה הוא ענין העונג הגשמי שהוא שרש כל התאוות רעות שהוא נמשך ג\"כ מנה\"ר המשקה הגן כו' רק שיכול להתהפך לטוב כי חצי[ו] טוב וחצי[ו] רע<sup data-n=\"10103\">19</sup>, והוא בחי' הלהט החרב המתהפכת<sup data-n=\"10104\">20</sup> שלפני הגן הזה. וזהו שציוה השי\"ת ליקח פרה אדומה תמימה<sup data-n=\"10105\">21</sup> כו', פי' כדי לברר בירור הרע שבנוגה צריך תחלה להפוך הטוב שבנוגה [ל]קדושה והיינו ע\"י שחיטת פ\"א<sup data-n=\"10106\">22</sup> מלאה גבורות קדושות שאין בה עדיין אחיזה לטוב שבנוגה, וזהו אשר אין בה מו\"ם<sup data-n=\"10107\">23</sup> כו'<sup data-n=\"10108\">24</sup>. ומזין דמה נוכח פני[מי'] אהל מועד<sup data-n=\"10109\">25</sup> והיינו שמוציאים חיות אלקות שבדמה שהוא עדיין",[["10090","6","<b>בזמן</b>: אד: בגן."],["10091","7","<b>שאין עשב למטה. . גדל</b>: נסמן לעיל פ' וארא ס, ב."],["10092","8","<b>תענוג הנרגש בבינה</b>: ראה סידור שער בהמ\"ז קד, ד. שער התקיעות רמב, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380947\" data-slug=\"likkutei-torah\" data-id=\"4001380947\">לקו\"ת ר\"ה נז, א</a>. הנסמן לעיל לג, ד הערה 332."],["10093","9","<b>הנשכל</b>: באוה\"ת חוקת כאן (ע' תשפד): כשנשפל."],["10094","10","<b>הרקיע שעל ראשי החיות</b>: ראה גם לעיל לג, ג ובהנסמן שם."],["10095","11","<b>ימים</b>: א: ימי. ד: ימי [בראשית]."],["10096","12","<b>ג\"ע. . בעולם הבריאה</b>: ראה גם לעיל פ' שמות מ, ד. וש\"נ."],["10097","13","<b>ונה\"ר שהוא בינה</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, א."],["10098","14","<b>ונה\"ר. . יוצא מעדן להשקות את הגן</b>: בראשית ב, י."],["10099","15","<b>משם יפרד והי' לארבע </b>[אד: והי' לד']<b> ראשים</b>: המשך הכתוב ונהר יוצא."],["10100","16","<b>שאת זלעו\"ז עשה האלקי'</b>: נסמן לעיל לד, ג."],["10101","17","<b>הד' ראשים ד' גליות</b>: ב\"ר פט\"ז, ד."],["10102","18","<b>פ' אדומה. . הד' מלכיות</b>: ראה יל\"ש עה\"פ. אוה\"ת חוקת (כרך ו) ע' א'תתסט. וש\"נ."],["10103","19","<b>שבנוגה. . חצי[ו] טוב וחצי[ו] רע</b>: ראה ע\"ח (שער ק\"נ) שמ\"ט, פ\"ו."],["10104","20","<b>הלהט החרב המתהפכת</b>: ראה בראשית ג, כד. זהר ויחי רכא, ב. ע\"ח שם, פ\"ג. לקמן רנ, א. פ' ויקהל תט, ג. שע\"ת ג, ב ובהערה 17."],["10105","21","<b>פרה אדומה תמימה</b>: חוקת יט, ב."],["10106","22","<b>פ\"א</b>: פרה אדומה."],["10107","23","<b>אשר אין בה מו\"ם</b>: המשך הכתוב פרה אדומה תמימה."],["10108","24","<b>כו'</b>: באוה\"ת כאן (ע' תשפח) באה הגהה: (זהו ט\"ס כי לפי הדרוש דכאן הפרה היא ק\"נ וכן פי' הרמ\"ז פ' חוקת וכמ\"ש בע\"ח אלא ר\"ל דמה הוא פנימיותה היינו הטוב דק\"נ עכ\"ה)."],["10109","25","<b>ומזין דמה נוכח פני[מי'] אהל מועד</b>: חוקת שם, ד."]]],[2300540152,"כול[ו] טוב כו' ומדביקים אותה בשרש[ה ו]מקורה האמיתי העונג האלקי שבפני[מי'] אהל מועד שהוא עד\"ן עילא\"ה בחי' היכל ק\"ק כו'. ובחי' אפ\"ר הפרה, היינו לאחר שמוציאין פנימיות\"ה ומעלים אותה בשרשה בעדן כו' שורפים בשרה ועורה<sup data-n=\"10110\">26</sup>, ומשימים בתוך השריפה עץ ארז ואזוב כו' הן דברים הרומזים על עה\"ח שבתוך הגן שהוא בחי' צומח לבד כו' והן עדיין למעלה [מ]בחי' עה\"ד טו\"ר כו', והיינו מבחי' אורות [דאצי'] קודם שבאו לכלים מכלים שונים כו', כך בשריפת העץ ארז נמתקו גבורות קשות דפ\"א זו להבדיל ממנה יניקת הטוב שבנוגה כו'. וזהו והשליך אל תוך שריפת הפרה<sup data-n=\"10111\">27</sup> דוקא, בהיות כי בשרה הוא חיצוני' החיות ולהיות מליאה גבורות יכול להיות המשכת השפע לחיצוני' כנ\"ל בענין העונג הגשמי שנשפע ג\"כ מנהר היוצא מהעדן ומשם יפרד להיות ראש וחיות לנפרדי' שהן ז' מדות הרעות כו', אבל בתערובות ושריפת ושלהבת העץ ארז ואזוב כו' שהן מעה\"ח כו' לא יתערב זר בשריפת הפרה ונק' אז רשפי' רשפי אש שלהבת י\"ה<sup data-n=\"10112\">28</sup> וד\"ל.\n<b>והנה</b> בזאת [ה]עבודה נמתק[ו'] גבורות קשות מבלי ימצא יניקה לטוב שבנוגה אמנם כדי לברר בירורי הרע שבנוגה ולהעלותה לה' לזאת צוה ה' שיתנו מים חיים <span data-k=\"pg\">604</span> ּ באפר הפרה, ומתחלה יוציאו האפר מחוץ למחנה<sup data-n=\"10113\">29</sup> דוקא [ו]ע\"י איש טהור כו'. והיינו להיות כי הרי האפר יש בו חמימות קצת מן השריפה אבל הוא מעט מזעיר כי העיקר כבר חלף והלך לו ע\"י השריפה ולא נשאר מבשרו רק חלק הדומם שבחי והוא האפר כו', כן עד\"מ כבר נמתקו עיקר הגבורות. ואך מה שנשאר עדיין מבחי' הגבורות הקשות באפר הפרה אדומה כו' יוציא איש טהור מחוץ למחנה היינו ליתן שפע להיכלות הנפרדי' מהנהר הראשון כו' כנ\"ל, ויניקתם מעט מזעיר בהיות כי האפר כבר ניטל ממנו חלק חי וצומח ומדבר, וע\"כ יש בכח אפר הזה כשיתנו בו מים חיים והוא חכ' המברר ומבדיל בין טוב לרע כידוע שיטהר את הטמא ממש והוא בירור הרע שבנוגה [כו'], כי אם לא הי' בשרו נשרף תחלה כו' לא הי' עדיין כח למים חיים לברר כו', אבל האפר יוקדש ע\"י מים חיים כו', ועכ\"פ כל הנוגע בה יטמא<sup data-n=\"10114\">30</sup> כו' והמזה מי הנדה יכבס בגדיו<sup data-n=\"10115\">31</sup> כו' והניזה ממנו נטהר, וע\"ז א' שלמה [אמרתי] אחכמה והיא רחוקה<sup data-n=\"10116\">32</sup> פי' שיש ב' מיני העלאות מ\"ן מבירורי נוגה א' ע\"י קירוב והוא העלאת טוב שבנוגה כנ\"ל, והב'",[["10110","26","<b>ועורה</b>: ראה הגהת הצ\"צ באוה\"ת חוקת כאן (ע' תשפח)."],["10111","27","<b>והשליך אל תוך שריפת הפרה</b>: חוקת שם, ו."],["10112","28","<b>רשפי' רשפי אש שלהבת י\"ה</b>: שה\"ש ח, ו."],["10113","29","<b>למחנה</b>: באוה\"ת חוקת כאן (ע' תשפט): (הג\"ה אין כ\"ז מדוקדק. . )."],["10114","30","<b>הנוגע בה יטמא</b>: חוקת יט, כא."],["10115","31","<b>והמזה מי הנדה יכבס בגדיו</b>: חוקת שם."],["10116","32","[אמרתי]<b> אחכמה והיא רחוקה</b>: קהלת ז, כג."]]],[2300540189,"ענין אפר הפרה מחוץ למחנה דוקא הוא לאחר שנפרד מעה\"ד טו\"ר יתברר ע\"י החכ' הנק' מים חיים<sup data-n=\"10117\">33</sup>, הרי הובא הבירור ממקום רחוק מאד כו', וצ\"ל המברר ג\"כ ממקום הגבוה מאד נעלה בחכמה כו', וזהו אמרתי אחכמה [ו]הוא א' מאאלפך חכ'<sup data-n=\"10118\">34</sup> [ש]היא רחוקה מהחכ' הגלוי' כידוע, ע\"כ המזה טמא והניזה ממנו טהור שלא יהי' דבר כזה ע\"פ השגה נגלית כו' וד\"ל.\n<b>ועד\"ז</b> בכל מצות מעשיות שהוא ענין בירורי נוגה הרי שכר מצוה מצוה, פי' שניתוסף אור חדש באצי' ע\"י מעשה מצוה, והיינו בהיות שהזיו והעדן הוא במדה וקצבה ומחמת בירורי נוגה מד' נהרות הנפרדי' כו' כשמתהפכי' לטוב מהעונג שבמדות רעות כשמתהפך כו' מזה יהי' גרם [ל]תוספת שפע חדשה מהמאציל העצמי שבעדן לגן הזה. וזהו שהניח בג\"ע את האדם לעבדה<sup data-n=\"10119\">35</sup> כו', פי' שיזרע הגן ויוסיף ב[ו] צמיחת דשאים ואילנות והיינו שע\"י מע\"ט [י]תוס[ף] אור ושפע המאציל להיות נשפל בגן הזה כו', וביום שכולו ארוך<sup data-n=\"10120\">36</sup> יתגלה כל תוספת השפע שע\"י כל המעשים טובים ועתה הוא באצי' לבד כו' וד\"ל. וזהו שיכול האדם ליטול חלק חבירו בג\"ע<sup data-n=\"10121\">37</sup>, פי' כי יש בכל נשמ[ה] אלקי' כח לברר בנוגה ולגרום תוס' השפע בג\"ע העליון וכשאותו האדם שלא עשה טוב ולא בירר הפסיד ומונע אור כו' והרי חבירו שבמדריגתו לוקח חלקו כי הוברר גם חלק חבירו כי הם בשרשן מדה אחת וד\"ל. וזהו שלא על מנת לקבל פרס<sup data-n=\"10122\">38</sup> הוא ענין תוספת אור חדש שיאיר ע\"י המצוה שלא יחפוץ [בה] כו' וד\"ל והמשכיל יבין<sup data-n=\"10123\">39</sup>.",[["10117","33","<b>החכ' הנק' מים חיים</b>: ראה גם לקו\"ת חוקת נז, א."],["10118","34","<b>מאאלפך חכ'</b>: ראה הנסמן לעיל פ' שמות טו, ב."],["10119","35","<b>שהניח בג\"ע את האדם לעבדה</b>: בראשית ב, טו."],["10120","36","<b>וביום שכולו ארוך</b>: ראה קידושין לט, ב. סידור ערב שבת קסג, א. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתקי־ דברים ח\"ג ע' תתלא. לקמן פ' משפטים רצב, ד."],["10121","37","<b>ליטול חלק חבירו בג\"ע</b>: ראה חגיגה טו, א."],["10122","38","<b>שלא על מנת לקבל פרס</b>: אבות פ\"א, מ\"ג."],["10123","39","<b>והמשכיל יבין</b>: א: סליק והמ\"י. בגדהזח: ליתא. ו: חסר. ט: ארבע תיבות האחרונות ליתא."]]],[2300540077,"<b>בס\"ד פ' בשלח, התקפ\"ה</b>\n<span data-k=\"pg\">שב</span> ּ<b>ויאמר</b> ה' אל משה הנני ממטיר<sup data-n=\"10124\">1</sup> לכם לחם<sup data-n=\"10125\">2</sup> מן השמים כו', והי' ביום הששי והכינו את אשר יביאו<sup data-n=\"10126\">3</sup> כו' עד ויהי ביום הששי לקטו לחם משנה<sup data-n=\"10127\">4</sup> כו' ויאמר אליהם הוא אשר דיבר ה' שבתון שבת קדש לה'<sup data-n=\"10128\">5</sup> [כו'] ויאמר משה אכלוהו היום כי שבת",[["10124","1","<b>ויאמר ה' אל משה הנני ממטיר</b>: המאמר כנראה מיוסד על ד\"ה למה נסמכה פ' המן עם מצות השבת נדפס במאמרי אדה\"ז על פרשיות התורה ח\"א ע' רצו. ונו\"א נדפס שם ע' רצה ובפתיחה להבין למה נסמכה השבת לפ' המן. ובשינויים באוה\"ת בשלח ע' תרלח ואילך. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["10125","2","<b>ויאמר. . הנני ממטיר לכם לחם</b>: בשלח טז, ד."],["10126","3","<b>והיה ביום הששי. . יביאו</b>: בשלח שם, ה."],["10127","4","<b>ויהי. . לחם משנה</b>: שם שם, כב."],["10128","5","<b>ויאמר אליהם. . קדש לה'</b>: שם טז, כג."]]],[2300540115,"היום לה' [היום] לא תמצאוהו בשדה<sup data-n=\"10129\">6</sup> ששת ימים תלקטוהו<sup data-n=\"10130\">7</sup> וביום הז' שבת לא יהי' בו כו' עד ראו כי ה' נתן לכם השבת<sup data-n=\"10131\">8</sup> ע\"כ הוא נותן לכם ביום הוי\"ו לחם יומים כו'. הנה מכ\"ז משמע שלא הגיד להם משה פ' שבת משנצטווה לומר להם עד שא' ו[י]הי ביום הששי כו', שאז ששאלו לו מה זאת א\"ל הוא אשר דיבר ה' שנצטוויתי לומר לכם (כפרש\"י). הרי פ' המן עם פ'<sup data-n=\"10132\">9</sup> מצות השבת בזמן א' ובבת א' נאמרו מאחר שלא הזכיר להם משה מצות השבת עד שא' להם פ' המן, וא\"כ מוכרח לומר דשרש א' הוא למצות שבת עם מצות המן. ולכאורה משמע ממה שלא ירד המן ביום השבת כמאמר היום לא תמצאוהו בשדה כו', וביום הז' שבת לא יהי' בו, א\"כ הרי המן היפך ענין מצות השבת שמפני זה לא ירד בשבת. אך הנה<sup data-n=\"10133\">10</sup> הענין הוא דאדרבה ממה שלא ירד המן ביום השבת זה הי' הוראה גמורה ששרש המן עם השבת א[חד] הוא ממש ע\"כ לא ירד שפע המן בשבת (כמשי\"ת), והוא לפי שעיקר ומקור של השפע דמן בכל הוי\"ו ימי' דחול, הוא ביום השבת שנמשך על כל הוי\"ו ימים דחול כמו שהשבת הוא שרש [ו]מקור השפע לכל הוי\"ו ימים<sup data-n=\"10134\">11</sup> דחול כו'. וכמו שבשבת א[מר] כי בו שבת וינפש<sup data-n=\"10135\">12</sup> שנק' נייחא דרוחא<sup data-n=\"10136\">13</sup> במניעת ירידת השפע למטה, כך גם המן לא ירד בשבת. ואמנם בחי' מנוחה זו ה[י]א סיבת ירידת ההמשכה הכללי' לכל הו' ימים דחול דוקא כמ\"ש ויברך אלקי' את יום הז'<sup data-n=\"10137\">14</sup> כו' דעיקר ומקור הברכה בשבת הוא.\n<b>וביאור</b> הענין הנה תחלה יש להקדים במה דשרש ענין השבת והמן א' הוא, היינו במה ששניהם הם בבחי' ומדרגה שלמעלה מן הזמן ומקום שזהו למעלה מבחי' השתלשלו' העולמות מאין ליש כידוע, דהנה בשבת א[מר] אז תתענג על הוי'<sup data-n=\"10138\">15</sup> למעלה משם הוי' כו', וידוע דד' אותיות דשם הוי'<sup data-n=\"10139\">16</sup> יו\"ד בחכ' וה\"א בבינה וי\"ו מדות ה\"א דיבור והן כללות ע\"ס דאצי' (וקוצו של יו\"ד הוא בחי' הכתר<sup data-n=\"10140\">17</sup> ) ולמעלה משם הוי' דע\"ס כו'. והענין הוא כידוע בשרש ענין השבת כי בו שבת מכל מלאכתו<sup data-n=\"10141\">18</sup> כו', שהוא השביתה והמנוחה מן כל<sup data-n=\"10142\">19</sup> ההשתל' הנמשך מן הע\"ס בכלל ובפרט שנק' נייחא דרוחא, שגם בחי' הרצון והחכ'<sup data-n=\"10143\">20</sup> שובת ונח ועולי' למעלה במהו\"ע דא\"ס ב\"ה כמ\"ש כי בו שבת וינפש",[["10129","6","<b>ויאמר משה אכלוהו היום. . בשדה</b>: שם שם, כה."],["10130","7","<b>ששת ימים תלקטוהו</b>: בשלח טז, כו."],["10131","8","<b>ראו כי ה' נתן לכם השבת</b>: בשלח שם, כט."],["10132","9","<b>פ'</b>: בה: ליתא."],["10133","10","<b>הנה</b>: שם: ליתא."],["10134","11","<b>שהשבת. . השפע לכל הוי\"ו ימים</b>: זהר בשלח סג, ב. יתרו פח, א. ראה מאמרי אדה\"ז על מארז\"ל ע' רסא ואילך."],["10135","12","<b>כי בו שבת וינפש</b>: חיבור ב' כתובים בראשית ב, ג. תשא לא, יז [ראה לקמן ריז, ד. ריט, א. רכ, ג. רמב, ב. פ' יתרו רסו, א. ויקהל שצא, ב. ד. מאמרי אדה\"א ויקרא ח\"ב ע' תשסה. וש\"נ. ש\"א עט, א ובהערה 16. ולהעיר מרמב\"ן בהר כה, ב. בחיי נח ז, כב]."],["10136","13","<b>נייחא דרוחא</b>: ראה גם שער האמונה כט, א ובהערה 1."],["10137","14","<b>ויברך אלקי' את יום הז'</b>: בראשית ב, ג. ראה שע\"ת סו, א."],["10138","15","<b>אז תתענג על הוי'</b>: ראה גם לעיל פ' וארא נ, ב. וש\"נ."],["10139","16","<b>דד' אותיות דשם הוי'</b>: נסמן לעיל פ' שמות יב, ד."],["10140","17","<b>וקוצו של יו\"ד. . הכתר</b>: נסמן לעיל פ' בא קכב, א."],["10141","18","<b>כי בו שבת מכל מלאכתו</b>: בראשית ב, ג."],["10142","19","<b>מן כל</b>: ב: מכל. ה: מן."],["10143","20","<b>הרצון והחכ'</b>: ה: החכ' והרצון."]]],[2300540153,"כו'. אך א\"כ הי' הכל חוזר למקור הראשון מקורא דכולא<sup data-n=\"10144\">21</sup>, ואנו רואים שגם ביום השבת נמשך האור והשפע האלקי' בכל ההשתלשלו' דאבי\"ע כו' בכל אופן פרטי ההמשכות העליונות ביחו\"ע דחכ' ומדות באו\"כ עד שנמשך לעולם העשי' בשפע גשמיות<sup data-n=\"10145\">*22</sup> דמזלות בדצח\"ם וארמ\"ע הגשמיי'. אך התירוץ ידוע שעיקר השביתה עכשיו הוא רק בבחי' הפנימי'<sup data-n=\"10146\">22</sup> דחכ' וכתר שעולה בעצמות א\"ס ב\"ה אבל בחי' החיצוני' נמשך בסדר ההשתל' <span data-k=\"pg\">606</span> ּ בשביל שפע כל העולמות דבי\"ע. והענין הוא כידוע שיש ב' מדרגות בחכמה<sup data-n=\"10147\">23</sup>, א' בחי' הפנימי' שנק' אין דחכ' שזהו בחי'<sup data-n=\"10148\">24</sup> שהחכמה למעלה מבחי' ההתפשטות והמשכה למטה עדיין להיות מקור להשגה דבינה שנק' יש, והוא בחי' נקודה דיו\"ד שנק' כח מ\"ה<sup data-n=\"10149\">25</sup> בחי' מ\"ה ממש וכמ\"ש והחכ' מאין תמצא<sup data-n=\"10150\">26</sup> בבחי' אין דכתר. והב' בחי' חיצוני' דחכמה שנמשך לבינה בהשגת השכל שזהו מאין ליש, והוא כללות ענין מע\"ב בי\"מ דבראשית ברא אלקי'<sup data-n=\"10151\">27</sup> דאבא א[מר] לאימא<sup data-n=\"10152\">28</sup> שנק' אלקים<sup data-n=\"10153\">29</sup> כידוע. וזהו עיקר ענין השביתה בשבת שהוא עולה בפנימי' דחכמה בחי' אין דכתר שנק' קדש מלה בגרמי'<sup data-n=\"10154\">30</sup> כידוע, אבל בחי' החיצוניות דחכ' נמשך גם בשבת לבינה ומבינה למדות ודיבור בי\"מ להיות התהוות העולמות מאין ליש ולחדש השפע בכל יום [בכל] וי\"ו ימי החול. ואמנם מפני בחי' העלי' הזאת בפנימי' דחכ' שבכתר כנ\"ל, ע\"כ [אמר] אז תתענג על הוי' כו' וכתי' וקראת לשבת ענג<sup data-n=\"10155\">31</sup> שחוזר ונמשך מחכ' לבינה ומדות או\"ח<sup data-n=\"10156\">32</sup> מבחי' העונג דאין דחכ' לכל ו' ימי החול, וע\"כ כל שבת נק' שבת בראשית<sup data-n=\"10157\">33</sup> (כמשי\"ת). וא\"כ עכ\"פ מובן מזה<sup data-n=\"10158\">34</sup> דשרש השבת הוא למעלה מן ההשתל' דשם הוי' דע\"ס כו', והיינו למעלה מבחי' הזמן דעבר הוה ועתיד, דשם הוי' מורה היותו עכ\"פ מקור לזמן דעבר הוה ועתיד שהוא ענין הי' הוה ויהי'<sup data-n=\"10159\">35</sup> אע\"פ שכוללם יחד מ\"מ שייך בו לומר ענין הי' ויהי', כמו בוא\"ש דהוי עלמא<sup data-n=\"10160\">36</sup> שכללותם הוא שם הוי' דחכ' דכולם בחכ' עשית<sup data-n=\"10161\">37</sup> מאין ליש בכללותם יחד ואח\"כ מתחלק בפרט כמארז\"ל במאמר א' יכול להבראות<sup data-n=\"10162\">38</sup> כו' והוא מאמר דבראשית דחכ' דבראשית נמי מאמר הוא<sup data-n=\"10163\">39</sup> כידוע, אבל בשבת עולה לפנימי' דחכ' למעלה גם ממקור הזמן דשם הוי' כנ\"ל וד\"ל.",[["10144","21","<b>מקורא דכולא</b>: זהר בראשית לג, א."],["10145","*22","<b>בשפע גשמיות</b>: ראה גם להלן רטו, ד ובהערה 334."],["10146","22","<b>שעיקר השביתה. . הפנימי'</b>: ראה סידור שער המילה קמא, ב. מאמרי אדה\"א שמות ח\"א ע' קנו־ ויקרא ח\"ב ע' תשסה ובהנסמן בהנ\"ל. לקמן פ' ויקהל תלז, א."],["10147","23","<b>ב' מדרגות בחכמה</b>: ראה גם לעיל פ' שמות לג, א."],["10148","24","<b>בחי'</b>: בה: כמו."],["10149","25","<b>שהחכמה. . כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א. ראה גם לעיל פ' שמות לג, א. וש\"נ."],["10150","26","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["10151","27","<b>דבראשית ברא אלקי'</b>: בראשית א, א."],["10152","28","<b>דאבא א[מר] לאימא</b>: נסמן לעיל יח, ד."],["10153","29","<b>לאימא שנק' אלקים</b>: ראה זהר בהקדמה ב, א ובמקדש מלך שם. כב, א. (תוספתא) בראשית לא, ב."],["10154","30","<b>קדש מלה בגרמי'</b>: זהר אמור צד, ב. ראה גם לעיל קכ, ב."],["10155","31","<b>וקראת לשבת ענג</b>: ישעי' נח, יג."],["10156","32","<b>או\"ח</b>: ה: אור חדש."],["10157","33","<b>כל שבת נק' שבת בראשית</b>: נסמן לקמן פ' יתרו רסד, א."],["10158","34","<b>עכ\"פ מובן מזה</b>: ה: מובן עכ\"פ."],["10159","35","<b>דשם הוי'. . הי' הוה ויהי'</b>: נסמן לעיל מט, ד."],["10160","36","<b>בוא\"ש דהוי עלמא</b>: ר\"ה לא, א. ראה הנסמן במאמרי אדה\"א בראשית ע' נג."],["10161","37","<b>דכולם בחכ' עשית</b>: תהלים קד, כד."],["10162","38","<b>במאמר א' יכול להבראות</b>: ראה גם לעיל פ' וארא פא, ג. וש\"נ."],["10163","39","<b>דבראשית נמי מאמר הוא</b>: ראש השנה לב, א."]]],[2300540190,"<b>וכמו\"כ</b> המן הי' שרשו [ב]למעלה מן הזמן ומקום דעולם שנה נפש<sup data-n=\"10164\">40</sup> כו', כי הנה מבואר למעלה דכל השתלשלו' העולמות מאין ליש נמשך מבחי' החכמה שמאין תמצא בבחי' יש כמ\"ש כולם בחכ' עשית, אבל המן הגם שנק' מזונא דחכ'<sup data-n=\"10165\">41</sup> כמ\"ש בזהר מ\"מ שרשו הי' בפנימי' דחכ' שהוא בבחי' אין דכתר כמו בשבת כנ\"ל שהוא למעלה מן החכ' דמע\"ב כנ\"ל. דהנה אנו מוצאים<sup data-n=\"10166\">42</sup> בשרש התהוות מציאות המן שהי' ע\"י הטל דוקא כמ\"ש ותעל שכבת הטל<sup data-n=\"10167\">43</sup> והנה ע\"פ המדבר דק מחוספס דק ככפור על הארץ, ופרש\"י כשהחמה זורחת עולה הטל שעל המן לקראת החמה כדרך הטל עולה כו', ובעל[ות] שכבת הטל נתגלה המן שמונח עליו וראו דק מחוספס כו'. וגם א' בפ' בהעלותך א'<sup data-n=\"10168\">44</sup> והמן כזרע גד לבן<sup data-n=\"10169\">45</sup> ועינו כעין הבדולח (שהוא שנק' טלא דבדולחא<sup data-n=\"10170\">46</sup> כו'<sup data-n=\"10171\">*47</sup> וברדת הטל על המחנה<sup data-n=\"10172\">47</sup> לילה ירד המן עליו (ואין זה סתירה<sup data-n=\"10173\">48</sup> למ\"ש ותעל שכבת [הטל] כו', דבלילה טל של לילה יורד והמן יורד עליו ובבוקר טל העולה לקראת החמה מתגלה המן מבין שכבת הטל העולה כו' ומשמע דב' מיני טל [הן<sup data-n=\"10174\">49</sup>, טל] היורד בלילה וכמ\"ש וברדת הטל כו' כמו שאו' מוריד הטל<sup data-n=\"10175\">50</sup> (ונק' <span data-k=\"pg\">שג</span> ּ רסיסי לילה<sup data-n=\"10176\">51</sup> כמ\"ש במ\"א בפי' שראשי נמלא טל) וטל העולה בבוקר והמן הי' בין שניהם כו').\n<b>והענין</b> הוא דשרש המן הוא נמשך מבחי' פנימי' ומקור החכ' שהוא נק' טלא דבדולחא שהוא נחשב מז' תיקונין דגלגלתא<sup data-n=\"10177\">52</sup> כו', ע\"כ ירידת המן הי' בירידת הטל דוקא. וזהו כמו שאנו רואים בנפש השכלית דאדם שיש בו ב' מדריגות בחכמה, א' מוח החכמה כמו שא' חכ' מוחא<sup data-n=\"10178\">53</sup> שכלול מחומר וצורה<sup data-n=\"10179\">54</sup> והחומר הוא כלי המוכן לצורה זהו רק לאור השכל הגלוי שנק' התחכמות שבא בגילוי אור מציאת שכל וסברא עכ\"פ (וזהו תלוי באיכות טוב מזיג' המוח מן הלחלוחי' שנק' מוח החכ' שהוא קר ולח<sup data-n=\"10180\">55</sup> כידוע). אבל מקור ההיולי של החכ' שנק' כח המשכיל בעצם כמו שהוא טרם שבא לגילוי אור מציאת שפע שכל זהו למעלה ממוח החכ' ואינו תלוי במזיגת המוח כלל, והוא כמו בחי' טל דק שלמעלה מן המוח אצל הגלגלת שמשם יאיר אור המקיף דחכ' הנק' כח [ה]משכיל כל השכלו' ויורד למטה ליתן כח ועוז במוח החכ' להשכיל כל שכל וחכ' בגילוי, כמו הטל",[["10164","40","<b>דעולם שנה נפש</b>: נסמן לעיל נג, ב."],["10165","41","<b>המן. . מזונא דחכ'</b>: ראה זהר בשלח סב, א. לקמן רי, ג."],["10166","42","<b>מוצאים</b>: ה: רואים."],["10167","43","<b>ותעל שכבת הטל</b>: בשלח טז, יד וברש\"י שם (בשינויים)."],["10168","44","<b>א'. . א'</b>: ב: א'. . ליתא. ה: ליתא. . אמר."],["10169","45","<b>והמן כזרע גד לבן</b>: בהעלותך יא, ז. בשלח טז, לא."],["10170","46","<b>טלא דבדולחא</b>: ראה זהר ויחי רכה, ב. תרומה קלו, ב. תזריע מט, א."],["10171","*47","<b>כו'</b>: כנצ\"ל: כו')."],["10172","47","<b>וברדת הטל על המחנה</b>: בהעלותך יא, ט."],["10173","48","<b>ואין זה סתירה</b>: ראה רש\"י בשלח טז, יג."],["10174","49","<b>דב' מיני טל [הן</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' קצו. במדבר ח\"ב ע' תרמה. דברים ח\"ד ע' א'קצז. פי' המלות פי\"ח."],["10175","50","<b>שאו' מוריד הטל</b>: בתפלת העמידה."],["10176","51","<b>רסיסי לילה</b>: שה\"ש ה, ב. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' כז. מאמרי אדה\"א במדבר שם."],["10177","52","<b>מז' תיקונין דגלגלתא</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. ע\"ח (שער א\"א) שי\"ג, פ\"ו."],["10178","53","<b>חכ' מוחא</b>: נסמן לעיל פ' שמות כח, ד."],["10179","54","<b>מחומר וצורה</b>: ראה מו\"נ ח\"א פי\"ז. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'קעו. שמות ח\"א ע' כג."],["10180","55","<b>מוח החכ' שהוא קר ולח</b>: נסמן לעיל פ' שמות כז, ג."]]],[2300540224,"היורד למטה ללחלח הארץ שמוסיף כח ועוז בכח הצומח<sup data-n=\"10181\">56</sup> שבארץ להצמיח ולהוליד מאין ליש כל צמח גשמי כמ\"ש במ\"א, כך יש בחי' טל דק בהעלם ודקות שהוא בחי' כלי לבחי' מקור האור והחיות דכח החכ' בעצם הנפש השכלי' (ובלשון הפלסופי' נק' שכל נבדל<sup data-n=\"10182\">57</sup> או שכל הפועל<sup data-n=\"10183\">58</sup> ובלשון המקובלים שכל מופלא<sup data-n=\"10184\">59</sup> שכל הנעלם מכ\"ר<sup data-n=\"10185\">60</sup> כו' והוא בחי' ח\"ס כו') שיורד למטה בכלי המוח ליתן בו כח ההתחכמות להוליד שכל חדש בכל דבר חכמה ושכל (וכמו\"כ בכח המוליד שבמוח להוליד ולד בא ממקיף זה) שהוא ג\"כ בחי' התענוג הנעלם הפשוט שבעצם הנפש שלמעלה מעונג שבשכל שבמוח שמתהווה מזה טפה הרוחניות במוח להוליד נפש השכלית בדומה לו שזהו כח המוליד מאין ליש כמו בארץ). וזהו ועינו כעין הבדולח דבחי' לחלוחית הטל הדק הזה מראה וגוון שלו זך ונקי ולבן כמראה וגוון האבן הבדולח וע\"כ נק' טלא דבדולחא (שהוא הטל שעתיד להחיות בו המתים<sup data-n=\"10186\">61</sup> ), וע\"כ הי' המן שירד על הטל הזה מראהו כמראה הבדולח שהוא בפנימי' ומקור דכח החכמה כמו שהוא בבחי' אין דכתר כנ\"ל.\n<b>וז\"ש</b> וברדת הטל כו' ירד המן עליו וכאן אמר ותעל שכבת הטל כו' דמן וטל ענין א' הוא בשרשם רק שיש במן ב' מדרגות, א' כמו שהוא במקומו למעלה שהוא למעלה גם מרוחניות דאור השכל שבמוח כנ\"ל, והב' בירידתו למטה ש[נ]תגשם ביותר כמ\"ש והמן כזרע גד לבן כו' שדכו במדוכה<sup data-n=\"10187\">62</sup> כו' ונעשה בחי' מזון גשמי כלחם גשמי והוא בירידתו למטה שאז עינו ומראהו כעין הבדולח הגשמי וטעמו כטעם<sup data-n=\"10188\">63</sup> כו' בטעם גשמי, והוא כמו שהטל בירידתו למטה ש[נ]תגשם ללחלח חלקי הארץ הגשמי שתצמיח ותוליד, אבל כמו שהטל למעלה נק' טל השמים<sup data-n=\"10189\">64</sup> שהוא דק הרבה יותר מן האויר הזך כו', וזהו מוריד הטל, וכך הוא המן שנק' לחם מן השמים<sup data-n=\"10190\">65</sup> וי[ו]רד למטה ומתגשם עד שדכו במדוכה והי' למזון גשמי ולחיות גשמי כמו מן הלחם הגשמי כו'. אך עכ\"ז אינו כמזון דלחם <span data-k=\"pg\">608</span> ּ מן הארץ שיש בו תערובות טו\"ר והרי במזון המן לא הי' פסולת<sup data-n=\"10191\">66</sup> כלל, והיינו לפי שגם שנעשה מזון לחזק המוח דחכמה [כ]לחם גשמי אבל נק' מזונא דחכ' שהוא מזון רוחני לאור החכמה שיוכל להשכיל כל שכל בגילוי מן ההעלם כנ\"ל, וכמו שא' במ\"ש לחם אבירים אכל איש<sup data-n=\"10192\">67</sup> זה משה שאכל לחם שמ\"ה<sup data-n=\"10193\">68</sup> ניזוני' בו כו', ומזון זה דמ\"ה ה\"ז מזון ושפע רוחניות ל[ח]יות אור השכל דהשגת המלאכים",[["10181","56","<b>הטל. . שמוסיף. . בכח הצומח</b>: ראה סידור שחרית לשבת קעט, ג. פיה\"מ פי\"ח. פי\"ט."],["10182","57","<b>שכל נבדל</b>: ראה מו\"נ ח\"א פמ\"ט. ח\"ב פ\"ב. פ\"ג־ פ\"ד [ושם: שכליים נפרדים]. ח\"ג פ\"ט. רמב\"ם הל' יסודי התורה פ\"ב ה\"ג [ושם: צורות נפרדות. וראה בהפירוש שם]."],["10183","58","<b>שכל הפועל</b>: ראה מו\"נ ח\"ב פ\"ד."],["10184","59","<b>שכל מופלא</b>: נסמן לעיל פ' שמות לג, א."],["10185","60","<b>שכל הנעלם מכ\"ר</b>: נסמן לעיל פ' שמות מז, ג."],["10186","61","<b>הטל שעתיד להחיות בו המתים</b>: ראה שבת פח, ב."],["10187","62","<b>שדכו במדוכה</b>: בהעלותך יא, ח."],["10188","63","<b>וטעמו כטעם</b>: בהעלותך שם."],["10189","64","<b>טל השמים</b>: תולדות כז, כח. לט. ראה גם פלח הרמון שה\"ש פ, א."],["10190","65","<b>לחם מן השמים</b>: בשלח טז, ד."],["10191","66","<b>המן לא הי' פסולת</b>: נסמן לעיל קסא, א."],["10192","67","<b>לחם אבירים אכל איש</b>: תהלים עח, כה. יומא עה, ב. וראה גם שה\"א נט, ב הערה 31."],["10193","68","<b>שמ\"ה</b>: ה: שמלאכי השרת."]]],[2300540256,"[ה]<b>עליונים</b>, כך הי' המן מזון רוחני להחיות הנשמות בכח ההשגה האלקי' כו' ולכך נק' מזונא דחכ' כמו שהחכמה תחי'<sup data-n=\"10194\">69</sup> כו' (וא\"כ ה\"ז שפע שנמשך מן החכ' ואין כל חדש בזה שכל חיי' הנמצאים כולם מן החכ' כמ\"ש כולם בחכמה עשית ויש בזה הסתעפות להיות תערובות טו\"ר לפי שהאור מצומצם בכלי בבחי' או\"פ כו', ואמנם מ\"ש בזהר דהמן נק' מזונא דחכ' היינו שהי' מזון לאור החכ' עילאה לחזק<sup data-n=\"10195\">70</sup> כח החכמה ממקורה בהעלם דמקיף דחכמה (שנק' ח\"ס כנ\"ל) שלמעלה מן החכ' המצומצם בכלי שנק' צורה בחומר, וע\"כ לא הי' בו פסולת כלל להיותו למעלה מעה\"ד טו\"ר (דהיינו בפנימי' אבא שנק' עה\"ח שהוא פנימי' ע\"י<sup data-n=\"10196\">71</sup> והוא בחי' טלא דבדולחא הנ\"ל שזהו בחי' גבו' דע\"י שמלובש בח\"ס<sup data-n=\"10197\">72</sup> כבדולח הלבן דגוונא סומקא אתחזי בי'<sup data-n=\"10198\">73</sup> בהעלם כו'). ומה שירד המן ונתגשם עד שדכו במדוכה בירידת הטל כו' זהו ירידת אור המקיף דחכ' שיורד ומתלבש למטה בגשמיות דוקא והי' למזון גשמי לחזק המוח דחכ' בצורה וחומר באופן שלא הי' בו פסולת כו'<sup data-n=\"10199\">74</sup> ) (וכן לחה\"פ במקדש שכולו פנים<sup data-n=\"10200\">75</sup> בלי חיצוני' ואחוריי' כלל, וכמו לחם פנג<sup data-n=\"10201\">76</sup> דלע\"ל, ומעין זה סעודות [ה]שבת שנק' סעוד' דע\"י שאינו מגשם כ\"כ, ומותר לאכול לתיאבון<sup data-n=\"10202\">77</sup> כמ\"ש פרש חגיכם<sup data-n=\"10203\">78</sup> ולא פרש שבתכם כידוע) שזהו בחי' עונג הנעלם שבא במורגש כמו בתחה\"מ ועוה\"ב כמ\"ש במ\"א), וע\"ז נאמר ימותו ולא בחכמה<sup data-n=\"10204\">79</sup> כו' דבפנימי' דחו\"ב לא הי' שבירה כלל רק בחיצוני' דחכ' שנק' יש שהוא כח\"ב דמע\"ב שכולם בחכ' עשית שיש שם אחיזה לטו\"ר בתערובו' שממנו יסתעף המות, וע\"כ עיקר תחה\"מ בטל העליון דפנימי' החכ' כנ\"ל (ואע\"פ שגם עתה הרי יש מקור לחכ' שבגילוי ממקור החכ' שנק' כח המשכיל בעצם הנ\"ל ונמשך ממנו המדות דחו\"ב<sup data-n=\"10205\">80</sup> שיש בהן נטי' לטו\"ר בבחי' פסולת ומותרות שי[ו]צא מנקוד' האמת כמו חכמים המה להרע<sup data-n=\"10206\">81</sup> כו', זהו מבחי' החיצוני' דמקור החכ' שממנו נמשך גם שפע חיצוני' ומותרות בחו\"ב ומדות, משא\"כ בפנימי' דח\"ס (וכמשי\"ת). וא\"כ הרי מובן מזה עכ\"פ ששרש המן הוא בפנימי' ומקור הח\"ע שלמעלה מן החכ' הבאה בהשתלשלו' דזמן ומקום שזהו למעלה משם הוי' כמו בשבת כנ\"ל (והיינו למעלה מבחי' חכ' מוחא כו', ועכ\"ז נק' בשם מזונא דחכ' דוקא כי הוא מקור העליון דחכמה בבחי' מקיף לאו\"פ ויורד למטה ונתגשם במזון גשמי, אך שלא הי' בו פסולת כלל מטעם הנ\"ל וד\"ל). ואין זה פלא כלל איך יוכל להיות או\"מ בא למטה בהגשמה כ\"כ, דאדרבה לפי שאו\"מ למעלה מן ההשתל' דאו\"כ יוכל לבא למטה",[["10194","69","<b>שהחכמה תחי'</b>: קהלת ז, יב."],["10195","70","<b>לחזק</b>: ב: לחדש."],["10196","71","<b>בפנימי' אבא. . פנימי' ע\"י</b>: נסמן לעיל פ' שמות כג, א."],["10197","72","<b>גבו' דע\"י שמלובש בח\"ס</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ו. פ\"ז."],["10198","73","<b>דגוונא סומקא אתחזי בי'</b>: ראה זהר (אד\"ר) נשא קלה, ב. ביאוה\"ז תזריע עא, ג. עב, סע\"ד. מאמרי אדה\"ז תקס\"ג ח\"א ע' שלג. תקס\"ה ח\"א ע' תכז."],["10199","74","<b>כו')</b>: בה: כלל."],["10200","75","<b>לחה\"פ. . שכולו פנים</b>: ראה מנחות צו, א. לעיל פ' בא קכז, ב הערה 679."],["10201","76","<b>לחם פנג</b>: נסמן לעיל כג, ב."],["10202","77","<b>סעודות [ה]שבת. . לתיאבון</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תקעו. וש\"נ. קונטרסים ע' רמב. וש\"נ. לקמן רטז, א. רנ, ב. פ' ויקהל תיח, ד. תכב, א."],["10203","78","<b>פרש חגיכם</b>: נסמן לעיל פ' בא קכ, ג."],["10204","79","<b>ימותו ולא בחכמה</b>: איוב ד, כא. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' ט וע' רצט. לקמן פ' ויקהל תכא, ג הערה 1209."],["10205","80","<b>דחו\"ב</b>: בה: דחו\"ג."],["10206","81","<b>חכמים המה להרע</b>: ירמי' ד, כב."]]],[2300540286,"בחיצוני' הלבושי' יותר כמו ענני כבוד שבמדבר שקיבלו החיצי'<sup data-n=\"10207\">82</sup> כו' וכה\"ג גם <span data-k=\"pg\">דש</span> ּ במזון כו' וד\"ל (אך א\"כ י\"ל דאם הי' שרש מזון המן מבחי' פנימי' החכ' שנק' עה\"ח שלמעלה מעה\"ד כו' שאין שם שרש למות ורע כלל א\"כ הרי [הי'] חיי' בחיות נצחי ולא הי' המות שולט בהן כלל ובאמת לא הי' כן עד מ\"ת שעמדו בה\"ס שאז פסקו מהן זוהמא<sup data-n=\"10208\">83</sup> של נחה\"ק כו' ובמן א' למען אנסנו הילך בתורתי אם לא<sup data-n=\"10209\">84</sup> כו' (ועוד י\"ל בעיקר הענין איך נעשה המן בבחי' מזון ומאכל אם הי' שרשו מבחי' המקיף דחכ' [שבכתר] ששם לא שייך בחי' אכילה כלל כמ\"ש בזהר על מ\"ש באתי לגני כו' אכלתי יערי כו' אבל באתרי' לאו אורחי' למיכל<sup data-n=\"10210\">85</sup> כו', ומ\"ש אכלו ריעים זהו בבחי' חו\"ב<sup data-n=\"10211\">86</sup> דאצי' שבאים בבחי' או\"כ כו' כנ\"ל) (וראי' מיו\"כ ועוה\"ב שאין בו אכילה ושתי' כלל).\n<b>אך</b> הנה הדוגמא האמיתי' לשרש המזון דמן הוא ענין שרש החכ' שבתורה שנק' ג\"כ לחם מן השמים דוקא כמ\"ש מן השמים השמיעך את קולו<sup data-n=\"10212\">87</sup> דהתורה מן השמים ניתנה<sup data-n=\"10213\">88</sup> וירד[ה] למטה בארץ לברר לעה\"ד טו\"ר, וזהו שניתן להם המן ך\"א יום קודם למ\"ת<sup data-n=\"10214\">89</sup> דוקא כמ\"ש למען אנסנו הילך בתורתי אם לא כו'. דהנה ידוע שהתורה קדמה לעולם<sup data-n=\"10215\">90</sup> אפי' לעולם הנאצל<sup data-n=\"10216\">91</sup> ונק' תוה\"ק<sup data-n=\"10217\">92</sup> שהיתה כלולה בעצמות הא\"ס ממש וכמ\"ש ואהי' אצלו אמון<sup data-n=\"10218\">93</sup> כו' אמון מוצנע<sup data-n=\"10219\">94</sup> כו' (וכמו כח המשכיל שכלול בנפש השכל[י'] כו') והוא בבחי' אין האמיתי שז\"ש והחכ' מאין תמצא כו', וע\"כ נק' התורה חכמה ברורה<sup data-n=\"10220\">95</sup> שכבר הובררה בעצמות החכ' דא\"ס שנק' חכים ולא בחכ' ידיעא<sup data-n=\"10221\">96</sup> כו', ומפני זה נק' התורה אמת<sup data-n=\"10222\">97</sup> שהוא בבחי' אמיתי' אור העצמות ופנימי' דרצון ותעה\"פ שבעצמות א\"ס כו'. וזהו שהתוה\"ק היא בבחי' עה\"ח ממש שכולו חיים וטוב ואין שם שרש לעה\"ד כלל (וכמו\"כ נשמת משה הי' משם כמ\"ש בו<sup data-n=\"10223\">98</sup> כי טוב הוא בטי\"ת רבתי<sup data-n=\"10224\">99</sup> כי מן המ\"ע דחכ' הקדומה משיתיהו<sup data-n=\"10225\">100</sup> כו') שהוא למעלה הרבה מבחי' החכ' ורצון דמע\"ב, שז\"ש שקדמה לעולם אלפים שנה<sup data-n=\"10226\">101</sup> והוא מ\"ש בראשית בשביל התורה שנק' ראשית<sup data-n=\"10227\">102</sup> כו' כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"10228\">103</sup> כו' כידוע דאסתכל באורייתא וברא עלמא<sup data-n=\"10229\">104</sup> כו' כדי",[["10207","82","<b>ענני כבוד. . החיצי'</b>: נסמן לעיל קכא, ב הערה 321."],["10208","83","<b>מ\"ת. . פסקו מהן זוהמא</b>: שבת קמו, רע\"א."],["10209","84","<b>למען אנסנו. . אם לא</b>: בשלח טז, ד."],["10210","85","<b>באתי לגני. . באתרי' לאו אורחי' למיכל</b>: שה\"ש ה, א. ראה זהר פינחס רמא, סע\"ב."],["10211","86","<b>אכלו ריעים. . חו\"ב</b>: שה\"ש שם. זהר ויקרא ד, א."],["10212","87","<b>מן השמים השמיעך את קולו</b>: ואתחנן ד, לו."],["10213","88","<b>דהתורה מן השמים ניתנה</b>: נסמן לעיל יב, א."],["10214","89","<b>המן ך\"א יום קודם למ\"ת</b>: ראה שבת פז, ב וברש\"י שם. תוספתא סוטה יא, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תריד ובהנסמן במ\"מ לשם. מאמרי אדה\"א שמות ח\"א ע' קנא. וש\"נ."],["10215","90","<b>התורה קדמה לעולם</b>: פסחים נד, א."],["10216","91","<b>התורה קדמה. . לעולם הנאצל</b>: נסמן לעיל פ' וארא עט, ד."],["10217","92","<b>תוה\"ק</b>: נסמן לעיל ב, ד."],["10218","93","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["10219","94","<b>אמון מוצנע</b>: ב\"ר בתחלתו."],["10220","95","<b>התורה חכמה ברורה</b>: נסמן לקמן הערה 109."],["10221","96","<b>חכים ולא בחכ' ידיעא</b>: נסמן לעיל ד, ד."],["10222","97","<b>נק' התורה אמת</b>: מלאכי ב, ו."],["10223","98","<b>בו</b>: בה: ליתא."],["10224","99","<b>כי טוב הוא בטי\"ת רבתי</b>: נסמן לעיל פ' שמות מג, ד."],["10225","100","<b>כי מן. . משיתיהו</b>: נסמן לעיל מג, א."],["10226","101","<b>שקדמה לעולם אלפים שנה</b>: נסמן לעיל פא, ג."],["10227","102","<b>בראשית בשביל התורה שנק' ראשית</b>: בראשית א, א. ראה רש\"י שם. הנסמן בלקו\"ש נח (כרך ג) ע' 755."],["10228","103","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["10229","104","<b>דאסתכל באורייתא וברא עלמא</b>: נסמן לעיל פא, ג."]]],[2300540314,"לתקן לעה\"ד טו\"ר משום דבחכ' אתברירו<sup data-n=\"10230\">105</sup> כו'. וז\"ש אשר ברא אלקי' לעשות לתקן<sup data-n=\"10231\">106</sup> והוא ע\"י קבלת התו\"מ בישראל שגם הם נק' ראשית תבואתו<sup data-n=\"10232\">107</sup> כמא' ג' קשרים הן<sup data-n=\"10233\">108</sup> ישראל מתקשראן [באורייתא] כו', וא\"כ הרי החכ' דתורה שהיא חכ' ברורה בתכלית כמ\"ש כל אמרת אלוה צרופה<sup data-n=\"10234\">109</sup> כו' אל תוסף<sup data-n=\"10235\">110</sup> כו' ירדה למטה בחכ' ומדות דמע\"ב לתקן לעה\"ד טו\"ר שהן תרי\"ג<sup data-n=\"10236\">111</sup> מצות בסומ\"ר וע\"ט לאהפכא חשוכא<sup data-n=\"10237\">112</sup> כו', לפי שכל בחי' בירור צריך להיות ממקור<sup data-n=\"10238\">113</sup> המבורר בעצמו<sup data-n=\"10239\">114</sup> (וע\"כ תורה צוה לנו משה<sup data-n=\"10240\">115</sup> דוקא שהי' נשמתו מח\"ע דתורה שכבר הובררה כו'). וזהו שהתורה נק' לחם מן השמים דוקא שזהו בבחי' מקיף דח\"ע [העצמי' שנק' מ\"ע שירדה למטה בבחי' לחם ומזון, אך הוא לחם ומזון דח\"ע] שהיא ברורה בתכלית ונק' לחם מן השמים וכמו במן שאמר הנני ממטיר לכם לחם מן השמים כו'. ואמנם ירדה התורה למטה עוד והוא בבחי' עה\"ד טו\"ר כדי לתקן ולהעלות רפ\"ח ניצוצין<sup data-n=\"10241\">117</sup> דתהו כנ\"ל ואז נק' לחם מן הארץ, וזהו ירידת ח\"ע בח\"ת דהיינו תושב\"כ<sup data-n=\"10242\">118</sup> בתושבע\"פ<sup data-n=\"10243\">116</sup> וז\"ש לכו לחמו בלחמי כו' שהן שתי הלחם<sup data-n=\"10244\">119</sup> דשבועות כידוע. וזהו ותורתך בתוך מעי<sup data-n=\"10245\">120</sup> כמזון גשמי לגוף כך התורה <span data-k=\"pg\">610</span> ּ הנגלית לנו דוקא נק' מזון רוחני לחיי הנשמות כמו [כי] אמרתך חייתני<sup data-n=\"10246\">121</sup> וכן א' כי הוא חייך<sup data-n=\"10247\">122</sup> ואורך ימיך, וכתיב אורך ימים בימינה<sup data-n=\"10248\">123</sup> כו', ובחי' אור וחיות זה נק' חיי עולם כמו בחי' עה\"ח שכולו חיים וטוב כו' שאין למות שרש אחיזה שם כלל וכמו ימותו ולא בחכמה כו' כנ\"ל (ולכך במ\"ת הי' בבחי' עה\"ח חירות ממ\"ה<sup data-n=\"10249\">124</sup> לגמרי לפי שפסקה מהם זוהמא כו' וגם עכשיו בכל עוסק בתורה לשמה זהו כמ\"ת ממש שדבריו חיים וקיימים<sup data-n=\"10250\">125</sup> כמ\"ש ואשים דברי בפיך<sup data-n=\"10251\">126</sup> כו' שאין מ\"ה יכול לשלוט בו כלל (כענין יעקב לא מת<sup data-n=\"10252\">127</sup> ) כמו ברכה בנח\"ו<sup data-n=\"10253\">128</sup> ). אך עכ\"ז לפי שנתלבשה התורה בעה\"ד טו\"ר לברר ולהבדיל בין טו\"ר נק' לחם מן הארץ שצריך בירור עכ\"פ בין טו\"ר כלחם הגשמי כך תורתך בתוך מעי כו', וע\"כ במי שאינו עוסק בתורה לשמה וכ\"ש כשאינו מקיים מ\"ש בתורה כו', נהפך לו מחיים למות כמ\"ש למשמאילים בה סמא דמותא<sup data-n=\"10254\">129</sup> (משא\"כ בפנימי' התורה כמו שהוא בבחי' עה\"ח שנק' לחם מן",[["10230","105","<b>דבחכ' אתברירו</b>: נסמן לעיל י, ג."],["10231","106","<b>אשר ברא אלקי' לעשות לתקן</b>: נסמן לעיל קלט, ד."],["10232","107","<b>ראשית תבואתו</b>: ירמי' ב, ג."],["10233","108","<b>ג' קשרים הן</b>: נסמן לעיל ב, ד."],["10234","109","<b>כל אמרת אלוה צרופה</b>: משלי ל, ה. ראה גם לעיל קעג, ב. וש\"נ."],["10235","110","<b>אל תוסף</b>: משלי שם, ו."],["10236","111","<b>תרי\"ג מצות</b>: נסמן לעיל קפט, ג."],["10237","112","<b>לאהפכא חשוכא</b>: ראה זהר בהקדמה ד, א."],["10238","113","<b>ממקור</b>: ה: ממקום."],["10239","114","<b>שכל בחי' בירור. . המבורר בעצמו</b>: ראה גם לקמן פ' ויקהל תיז, ד. וש\"נ."],["10240","115","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["10241","117","<b>רפ\"ח ניצוצין</b>: נסמן לעיל פ' שמות לו, ג."],["10242","118","<b>ח\"ע בח\"ת דהיינו תושב\"כ בתושבע\"פ</b>: ראה גם לעיל פ' וארא עא, ג. וש\"נ."],["10243","116","<b>שהתורה נק' לחם מן השמים. . מן הארץ. . תושב\"כ בתושבע\"פ</b>: ראה גם לעיל ב, ד. וש\"נ."],["10244","119","<b>לכו לחמו בלחמי. . שתי הלחם</b>: משלי ט, ה. ראה השמטות לזח\"א רס, א."],["10245","120","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["10246","121","<b>[כי] אמרתך חייתני</b>: תהלים קיט, נ."],["10247","122","<b>כי הוא חייך</b>: נצבים ל, כ."],["10248","123","<b>אורך ימים בימינה</b>: משלי ג, טז."],["10249","124","<b>במ\"ת. . חירות ממ\"ה</b>: ראה שמו\"ר פל\"ב, א. פמ\"א, ז. זהר בראשית לז, ב."],["10250","125","<b>שדבריו חיים וקיימים</b>: ע\"פ ברכת אמת ויציב."],["10251","126","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["10252","127","<b>יעקב לא מת</b>: תענית ה, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670110\" data-slug=\"torat-chaim\" data-id=\"2300670110\">תו\"ח נח סד, ד</a> הערה 60. שע\"ת כד, ג הערה 40."],["10253","128","<b>ברכה בנח\"ו</b>: ב: ברבה ב\"נ. ה: ברב\"נ כו' — נסמן לעיל פ' בא צב, ג הערה 291."],["10254","129","<b>למשמאילים בה סמא דמותא</b>: ראה גם לעיל פ' שמות ג, ד. וש\"נ."]]],[2300540339,"השמים שכולו חיים וטוב כנ\"ל) וכמשל הסם של הרפואה דמי שאינו ראוי לה יהי' לו לסם המות ולמי שראוי לה הוא סם חיים וזהו למיימינים בה סמא דחיי<sup data-n=\"10255\">130</sup> כו'. וכ\"ז מצד שהתורה נק' מזון גשמי שבא בהתלבשו' בעה\"ד בבירור דטו\"ר ממש כו', וכמ\"ש ראה נתתי לפניך<sup data-n=\"10256\">131</sup> החיים והטוב והמות והרע כו' ובחרת בחיים<sup data-n=\"10257\">132</sup> וכן א' את הברכה אשר תשמעון<sup data-n=\"10258\">133</sup> כו'. אבל בחי' מזון דמן שנק' לחם מן השמים לא הי' בו פסולת מעה\"ד כלל וכלל כנ\"ל לפי שהי' מבחי' טל העליון דהיינו מבחי' מקיף דח\"ע שנק' טל תורה שהוא בבחי' עה\"ח וירד כמו שהוא למטה בהגשמה כזרע גד לבן להיות למזון גשמי לחזק המוח דחכ' ומדות כו' שיהי' בה כח לברר לעה\"ד טו\"ר בחכ' ומדות שבתורה הנגלית שבא בעה\"ד (כי באמת מצד עצם אור דתורה גם כמו שהיא בהתלבשות בעה\"ד טו\"ר כמדות דתורה כשר פסול טמא טהור כו' להבדיל בין טו\"ר אין בה אחיזה לחיצוני' כלל ונק' חיי עולם, וראי' מהקורא ושונה<sup data-n=\"10259\">134</sup> כו' שזהו דבר ה' ממש כנ\"ל כמו במ\"ת שהוא בבחי' עה\"ח שאין למות שליטה שם כלל גם עכשיו רק מצד בחי' המקבל כשקורא ושונה של\"ש<sup data-n=\"10260\">135</sup> נהפך לו<sup data-n=\"10261\">136</sup> לסם המות כנ\"ל. וראי' לזה ממה שד\"ת אי[נם] מקבלים טומאה כלל דבע\"ק מותר בד\"ת<sup data-n=\"10262\">137</sup> ואין אור הגיהנם שולט בת\"ח<sup data-n=\"10263\">138</sup> כו' משום דגם בחושך לא יחשיך<sup data-n=\"10264\">139</sup> אור דתורה מצד שרשו במקיף דאור החכ' שלמעלה מן ההשתל' דאו\"כ כנ\"ל).\n<b>וזהו</b> למען אנסנו הילך בתורתי אם לא דמטעם זה ניתן להם מזון המן קודם מ\"ת שיהי' לנסיון אם ילכו בתורתי שבבחי' עה\"ח שבאה בעה\"ד לברר כנ\"ל אם יוכלו לברר בין טו\"ר אם [לא, זה הי' הנסיון באכילת המן דווקא אם יוכלו לקבל מזון המן הגשמי שהוא בלי פסולת כלל שיהי' מוסיף כח בחכמה דנשמה כמו שהיא בגוף גשמי' שבעה\"ד לתקן] לעה\"ד כמשל הטל שמלחלח הארץ שתוליד ותצמיח כנ\"ל וד\"ל). וזהו ויענך וירעיבך<sup data-n=\"10265\">140</sup> ויאכילך את המן כו' שהוא במקיף דכתר דח\"ע (שלא ידעו אבותיך כי שרש האבות במדות דחו\"ב ששרשם בחג\"ת דא\"א וע\"י<sup data-n=\"10266\">141</sup> ולא בפנימי' דג\"ר דע\"י וא\"א כו') להודיעך כי לא על הלחם לבדו יחי' האדם שזהו לחמה של תורה כמו שבאה בעה\"ד כו' שיחיו לנשמת האדם כנ\"ל, <span data-k=\"pg\">שה</span> ּ כי עיקר כח חיות זה הוא בא ונמשך מבחי' מקור הפנימי' דח\"ע שזהו על כל מוצא פי הוי' דחכ' שנק' מקור מוצא לפי הוי' דחכ' דתורה שבדבור מזה עיקר ומקור הכח לנשמת האדם שיוכל לברר לעה\"ד כו' ויחי' חיי עולם ולא על הלחם לבדו, כמו האומר אין",[["10255","130","<b>למיימינים בה סמא דחיי</b>: נסמן בהערה שלפנ\"ז."],["10256","131","<b>ראה נתתי לפניך</b>: נסמן לעיל קמו, ד."],["10257","132","<b>ובחרת בחיים</b>: נצבים ל, יט."],["10258","133","<b>את הברכה אשר תשמעון</b>: נסמן לעיל קלה, א."],["10259","134","<b>מהקורא ושונה</b>: נסמן לעיל פ' וארא נח, ג הערה 18."],["10260","135","<b>של\"ש</b>: ב: שלא לשמה."],["10261","136","<b>לו</b>: בה: ליתא."],["10262","137","<b>שד\"ת. . דבע\"ק מותר בד\"ת</b>: ברכות כב, א. לקמן פ' יתרו רנד, א ובהנסמן שם. תצוה שע, ג."],["10263","138","<b>ואין אור הגיהנם שולט בת\"ח</b>: ראה חגיגה כז, א. מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תשצד. לקמן פ' יתרו רנד, א ובהנסמן שם."],["10264","139","<b>דגם בחושך לא יחשיך</b>: ע\"פ תהלים קלט, יב."],["10265","140","<b>ויענך וירעיבך</b>: עקב ח, ג."],["10266","141","<b>שרש האבות. . בחג\"ת דא\"א וע\"י</b>: נסמן לעיל קנח, ב."]]],[2300540362,"לי אלא תורה<sup data-n=\"10267\">142</sup> כמו שהיא למטה אפי' תורה אין לו ואין התומ\"צ מתקיימים<sup data-n=\"10268\">143</sup> אלא במי שממית עצמו עליה<sup data-n=\"10269\">144</sup> ולא במי שמחיה עצמו בה כו' כדוגמא שא' הרוצה לחיות ימית א\"ע<sup data-n=\"10270\">145</sup> והרוצה למות יחיה עצמו כו', ומ\"ש כי הוא חייך זהו על כל מוצא פי ה' שבתו'<sup data-n=\"10271\">146</sup> ) בדיבור, וזהו כי על כל כו' שהוא המן שקודם מ\"ת. וא\"כ הרי יובן עכ\"פ ששרש התורה עליונה גם כמו שבאה למטה אין בה שינוי מצד העצם כלל רק מצד המקבלים, א\"כ גם התורה היא למעלה מן ההשתלשלו' דחכמה דמע\"ב, וזהו אם לא בריתי<sup data-n=\"10272\">147</sup> כו' דגם אותיות התורה בנגלה הן מקור לחיות כל מע\"ב כי הרי אין העולם מתקיים אלא בהבל תשב\"ר<sup data-n=\"10273\">148</sup> לפי שהוא הבל שאין בו חטא וכשקורא ושונה ההלכה הוא בחי' מקור מוצא פי הוי' דמקיף דח\"ע דעה\"ח הנ\"ל וד\"ל (ונמצא דג' אלה המן ושבת ותורה הן למעלה מבחי' החכ' דמע\"ב שבזמן ומקום כי שרש א' להם בפנימי' אבא שהוא פנימי' ע\"י רק שהמן הי' הכנה למ\"ת כנ\"ל וע\"כ מצות ת\"ת יום ולילה בתמידית<sup data-n=\"10274\">149</sup> כידוע).\n<b>וזהו</b> הנני ממטיר לכם לחם מן השמים דהיינו מבחי' השמים העליונים שהוא בחי' המקיף הכללי דכתר עליון שמקיף לכל ההשתלשלו' דאבי\"ע והוא מבחי' טל העליון שנק' טל השמים העליונים שהוא בחי' טלא דבדולחא הנ\"ל שלמעלה מן החכמה דמע\"ב שנמשך ע\"י צמצום והתפשטות באו\"כ כנ\"ל, אך בירידתו למטה בארץ נתגשם והי' כזרע גד לבן כו', עכ\"ז לא הי' בו שינוי בעצם מכמו [ש]הוא למעלה כי הרי הי' מזון רוחני לנשמה וגם לגוף בתכלית הבירור מן הפסולת והי' בו כח ועוז לברר גם לנה\"ט שבגופי' גשמיי' שיוכלו להתברר ע\"י תורה ומצות כנ\"ל (כמו הדיבור דדברי תורה שהוא מזון לנשמה בבחי' חיי עולם דעה\"ח כמו שהוא למעלה לעוסק בתורה לשמה ואין השינוי רק מצד המקבל[ים] וראי' ממ\"ת שהי' חירות ממות כו' ולולי חטא העגל כידוע. ובזה יתורץ הקושיא דלעיל מה שלא הי' המן לחיות נצחי כי זה הי' המניעה מצד המקבלים שהן הגופים שנמשכו מק\"נ בתערובות דטו\"ר (ועכ\"ז הי' מזון המן לחיות גשמי גם בחיצוניות האברים שנבלע בהן<sup data-n=\"10275\">150</sup> כמו שהוא בלי פסולת כלל וכלל), משא\"כ בתחה\"מ שיחיו חיי עולם מטל העליון הזה עצמו כמ\"ש כי טל אורות טלך<sup data-n=\"10276\">151</sup> כו' לפי שיהי' אחר הבירור דעה\"ד בתכלית והוא ענין הטהרה עליונה שמביאה לידי קדושה<sup data-n=\"10277\">152</sup> בעוה\"ב בגילוי אור העצמות דא\"ס ממש בפנימי' התענוג הנעלם ופנימי' רצה\"ע שבמצות כמו שהן למעלה",[["10267","142","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["10268","143","<b>התומ\"צ מתקיימים</b>: ב: התורה מתקיים. ה: התורה מתקיימת."],["10269","144","<b>ואין התורה מתקיימת. . עליה</b>: נסמן לעיל פ' שמות ד, א."],["10270","145","<b>הרוצה לחיות ימית א\"ע</b>: ראה תמיד לב, א."],["10271","146","<b>שבתו')</b>: בה: שבתו'."],["10272","147","<b>אם לא בריתי</b>: ירמי' לג, כה."],["10273","148","<b>אין העולם מתקיים. . תשב\"ר</b>: ראה גם לעיל פא, ד. וש\"נ."],["10274","149","<b>מצות ת\"ת. . בתמידית</b>: נסמן לעיל פ' וארא פא, א."],["10275","150","<b>המן. . בחיצוניות האברים שנבלע בהן</b>: יומא עה, ב. ראה גם לקמן רטז, ג."],["10276","151","<b>כי טל אורות טלך</b>: ישעי' כו, יט."],["10277","152","<b>הטהרה. . שמביאה לידי קדושה</b>: נסמן לעיל פ' שמות ז, א."]]],[2300540383,"במהו\"ע ית' ממש שנק' קדושת העצמות [ממש] כו' (שלמעלה גם מקדש העליון דפנימי' ח\"ע שנק' טעמי מצות <span data-k=\"pg\">612</span> ּ בפנימי' ח\"ס). אבל מזון המן שנעשה מטל העליון בהגשמה [ש]נק' מזונא דחכ[מתא] שבא ונמשך לחזק כח החכ' ומדות דנר\"נ דאדם שיובררו מעה\"ד טו\"ר ע\"י קיום התו\"מ בגשמיות זהו נק' טהרה, לטהר ולזכך העכרורי' כמו מי יתן טהור מטמא<sup data-n=\"10278\">153</sup> כו' והוא כל התורה כולה להבדיל בין טמא לטהור כו', וזהו טהרה שמביאה לידי קדושה דמצות בפו\"מ שמפני זה הי' טעם הקדמו' המן למ\"ת כמ\"ש למען אנסנו הילך כו'.\n<b>וזהו</b> והמן כזרע גד לבן כו' דלובן זה מורה על היותו ברור בתכלית מן הפסולת בעצם הווייתו כזרע גד לבן ולא כשאר זריעה שבאה בתערובות טו\"ר ומתברר ויוצא הפסולת בפ\"ע כקליפה לפרי כו' וע\"כ הי' הכנה לקדוש' דמצות בפו\"מ, ועינו כעין הבדולח שהוא כמו אבן השוהם שהוא ברור וזך ונקי בעצם הווייתו<sup data-n=\"10279\">154</sup>, כך אבן הבדולח מראהו זך ולבן ונקי בתכלית, וכך הי' המן זך ונקי בעצם בלי פסולת כלל להיות שרשו למעלה בבחי' פנימי' הח\"ע שכולו פנימי' ואין בו חיצוני' כלל (כלוחות הראשונו' שכתובים משני עבריהם<sup data-n=\"10280\">155</sup> כו' וכאור דתורה שלמעלה שהוא בבחי' פנימי' ועצמיות שנק' חכמה ברורה בעצם כנ\"ל), וע\"כ גם בירידתו למטה הי' טעמו כטעם לשד השמן וכצפיחית בדבש<sup data-n=\"10281\">156</sup>, שזהו כמו טעם המתיקות וחיות הפנימי' דנשמות במתיקות פנימי' התורה<sup data-n=\"10282\">*157</sup> ברזין וסודות [ד]טעמי תומ\"צ למעלה שיתגלו במשיח דכתי' בי' ישכיל עבדי<sup data-n=\"10283\">157</sup> כו' ונק' פלא יועץ כמו<sup data-n=\"10284\">159</sup> חכם חרשי'<sup data-n=\"10285\">158</sup> כו' וזהו כמו לשד השמן דפנימי' ח\"ע שנק' שמן משחת קדש<sup data-n=\"10286\">160</sup> העליון כו' וכצפיחית בדבש כמ\"ש מתוקים מדבש<sup data-n=\"10287\">161</sup> כו'. וז\"ש באתי לגני כו' לג\"ע העליון אכלתי יערי עם דבשי שתיתי [ייני] כו' שהן פנימי' סודות התורה<sup data-n=\"10288\">162</sup> כידוע, אבל באתרי' ממש לאו אורחי' למיכל להיותו למעלה מטעם כמוס לרצון [העליון] כו' והוא כמו בעוה\"ב שאין בו או\"ש כלל כו', אבל המן טעמו כטעם לשד השמן כו' לפי שנק' מזונא דפנימי' ח\"ע דתורה שלמעלה כו' וד\"ל), (ומ\"ש הנני ממטיר לכם לחם כו' כמטר שיורד מן השמים, אך לא כמו במטר במים שיורד בארץ והרוה והולידה שיש שם תערובות טו\"ר בלחם מן הארץ שזהו כמו בהתלבשות הח\"ע בח\"ת בעה\"ד טו\"ר, כמטר דתורה שא' יערוף כמטר לקחי<sup data-n=\"10289\">163</sup> תזל כטל כו' יערוף ענין עורף<sup data-n=\"10290\">164</sup> בחי'",[["10278","153","<b>מי יתן טהור מטמא</b>: איוב יד, ד."],["10279","154","<b>אבן השהם שהוא ברור. . בעצם הווייתו</b>: ראה גם לעיל פ' שמות ז, א. וש\"נ."],["10280","155","<b>כלוחות הראשונו'. . עבריהם</b>: תשא לב, טו. ראה גם מאמרי אדה\"א בראשית ע' תסח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680310\" data-slug=\"torat-chaim\" data-id=\"2300680310\">תו\"ח וישלח קפה, ג</a> ובהערה 32. לקמן פ' תצוה שלא, ב. ויקהל תכא, ג. פקודי תנט, ג. וראה גם לקמן פ' תצוה שנד, ג."],["10281","156","<b>וכצפיחית בדבש</b>: בשלח טז, לא."],["10282","*157","<b>לשד השמן. . פנימי' התורה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161169\" data-slug=\"likkutei-sichot\" data-id=\"1300161169\">לקו\"ש בשלח (כרך טז) ע' 169</a> ובהערה 42."],["10283","157","<b>במשיח. . ישכיל עבדי</b>: נסמן לעיל פ' שמות מג, ד."],["10284","159","<b>כמו</b>: ב: כו'. ה: ליתא."],["10285","158","<b>במשיח. . פלא יועץ. . חכם חרשי'</b>: נסמן לעיל כג, א."],["10286","160","<b>ח\"ע שנק' שמן משחת קדש</b>: תשא ל, כה. לא. ראה גם ביאוה\"ז שמיני סד, ג. ש\"א כד, ב ובהערה 20."],["10287","161","<b>מתוקים מדבש</b>: תהלים יט, יא [ושם: ומתוקים]."],["10288","162","<b>[ייני]. . סודות התורה</b>: ראה מאמרי אדה\"א בראשית ע' תקסט ואילך. דברים ח\"ב ע' תקצא. וש\"נ. נ\"ך ע' סה. וש\"נ."],["10289","163","<b>יערוף כמטר לקחי</b>: האזינו לב, ב."],["10290","164","<b>יערוף ענין עורף</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רכג. וש\"נ."]]],[2300540403,"חיצוני' דח\"ע כמאמר נובלות חש\"מ תורה<sup data-n=\"10291\">165</sup>, אע\"פ שאין באור דתורה שינוי מצד העצם מ\"מ במקבלים מתבררים הטוב מן הרע והטמא טמא יקרא כנ\"ל העוסקי' שלא לש\"ש כו'. משא\"כ במן שנק' לחם מן השמים דוקא שאינו בא בהתלבשות בעה\"ד טו\"ר כלל, אע\"פ שיורד למטה ומתגשם עד שדכו במדוכה כו', וע\"כ לא הי' בו פסולת כלל וז\"ש הנני ממטיר לכם לחם מן השמים כמו שהוא למעלה ממש וד\"ל).\n<b>ומעתה</b> י\"ל מ\"ש ויצא העם ולקטו דבר יום ביומו<sup data-n=\"10292\">166</sup> דוקא וכמ\"ש איש אל יותר ממנו עד בוקר<sup data-n=\"10293\">167</sup> כו' וזה סותר לכאו' כל ענין הנ\"ל בשרש בחי' המן שהי' מלמעלה מן ההשתל' דזמן ומקום כנ\"ל ואיך א' שילקטו דבר יום ביומו דוקא שזהו הבא ונמשך בהתחלקות הזמן דימים דוקא. ועוד י\"ל מ\"ש דבר יום ביומו שכל יום מובדל מחבירו<sup data-n=\"10294\">168</sup> <span data-k=\"pg\">שו</span> ּ ואין לו חיבור עמו כלל וכמ\"ש בזהר דכל יומא לא יהיב ולא יזיף ליומא אחרא<sup data-n=\"10295\">169</sup> כו' (וכך הי' בוימ\"ב דכל יום מובדל מחבירו כמ\"ש בזהר דכל יומא בעבידתי'<sup data-n=\"10296\">170</sup> כו' וכך הוא ב[כל] וא\"ש דהוי עלמא כו'), והלא עיקר בחי' התיקון דשם מ\"ה דחכמה<sup data-n=\"10297\">172</sup> הוא בבחי' ההתכללות<sup data-n=\"10298\">171</sup> והחיבור דוי\"ו מדות דחג\"ת כו' שהן ו' יומין עילאין דאצי' שכלולים זע\"ז דוקא וכמו יום ליום יביע אמר<sup data-n=\"10299\">173</sup> כו', ואמ\"ר זה היינו התכללות דאש מים [ו]רוח<sup data-n=\"10300\">174</sup> שיביע כל יום ליום שלאחריו כו' (וכך הוא בבחי' החכמה דתורה שהוא בבחי' התיקון דשם מ\"ה לאכללא שמאלא בימינא [ו]ימינא בשמאלא<sup data-n=\"10301\">175</sup> כ[מו] ע\"י בחי' קו האמצעי כו' וכמ\"ש מימינו אש דת<sup data-n=\"10302\">176</sup> כו' כידוע), ולמעלה מבואר בשרש המן שהי' מבחי' פנימי' דח\"ע שנק' פנימי' אבא כו' שממנו שרש התיקון דשם מ\"ה דחכ' כידוע, וא\"כ איך א' דבר יום ביומו דוקא בהתחלקות ופירוד המדות דוי\"ו יומי' כו'<sup data-n=\"10303\">177</sup>.\n<b>אך</b> הענין הוא דאדרבה לפי ששרש המן בפנימי' ומקור דח\"ע שלמעלה מן הזמן דשם הוי' כנ\"ל ע\"כ הוא המקור להתחלקות השפע בזמן דימים להיות כ\"א מובדל מחבירו דוקא ולא יזיף לחברי' כו', כי כל יום יש לו מקור מיוחד בחידוש השפע לאותו יום לבדו וביום השני מתחדש השפע ליום זה במדרגה מיוחדת בפ\"ע בלי חיבור והתכללות עם יום שלאחריו. וגם זה אמת דיום ליום יביע אמ\"ר שכלולים זע\"ז דוקא (וכמ\"ש",[["10291","165","<b>נובלות חש\"מ תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["10292","166","<b>ויצא העם ולקטו דבר יום ביומו</b>: בשלח טז, ד [המשך הכתוב הנני ממטיר]."],["10293","167","<b>איש. . עד בוקר</b>: בשלח טז, יט."],["10294","168","<b>שכל יום מובדל מחבירו</b>: ראה גם לעיל פ' בא צג, א. וש\"נ."],["10295","169","<b>דכל יומא. . ליומא אחרא</b>: ראה זהר בשלח סג, ב."],["10296","170","<b>דכל יומא בעבידתי'</b>: ראה זהר ויגש רה, סע\"א. אמור צד, ב. השמטות לזח\"א רסד, ב."],["10297","172","<b>דשם מ\"ה דחכמה</b>: ראה ת\"ז תי\"ט מ, רע\"א ובכסא מלך שם (סג, א) אות א."],["10298","171","<b>התיקון. . בבחי' ההתכללות</b>: ראה גם לעיל פ' שמות מד, ג ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670419\" data-slug=\"torat-chaim\" data-id=\"2300670419\">תו\"ח בראשית מא, א</a> הערה 5."],["10299","173","<b>יום ליום יביע אמר</b>: תהלים יט, ג."],["10300","174","<b>ואמ\"ר. . דאש מים [ו]רוח</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תעב. וש\"נ. לקמן פ' משפטים רפג, ג."],["10301","175","<b>לאכללא. . בשמאלא</b>: נסמן לעיל פ' וארא פה, א."],["10302","176","<b>מימינו אש דת</b>: ברכה לג, ב."],["10303","177","<b>כו'</b>: בתו\"ח כאן באו עוה\"פ התיבות: שממנו שרש. . דוי\"ו יומי' כו'."]]],[2300540423,"בס\"י טרף אש ומים ובללן זע\"ז<sup data-n=\"10304\">178</sup> כו', עד שיש מים באש ואש במים כו'), ואמנם מצד בחי' ההתכללו' הזאת דוקא בא סיבת ההתחלקות והפירוד והבדלה אח\"כ בין זה לזה והא בהא תליא דוקא (כמשי\"ת). וראי' לזה מבחי' החכ' ומדות שבתורה שהוא בבחי' ההתכללו' דחו\"ג דוקא כנ\"ל, ועכ\"ז הרי אנו רואים שעיקר ההתחלקות ופירוד בין המדות דחו\"ג בא ע\"י המדות דחכמה דתורה דוקא, שהרי כל עיקר התורה הוא להבדיל בין טמא לטהור כו' שכל א' על מקומו יבא ולא יתערב הטמא בטהור ואסור במותר כו' שהוא עיקר ענין ההבדלה בין טו\"ר, כמו כל דיני המשנה באו\"ה וטו\"ט כשר ופסול וחייב וזכאי כו' שאינו רק אחר הבירור וההבדלה בתכלית בין טו\"ר ששרשם הוא במדות דחו\"ג כידוע, ואין בירור והבדלה זו רק עפ\"י החכמה ודעת כידוע דאם אין דעת אין הבדלה<sup data-n=\"10305\">179</sup> ע\"כ קבעו הבדלה בחונן הדעת כו', וכך הוא בחי' דעת נוטה דתורה לימין ושמאל בהבדלה נכונה וברורה בתכלית וכמ\"ש לא תסור ימין ושמאל<sup data-n=\"10306\">180</sup> כו' שזהו עיקר כל התומ\"צ כידוע, ועכ\"ז הרי שרש החכ' ומדות דתורה היא בבחי' ההתכללו' לאכללא שמאלא בימינא כו' כמ\"ש מימינו אש דת כו' כנ\"ל, ואין זה ב' הפכי' בנושא א' אלא אדרבה הא בהא תליא דוקא דמצד בחי' ההתכללו' לאכללא<sup data-n=\"10307\">181</sup> דתיקון דשם מ\"ה דחכמה דתורה הוא שעושה בחי' ההבדלה והבירור בין טו\"ר בעה\"ד בסומ\"ר וע\"ט כו' והכל א' כנ\"ל וד\"ל.\n<b>ולהבין</b> זה יש להקדים תחלה בשרש בחי' המן שנק' לחם מן השמים שירד מן השמים בהתחלקות לחלקים קטנים [כ]התחלקות <span data-k=\"pg\">614</span> ּ הטיפין דמטר כמ\"ש הנני ממטיר לכם לחם כו' ובירידתו לארץ הי' כזרע גד לבן כו' שהוא מחולק לחלקים דקים כמ\"ש דק מחוספס ככפור<sup data-n=\"10308\">182</sup> כו' שזהו הוראה על שרשו שהוא מבחי' הגבורה שבחסד, והוא מ\"ש ועינו כעין הבדולח דגוונא סומקא אתחזי בי' בהעלם דהיינו העלם הגבו' בחסד במראה הלובן דבדולח וזהו בחי' גבו' דע\"י שמלובש בהעלם בח\"ס שהוא בחי' טלא דבדולחא הנ\"ל (דאע\"פ שטל השמים מקובץ בחלקים למעלה וגם בירידתו למטה אבל מתחלק גם הם ונק' רסיסי לילה כו') (והוא טל שיחי' המתים שנא' כי טל אורות כו' לשון רבים שמתחלק בכל גוף בפ\"ע ולכך נז' תח\"ה בברכת אתה גבור שהוא בבחי' גבו' שבחסד<sup data-n=\"10309\">183</sup> כמו מכלכל חיים בחסד שהן המזונו' שהן מתחלקי' לחלקים ולכך השולחן בצפון<sup data-n=\"10310\">184</sup>",[["10304","178","<b>טרף אש ומים ובללן זע\"ז</b>: ראה גם לעיל פ' שמות מה, ג. וש\"נ."],["10305","179","<b>דאם אין דעת אין הבדלה</b>: ראה ירושלמי ברכות פ\"ה, ה\"ב. מאמרי אדה\"א דברים ח\"ג ע' תתלג."],["10306","180","<b>לא תסור ימין ושמאל</b>: פ' שופטים יז, א [בדילוג]."],["10307","181","<b>לאכללא</b>: בג: ליתא. ה: חסר."],["10308","182","<b>דק מחוספס ככפור</b>: בשלח טז, יד [בדילוג]."],["10309","183","<b>אתה גבור. . גבו' שבחסד</b>: ראה גם לעיל קסז, ד. וש\"נ."],["10310","184","<b>השולחן בצפון</b>: פקודי מ, כב. יומא כא, ב. ראה מאמרי אדה\"א דברים ח\"ג ע' תשעה. וש\"נ."]]],[2300540443,"כידוע וכן גבו' גשמים<sup data-n=\"10311\">185</sup> ומוריד הטל כו'), והוא בחי' פנימי' דח\"ס שממנו מקור מוצא ההתחלקו' דג' קוין דאצי' ונק' קו המדה<sup data-n=\"10312\">186</sup> או משחת'<sup data-n=\"10313\">187</sup> כו' שמודד כל או\"כ פנימי' ומקיפי' דאצי' בכל הע\"ס דאצי' בג' הקוין חח\"ן ובג\"ה ודת\"י<sup data-n=\"10314\">188</sup> כו' וכל א' על מקומו יבא לא יחליפו ולא ישנו מזל\"ז, וכמו\"כ מאצי' לבי\"ע כמו במרכבה דפני ארי' ופני שור<sup data-n=\"10315\">189</sup> ומחנות שכינה דמיכאל וגבריאל<sup data-n=\"10316\">190</sup> כל א' מובדל מחבירו במדרגה בפ\"ע ולא ישנו תפקידם כו'. והנה אנו מוצאים לכאורה בהיפוך שיש בחי' ההתכללו' בקוין דאצי' ע\"י קו האמצעי (ששרשו בפנימי' הכתר<sup data-n=\"10317\">191</sup> שמשם נמשך בחי' קו המדה דח\"ס שנק' חכ' שבכת\"ר) שזהו עיקר בחי' התיקון [דשם] מה שמתכללים ע\"י כל ההפכיי' דחו\"ג דאצי', עד שגם מאצי' בבי\"ע יש בחי' ההתכללו' ג\"כ במרכבה דפני ארי' ושור ומו\"ג<sup data-n=\"10318\">192</sup> וכה\"ג [ו]כמ\"ש עושה השלום<sup data-n=\"10319\">193</sup> ובשרפי' דבריאה<sup data-n=\"10320\">194</sup> אמר וקרא זא\"ז [ותרגם יונתן] ומקבלין דין מן דין<sup data-n=\"10321\">195</sup> כו', וכמ\"ש בזהר דכליל[ן] דא בדא ושליבן כחדא<sup data-n=\"10322\">196</sup> כו'.\n<b>אך</b> צ\"ל דשניהם אמת ואין זה ב' הפכים כלל כנ\"ל דאדרבה מצד בחי' ההתכללות הוא שנעשה ההתחלקות כו'. והענין הוא כידוע ומבואר במ\"א שיש ב' מיני התחלקות וב' מיני התכללות, א' ההתחלקות בתחלת ההוי' בעצם שהוא בבחי' הנקודות דכתר (באורות דתה\"ו), כמו עצם מהות נקודת הרצון דחסד ועצם נקוד' הרצון דגבורה טרם שמתחלק לי' בחב\"ד וחג\"ת כו' שבלתי יוכלו להתחבר [כלל] כמו אש ומים הפשוטים כמו שהן בעצם כו' כידוע, ולמעלה היינו בחי' ע\"ס דתהו בבחי' נקוד[ות] (ובחי' עקודי' הוא שנק' ע\"ס הגנוזות<sup data-n=\"10323\">197</sup> בעצמות המאציל כמו יו\"ד כחות העצמיים הכלולי' כא' שבנפש<sup data-n=\"10324\">198</sup> שבאים ב[בחי'] התחלקו' בעצם החכמה<sup data-n=\"10325\">199</sup> כו'. והב' התחלקות ההפכיים ממש מזו, והוא מה שכל מדה מתחלק לכמה חלקים שונים עד שיש בכל מדה מהיפוכה דוקא כגבו' שבחסד וחסד שבגבו' כו', כמו שמתחלקי' היסודות דאש ומים במציאותם לריבוי חלקים שונים עד שימצא באש ממים ומים באש כמו אש שותה<sup data-n=\"10326\">200</sup> כו', ומסיבת ריבוי ההתחלקות דכל ספירה מהיפוכה יוכלו להתמזג יחד כמה מיני ריבוי הפכיים בריבוי אופנים שונים לאין שיעור כלל הנק' התכללות (כמ\"ש בס\"י<sup data-n=\"10327\">201</sup> שיש ג'<sup data-n=\"10328\">202</sup> אלפי' רבבות ספי' בו\"ק דז\"א, דהיינו מצד שמתכללי' בריבוי אופנים מאד מחמת ריבוי ההתכללו'<sup data-n=\"10329\">203</sup> שהוא עושה ריבוי <span data-k=\"pg\">שז</span> ּ הכלים מכלים שונים, והוא שיעור קומה של יוצר בראשית<sup data-n=\"10330\">204</sup> כו' שזהו ור\"ב",[["10311","185","<b>גבו' גשמים</b>: תענית ב, א. ראה מאמרי אדה\"א ויקרא ח\"א ע' כה. שע\"ת מח, א ובהערה 4."],["10312","186","<b>קו המדה</b>: נסמן לעיל פ' שמות יג, ג."],["10313","187","<b>משחת'</b>: ראה זהר בראשית יח, ב. ביאוה\"ז פקודי נז, ד."],["10314","188","<b>חח\"ן ובג\"ה ודת\"י</b>: נסמן לעיל פ' וארא פד, ד."],["10315","189","<b>במרכבה דפני ארי' ופני שור</b>: יחזקאל א, י. ראה גם לקמן רנ, א. שע\"ת יג, א ובהנסמן במ\"מ לשם."],["10316","190","<b>ומחנות שכינה דמיכאל וגבריאל</b>: זהר במדבר קיח, ב."],["10317","191","<b>קו האמצעי. . הכתר</b>: נסמן לעיל פ' שמות כא, ב."],["10318","192","<b>ומו\"ג</b>: ה: ומיכאל וגבריאל."],["10319","193","<b>עושה השלום </b>[ה: שלום]: נסמן לעיל יג, ד."],["10320","194","<b>ובשרפי' דבריאה</b>: נסמן לעיל פ' בא צז, ג."],["10321","195","<b>וקרא. . מן דין</b>: ישעי' ו, ג."],["10322","196","<b>דכליל[ן]. . ושליבן כחדא</b>: נסמן לעיל מה, ד."],["10323","197","<b>ע\"ס הגנוזות</b>: נסמן לעיל כח, ד."],["10324","198","<b>שבנפש</b>: ג: שבנפש)."],["10325","199","<b>החכמה</b>: ה: אח\"פ."],["10326","200","<b>אש שותה</b>: יומא כא, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670368\" data-slug=\"torat-chaim\" data-id=\"2300670368\">תו\"ח בראשית יג, א</a> ובהערה 4."],["10327","201","<b>כמ\"ש בס\"י</b>: מובא גם בשם הת\"ז ואד\"ר — ראה מאמרי אדה\"א דברים ח\"ג ע' תתיט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670576\" data-slug=\"torat-chaim\" data-id=\"2300670576\">תו\"ח בראשית מה, ד</a> ובהערה 52."],["10328","202","<b>ג'</b>: ב: רל\"ו. ג: כבפנים. ה: ו' [ועה\"ג נרשם: נ' שצ\"ל רל\"ו]. ראה בהנסמן בהערה שלפנ\"ז."],["10329","203","<b>ההתכללו'</b>: ה: ההתחלקו'."],["10330","204","<b>שיעור קומה של יוצר בראשית</b>: ראה הנסמן באוה\"ת ואתחנן ע' ב'רלג. מאמרי אדה\"א ויקרא ח\"ב ע' תשצו־ דברים שם־ ש\"א לו, ב. ד\"ה וידבר גו' ויצוום תרל\"ח פ\"ד."]]],[2300540463,"כ\"ח<sup data-n=\"10331\">205</sup> כו'), וזהו מ\"ש טרף אש ומים ובללן זה בזה מצד ריבוי ההתחלקות שזהו ריבוי ההרכבות הנמצאים בכ\"א מהיפוכו, ובחי' ההתכללות הזאת שמן ההתחלקו' כנ\"ל זהו כללו' ענין התיקון דבחי' שם מ\"ה דאדם<sup data-n=\"10332\">206</sup> ששרש הכללי הוא בחי' החכ' שבמוח שכלול מכל המדות המתחלקים וכוללם יחד בתחלה בטרם שהן מתחלקי' באו\"כ, כמו שאנו רואים במוח החכמה שכלול בו מכל ההפכיים יחד וממנו יוצא ומסתעף ריבוי ההתחלקות וריבוי ההתכללו' שנק' מזיג' בריבוי האורות בכלים, כמו שכל המטה כלפי חסד שמתחלק בריבוי אופנים שונים עד שכלול גם מהיפוכו משכל שמטה כלפי דין, וכמו\"כ שכל המטה כלפי דין בכלל מתחלק לכמה חלקים באופנים שונים עד שימצא בו הרבה מחלקי השכל שמטה כלפי החסד כו', וע\"כ יכול לחזור בכל הצדדי' ומתהפך משכל של חסד לדין ומדין לחסד כמה פעמי' בכמה אופנים שונים מאד זהו שעושה ריבוי ההתכללות במדות אורות בכלים בכמה ריבוי אופנים שונים מאד, דהיינו מה שיוצא פסק הדבר בריבוי אופני' שונים ומחולקי' ולא באופן א' או ב' או ג', וכל מה שיוצא לפסק הלכה לדין או לחסד בפרטי אופניהם יהי' בבחי' ההתחלקות ופירוד והבדלה גמורה בין זה לזה שנק' בירור הדין וההלכה שלא יוכלו עוד להחליף ולשנות מדין לחסד או להיפוך אפי' בשינוי כל שהוא. וזהו ההתחלקות הג'<sup data-n=\"10333\">207</sup> שאחר ההתכללו' שבא[ה] מסיבת ההתחלקו' של כל אחד לכמה הפכיי' כנ\"ל. ואע\"פ שהתחלקות זו דומה להתחלקו' בעצם המציאות הנ\"ל [מ]אחר שא\"א להם להתחלף [א]ו להתחבר יחד (כמו שא\"א שהטמא יטהר והטהור יטמא והחייב יזכה והזכאי י[ת]חייב אפי' שינוי כל שהוא בכל פרטי הדינים היוצאים אחר בירור החכמה כנ\"ל), מ\"מ מאחר שבאה בריבוי אופנים מצד ריבוי ההתכללו' מכל ההפכיי' יחד שמצד ריבוי של ההתחלקות של כל אחד מהיפוכו כו', א\"כ זהו היפוך גמור מהתחלקות שבעצם כנ\"ל.\n<b>ונמצא</b> מובן מזה דריבוי ההתחלקות שיוצא בבירור הדין וההלכה כ\"א על מקומו בלי חילוף ושינוי ותמורה לעולם ולא יתערבו עוד זהו ע\"פ הדעת וחכמה המבררם שזהו שא' אם אין דעת אין הבדלה כו'. וזהו עיקר בחי' התיקון דחכמה דבחכ' דוקא אתברירו להבדיל בין טו\"ר כמו כשר פסול טו\"ט כו' שזהו התחלקות המדות אחר ההתכללו' דחו\"ג זב\"ז שמזה דוקא יוצא אופנים פרטי' מחולקי' לאין שיעור (וזהו כמוח החכ' דאדם שמתכללים בו כל חי[ות] האברים יחד בתחלה ואח\"כ יוצא אור וחיות כאו\"א באופן פרטי המיוחד כח הראי' בעין וכח השמיעה באוזן בלי ישנו תפקידם ולא יחליפו זב\"ז כלל וכלל וכה\"ג בכל האברים כל א' על מקומו יבא ולא ישונה לפעול פעולת זולתו,",[["10331","205","<b>ור\"ב כ\"ח</b>: תהלים קמז, ה."],["10332","206","<b>שם מ\"ה דאדם</b>: נסמן לעיל פ' שמות ד, ב."],["10333","207","<b>הג'</b>: ה: הב'."]]],[2300540482,"וזהו שנק' ריבוי האורות בריבוי הכלים), [ו]למעלה היינו בחי' קו המדה דפנימי' ח\"ס מקור התיקון דחכ' שמודד כל או\"כ שיוצאים מחולקים בג' קוין דאצי' בכל פרטי הציור דפרצוף אדם בנר\"נ באו\"כ כו', וזהו בחי' התחלקות ה\"ג הנ\"ל שבאה אחר ההתכללו' דחכ' <span data-k=\"pg\">616</span> ּ במקורה בפנימי' דח\"ס<sup data-n=\"10334\">208</sup> שכולל כל האורות יחד אחר שעושה התחלקות לי' וי' ליו\"ד כו', ונותן אח\"כ מדה ושיעור לכל או\"כ בריבוי אופנים שונים לאין שיעור כמ\"ש טרף אש ומים ובללן יחד כו'. ואח\"כ יוצא ההתחלקות שנק' בירור והבדלה שנעשה ע\"פ החכ' הקדומה שנק' חכמה ברורה כמו כי הוא צוה ונבראו<sup data-n=\"10335\">209</sup> באופנים פרטי' בכל א' ולא ישנו תפקידם לעולם כי חק נתן ולא יעבור<sup data-n=\"10336\">210</sup> לעולם, שזהו הכל ע\"פ בחי' מאמר קו המדה הכללי' בכללות בנין העולמות דאבי\"ע עד כל פרטי ציור הנבראים דבי\"ע עד סוף [עולם] העשי' בציור החי[ות] ובהמות וצומח ודומם כו' וכל צבא השמים לא יסבו בלכתן<sup data-n=\"10337\">211</sup> כו' וכמ\"ש במ\"א וד\"ל (ועכ\"ז אין זה התחלקות בעצם אדרבה הרי כאו\"א יש בו מזיגה והרכבה מהיפוכו דוקא כמו כל עוף למינהו<sup data-n=\"10338\">212</sup>, יש בנשר רחמני<sup data-n=\"10339\">213</sup> מהיפוכו כאכזריות שטורף<sup data-n=\"10340\">214</sup> ומזיק והעורב אכזרי<sup data-n=\"10341\">215</sup> ואינו טורף<sup data-n=\"10342\">216</sup> כו', וכן יש בשור רב תבואות<sup data-n=\"10343\">217</sup> ועול נושא אע\"פ שמנגח כו' וכן באריה יש מבחי' השור, וכך בכל<sup data-n=\"10344\">218</sup> דומם וצומח כלול כ\"א מחו\"ג, כי אין דבר מה שנמשך באופן מיוחד [שאינו בא] ע\"י התכללו' מכמה הפכים יחד, כמו שאין דין והלכה פרטי' שאינו בא רק ע\"י התכללו' ומזיגה מחו\"ג, [מ]אחר שהתחלקות זו באה אחר התכללות דוקא כנ\"ל ונק' התחלקות וריבוי אופני המזיגות שונות ולא התחלקות בעצם, כמו שממזגים הטעמים של חריפות ומתיקות בריבוי אופני הרכבות ומזיגות שונות זו מזו דאע\"פ שאין [טעם] א' דומה לחבירו מ\"מ כ\"א נק' מזיג' והרכבה פרטית ולא שהוא עצם פשוט כו'. ונמצא שהתחלקות זו הוא ענין א' עם ההתכללו' בכלל רק שבאה דרך פרט בהתחלקות עד שגם החילוקי' במינים כלול כ\"א מזולתו גם אחר שיצאו מחולקי' ומפורדי' זמ\"ז ולא ישנו תפקידם כנ\"ל וד\"ל).\n<b>וזהו</b> הטעם שאנו רואים שיוכל להיות התכללו' מכל מיני דצ\"ח באדם שכלול מכולם כידוע, אע\"פ שבפרטי מיני הצו\"ד וחי ה[ם] מחולקי' זמ\"ז בתכלית וגם בהיותם כלולים באדם הרי הן מחולקי' כאו\"א, כמו הצומח דשערות וצומח דצפרנים וכה\"ג בדומם שבעצמות וגידים ובשר, וכן בחלק החי שכל פרטי חיות כל אבר מחולק ומובדל מזולתו בכחו ופעולתו כו', מ\"מ יש להן חיבור ושיתוף יחדיו ידובקו והיו למהות אחד ממש שהרי כשיפעול פעולת ההילוך ברגל יתחברו וישתתפו בו כל החיות שונ[ים] שבכל האברים כו' עד החיות הפנימי של הרצון שבמוח",[["10334","208","<b>דח\"ס</b>: שם: דחכמה."],["10335","209","<b>כי הוא צוה ונבראו</b>: תהלים קמח, ה."],["10336","210","<b>חק נתן ולא יעבור</b>: תהלים שם, ו."],["10337","211","<b>לא יסבו בלכתן</b>: יחזקאל א, יב. יז."],["10338","212","<b>כל עוף למינהו</b>: נח ז, יד [ושם: וכל העוף]. בראשית א, כא [ושם: עוף כנף]."],["10339","213","<b>בנשר רחמני</b>: ראה ירושלמי פאה פ\"א, ה\"א. זהר יתרו פ, ב. מאמרי אדה\"ז תקס\"ח ח\"א ע' רנה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380236\" data-slug=\"likkutei-torah\" data-id=\"4001380236\">לקו\"ת אמור לז, ג</a>. מאמרי אדה\"א דברים ח\"ג ע' תתעט. וש\"נ. לקמן פ' משפטים רפו, ד. רצ, א."],["10340","214","<b>בנשר. . שטורף</b>: ראה גם ש\"ך יו\"ד סנ\"ז, סקט\"ו. ביאוה\"ז ויחי כח, ג. מאמרי אדה\"א שבהערה 216."],["10341","215","<b>והעורב אכזרי</b>: נסמן בהערה 213."],["10342","216","<b>והעורב. . ואינו טורף</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשז. וש\"נ."],["10343","217","<b>בשור רב תבואות</b>: ע\"פ משלי יד, ד."],["10344","218","<b>בכל</b>: ה: בבחי'."]]],[2300540500,"כו', לפי שיש בכל א' הרכבה מזולתו דוקא גם בהיותם מחולקי' בפעולתם וכחם, והעיקר מצד הכח הכוללם יחד שהוא הרצון והשכל שבמוח שהי' כלול בו כל הפרטי' בתחלה, הוא שמרגישם יחד גם אחר התחלקותם כידוע ומבואר במ\"א) וד\"ל<sup data-n=\"10345\">219</sup>. וזהו ענין וטעם בחי' התכללות הב' שאחר התחלקות הג' הנ\"ל כמו השיתוף וחיבור שיש בכל האברים יחד כנ\"ל שגם בהתחלקותם יתאחדו יחד ונק' התכללו' חיצוניו' דחיצוניות אדם כידוע וד\"ל (ונמצא שיש בדרך פרט ג' מיני התחלקות וג' מיני התכללות וזהו סדרן, א' ההתכללו' והתחלקות בעצם הנ\"ל, דהיינו ההתכללו' שלהם בכללות פנימי' החכ' שכולל כל הנקודות דרצון דחו\"ג כמו התכללו' החיצוני' בהרגשה כללית [כנ\"ל] ואח\"כ התחלקות בעצם הנ\"ל, ואח\"כ התחלקות דכל מדה בפרט הנ\"ל, ואח\"כ התכללו' בפרט מכל ריבוי <span data-k=\"pg\">שח</span> ּ ההתחלקות הזאת כנ\"ל, ואח\"כ ריבוי ההתחלקות בהבדלה גמורה בהתחלקות האברים בפעולתם כנ\"ל, ואח\"כ התכללות החיצוני' שמתאחדים יחד כנ\"ל וד\"ל).\n<b>והנה</b> כ\"ז הכל בבחי' אדם (שהן ג' מדרגות דעקודים נקודים<sup data-n=\"10346\">221</sup> [ו]ברודים<sup data-n=\"10347\">220</sup>, עקודים שעקודים כל הע\"ס בכלי א'<sup data-n=\"10348\">222</sup> שהוא התכללות בעצם שכולל כל היו\"ד נקודות כו', ונקודים התחלקות ליו\"ד בעצם הנ\"ל, וברודים הוא בחי' ההתכללות דתיקון שמחמת ריבוי ההתחלקות דכל ספי' לי' וי' ליו\"ד כו' בריבוי הכלים פנימי אמצעי חיצון<sup data-n=\"10349\">223</sup> כו' שנק' פרצוף אדם) שהן ג' מיני אדם בכלל, אדם פנימי בפנימי' דח\"ס ואדם אמצעי בהתכללות [והתחלקות] או\"כ ואדם חיצוני<sup data-n=\"10350\">224</sup> בהתכללות החיצוני' שהוא בחיצוני' האברים כנ\"ל וד\"ל. אבל הנה יש עוד בחי' ההתכללות האמיתי' שלמעלה מבחי' ההתכללו' דח\"ס דאדם והוא בעצמות המאציל ממש דלאו מכא\"מ כלל<sup data-n=\"10351\">225</sup> ונק' חד ולא בחושבן<sup data-n=\"10352\">226</sup> י\"ס כו' ושם נק' ע\"ס בלי מה בלי מהות<sup data-n=\"10353\">227</sup> כלל, כמו היו\"ד כחות הכלולים בעצמות הנפש שהן בטלים ממציאותם לגמרי (משא\"כ התכללות דיו\"ד נקודות דרצון הנ\"ל שנק' עקודים שהן במציאות ומהות כחות במספר יו\"ד רק שכלולים כא' כו', שלמעלה הוא שנק' ע\"ס הגנוזות בהעלם בעצמו' כנ\"ל) שלמעלה מהתכללות בעצם הנ\"ל. וזהו שנק' שם מ\"ה מלגיו<sup data-n=\"10354\">228</sup> דאיהו אורח כל<sup data-n=\"10355\">229</sup> האצי' כו' [ש]ע\"י הארה העצמי' מתכללים [כל] הי\"ס מצד בחי' הביטול שלהם במקורא דכולא שהוא אור העצמ[ו]' שמובדל ומרומם ומושלל מכל ספי' כו', ויש בשם מ\"ה זה ג\"כ מבחי' ההתכללו' שבאה מצד התחלקות והתכללות כא'<sup data-n=\"10356\">230</sup>",[["10345","219","<b>במ\"א) וד\"ל</b>: ב: במ\"א וד\"ל. גה: במ\"א וד\"ל)."],["10346","221","<b>דעקודים נקודים [ו]ברודים</b>: ויצא לא, י. יב."],["10347","220","<b>אדם. . דעקודים נקודים [ו]ברודים</b>: ראה גם לעיל קלט, ג."],["10348","222","<b>שעקודים. . בכלי א'</b>: ראה לעיל פ' וארא נב, ד. וש\"נ."],["10349","223","<b>הכלים פנימי אמצעי חיצון</b>: ראה ע\"ח (שער המוחין) ש\"כ, פ\"ה. לעיל פ' בא קכט, ד."],["10350","224","<b>אדם פנימי. . אמצעי. . חיצוני</b>: ראה גם בענין אדם פנימי וכו' מאמרי אדה\"א שמות ח\"א ע' צה ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670542\" data-slug=\"torat-chaim\" data-id=\"2300670542\">תו\"ח בראשית כט, ג</a> ובהערה 25. לקמן פ' תרומה שיד, ב."],["10351","225","<b>דלאו מכא\"מ כלל</b>: ת\"ז בהקדמה (יז, ב)."],["10352","226","<b>חד ולא בחושבן</b>: ת\"ז שם (יז, א)."],["10353","227","<b>ע\"ס. . בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["10354","228","<b>שם מ\"ה מלגיו</b>: נסמן לעיל פ' שמות יג, ד."],["10355","229","<b>כל</b>: נסמן לעיל פ' בא קיג, ג."],["10356","230","<b>כא'</b>: ה: כל א'."]]],[2300540518,"מהיפוכו שנק' אדם פנימי כו', והיינו בחי' פנימי' דח\"ס שנק' חכ' שבכתר, כי בכלל בחי' הכתר נק' ממוצע<sup data-n=\"10357\">231</sup> בין עצמו' המאציל לנאצלים, ובחי' כשב\"כ נחשב מבחי' האחרונה שבעצמות שזהו בחי' הביטול והתכללות האמיתי דע\"ס בעצמו' כנ\"ל וע\"כ לא נחשב ממנ[ין] הי\"ס<sup data-n=\"10358\">232</sup>, ובחי' חכ' שבכתר נק' ראש לנאצלים שזהו בחי' ההתכללו' בעצם דבחי' מ\"ה דאדם כמ\"ש מ\"ה שמו מ\"ה שם בנו<sup data-n=\"10359\">233</sup> בהתכללות דאדם אמצעי באו\"כ [ד]מדות כו'. ודרך פרט בחי' פנימי' דח\"ס הוא מבחי' המקיף דכתר הכללי שכלולים שם הע\"ס בביטול המציאות, וגם ממנו נמשך שרש ההתכללות דבחי' התיקון שכולל כל<sup data-n=\"10360\">234</sup> הי\"ס ומתחלקי' ומתכללי' בפנימי' וחיצוני' דאדם כנ\"ל, והוא בחי' קו המדה שעושה בחי' ההתחלקות בב' אופנים הנ\"ל עד שכל א' על מקומו יבא כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יתורץ כל הנ\"ל בענין שרש המן ושרש החכ' דתו\"מ כו' וענין התחלקות וההתכללו' דמרכבה כו'. ותחלה יובן כל הנ\"ל (בג' מיני התכללו' וג' מיני התחלקות הנ\"ל) במע\"ב שא' בראשית ברא ות\"א בקדמין<sup data-n=\"10361\">235</sup> והוא ברצונו הפשוט ועצמי, כמו ברוך שאמר והי' העולם<sup data-n=\"10362\">236</sup> בכללות שכולל כל מיני רצונות הפנימי' דחו\"ב<sup data-n=\"10363\">237</sup> שבאי' בהתחלקות (ונק' ע\"ס הגנוזות בעצמות כו', והיינו מה ששיער בעצמו בכח<sup data-n=\"10364\">238</sup> מה שעתיד להיות בגילוי ע\"ס כו' וזהו גליף גליפו בטה\"ע<sup data-n=\"10365\">239</sup> (שנק' שה\"ש<sup data-n=\"10366\">240</sup> ), ואח\"כ בבחי' חכ' שבכתר שנק' טעם כמוס לרצון מתחלק כל ספי' ומדה ליו\"ד, כמו <span data-k=\"pg\">618</span> ּ שכל שנוטה לחו\"ג שמתהפך לכל צד בפרטי' רבים שכל א' יש בו מהיפוכו [כ]התחלקות דאש ומים כו', ועי\"ז מתכללים זע\"ז יחד בריבוי אופנים שונים כענין טרף אש ומים ובללן כו' שזהו שנק' שמים תתאין שמקיף הכל וכלול בו כל ההפכיי' יחד, ואח\"כ מתחלק ע\"י מאמר קו המדה בג' קוין ועושה הבדלה בין א' לזולתו כמו שיוצא פסק הדבר דבר מבורר בכמה ריבוי אופנים כ\"א על מקומו בלי יחליפו מזה לזה כנ\"ל, והיינו כל בנין האצי' באו\"כ אחר ההתכללות דבחי' מ\"ה דתיקון והם שרשים לוימ\"ב שהן וא\"ש<sup data-n=\"10367\">241</sup> כו' שכל א' מובדל מחבירו כנ\"ל וד\"ל. ובזה יתורץ מה שעיקר התיקון הוא בבחי' ההתכללות דקוין וממנו יבא ההתחלקות שהכל א' שאין זו התחלקות בעצם אלא בכ\"א יש מהיפוכו כנ\"ל, וגם במרכבה דחיות ושרפי' כ\"א מקבל מזולתו ההפכי כנ\"ל, ועכ\"ז כ\"א על מקומו ומדריגתו ולא ישנו תפקידם לעולם כו' (ועכ\"ז משתתפים ומתאחדים כ\"א<sup data-n=\"10368\">242</sup> לשאת את הכסא וכמו וקרא זא\"ז כמו בחי' [ה]התכללות החיצוניות דחיצוניות האברים באדם גם בהיות כל אבר מובדל",[["10357","231","<b>הכתר נק' ממוצע</b>: נסמן לעיל פ' שמות יא, ג."],["10358","232","<b>הכתר. . לא נחשב ממנ[ין] הי\"ס</b>: נסמן לעיל פ' בא פט, ג."],["10359","233","<b>מ\"ה שמו מ\"ה שם בנו</b>: נסמן לעיל פ' שמות א, ג."],["10360","234","<b>כל</b>: בה: ליתא."],["10361","235","<b>בראשית. . בקדמין</b>: בראשית א, א."],["10362","236","<b>ברוך שאמר והי' העולם</b>: נוסח ברוך שאמר."],["10363","237","<b>דחו\"ב</b>: בה: דחו\"ג."],["10364","238","<b>מה ששיער בעצמו בכח</b>: נסמן לעיל פ' בא קב, א."],["10365","239","<b>גליף גליפו בטה\"ע</b>: זהר בראשית טו, א."],["10366","240","<b>בטה\"ע. . שה\"ש</b>: נסמן לעיל קעח, ג הערה 639."],["10367","241","<b>לוימ\"ב שהן וא\"ש</b>: ראה לקמן רכא, ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ. ח\"ג ע' תתה. וש\"נ."],["10368","242","<b>כ\"א</b>: ה: כאחד."]]],[2300540536,"מזולתו כנ\"ל וד\"ל. וכך הוא בחכמה ומדות דתורה שמן השמים ניתנה שכלול[ה] מחו\"ג כ\"א בפנימי' דח\"ס ומתחלקים המדות ואח\"כ מתכללים בריבוי אופנים כמו במטפ\"ט ומ\"ט פנים טהור<sup data-n=\"10369\">243</sup> כו' עד שיוצא מבורר כל דין והלכה [מוי\"ו] מדות דחכמה<sup data-n=\"10370\">244</sup>, וזהו ע\"פ בחי' החכ' הברורה שנק' קו המדה כנ\"ל, ואין כאן ב' הפכים כלל, דמה שהתורה בבחי' התכללות דימינא כו' זהו העושה בחי' התחלקות להיות כ\"א על מקומו ולא יוחלף מטהור לטמא ומטהור לטמא לעולם והכל א' כנ\"ל, וגם אחר ההבדלה ובירור זה יש בכל פרטי רמ\"ח מ\"ע ושס\"ה ל\"ת<sup data-n=\"10371\">245</sup> שהמה בציור אדם חיצוני בחי' התכללות ואחדות חיצוני' כנ\"ל, וע\"כ נק' תור\"ת האד\"ם ורמ\"ח מ\"ע רמ\"ח אברי' חיצוני' כו' (ונעוץ תחב\"ס<sup data-n=\"10372\">246</sup> דוקא שבהתכללות חיצוני' זו עיקר שלימות דאדם להיות דומה לעליון<sup data-n=\"10373\">247</sup> שהוא התכללות האמיתי דע\"ס דאדם בעצמות א\"ס ממש הנ\"ל וד\"ל).\n<b>ומעתה</b> יובן ג\"כ בשרש ענין המן כמ\"ש ולקטו דבר יום ביומו דוקא בהתחלקות ופירוד דלא יהיב ולא יזיף יומא לחברי' כו' כנ\"ל, אע\"פ ששרש המן בפנימי' דח\"ס שהוא בחי' טלא דבדולחא הנ\"ל שלמעלה מן הזמן כו', כי הנה בחי' ח\"ס שהיא חכמה שבכתר הוא בחי' ממוצע בין עצמיות המאציל לנאצלי' כנ\"ל, ויש בו מבחי' אחרונה שבעצמות שלמעלה מע\"ס לגמרי כנ\"ל בבחי' העלם דמקיף כמ\"ש אין אמר ואין דברים<sup data-n=\"10374\">249</sup> כו') כנ\"ל (ובחי'<sup data-n=\"10375\">248</sup> טה\"ע כנ\"ל), ואמנם גם הוא שרש וראש בבחי' מקיף לאצי' שזהו בחי' ההתכללות בעצם מכל ההפכיי' יחד והוא בחי' שמים העליוני' (בחי' טה\"ת כנ\"ל<sup data-n=\"10376\">250</sup> ) (וכמו דוגמת היריעות דמשכן שהיו כלולים בהם כל הגוונים דשש משזר תכלת וארגמן<sup data-n=\"10377\">251</sup> כו' בבחי' מקיף ואח\"כ יצא לבחי' ההתחלקות והבדלה כל א' במקומו דוקא, כשולחן בצפון ומנורה בדרום ומזבח הזהב באמצע<sup data-n=\"10378\">252</sup> כמו התחלקות דאצי' ג' קוין [כנ\"ל)], וכמו השמים מספרים כו' מנהרין ומנצצין<sup data-n=\"10379\">253</sup> בכל מיני גווני' דחג\"ת (שלזה נק' שמים שכלולים מאש ומים<sup data-n=\"10380\">254</sup> יחד וכמ\"ש <span data-k=\"pg\">שט</span> ּ טרף אש ומים כו'). וזהו יום ליום יביע אמ\"ר בבחי' התכללות זע\"ז דוקא כנ\"ל שזהו בחי' שם מ\"ה דפנימי' ח\"ס (דאיהו אורח כל האצי' בכל פרט וכוללם יחד) [בבחי' העלם דמקיף כמ\"ש אין אמר ואין דברים כו')]<sup data-n=\"10381\">255</sup> כנ\"ל [ו]מזה דוקא נמשך קו המדה דח\"ס למדוד כל או\"כ בשיעור ומדה דוקא (כמ\"ש בכל הארץ יצא קום<sup data-n=\"10382\">256</sup> כו'). וזהו ענין ירידת המן מן השמים הללו לארץ בירידת הטל העליון למטה כנ\"ל (שהוא מבחי' גבורה דע\"י שמלובש בח\"ס שמודד כל מדה באו\"כ דאצי' בוי\"ו מדות דז\"א שהן ו' ימי החול למטה כנ\"ל).",[["10369","243","<b>במטפ\"ט ומ\"ט פנים טהור</b>: נסמן לעיל י, ג."],["10370","244","<b>[מוי\"ו] מדות דחכמה</b>: ראה גם לעיל פ' שמות יא, א. וש\"נ."],["10371","245","<b>רמ\"ח מ\"ע ושס\"ה ל\"ת</b>: מכות כג, סע\"ב."],["10372","246","<b>ונעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["10373","247","<b>דאדם. . דומה לעליון</b>: נסמן לעיל מו, ב הערה 119."],["10374","249","<b>אין אמר ואין דברים</b>: תהלים יט, ד."],["10375","248","<b>בבחי'. . (ובחי'</b>: ב: (ובחי'. ה: (בבחי'. והשאר ליתא. ראה לקמן הערה 255."],["10376","250","<b>כנ\"ל</b>: בד: כו'. גה: כבפנים."],["10377","251","<b>היריעות. . דשש משזר תכלת וארגמן</b>: תרומה כו, א."],["10378","252","<b>כשולחן. . ומנורה. . ומזבח הזהב באמצע</b>: יומא לג, ב."],["10379","253","<b>השמים מספרים. . מנהרין ומנצצין</b>: תהלים יט, ב. ראה זהר תרומה קלו, ב. סידור שחרית לשבת קעח, א ואילך. פיה\"מ ו, ב."],["10380","254","<b>שמים שכלולים מאש ומים</b>: חגיגה יב, סע\"א."],["10381","255","[בבחי'. . כו')]: ראה לעיל הערה 248."],["10382","256","<b>בכל הארץ יצא קום</b>: תהלים יט, ה."]]],[2300540554,"<b>וזהו</b> הנני ממטיר לכם לחם מן השמים ויצא העם ולקטו דבר יום ביומו דוקא בהתחלקות והבדלה בין יום לחבירו (כמו וימ\"ב דכל יומא בעבידתי' כו' וכן ו\"א שנים, דאלף שנה בזמן ומקום כיום א' דאצי', כידוע דאלף שנה הא' בבחי' [החסד] כיום א' דמע\"ב<sup data-n=\"10383\">257</sup> ) שהי' מבחי' החסד במא' יהי אור<sup data-n=\"10384\">258</sup> כו' ואין לו חיבור עם יום הב' שהוא אלף שנה הב' שהוא בבחי' הגבורה וכמ\"ש ויהי ערב כו' יום אחד<sup data-n=\"10385\">259</sup> ). והיינו מטעם הנ\"ל שאחר בחי' ההתכללו' דמדות בח\"ס בחי' המקיף הכולל הכל ועושה התחלקות וריבוי אופנים שונים, הוא שנותן מדה ושיעור לכל יום ויום ביומין עילאין דאצי' בבי\"ע כ\"א על מקומו דוקא ואין ליום זה עם יום הבא אחריו חיבור כלל, לפי שההמשכה הזאת באה בבחי' התחלקות במדה לכל יום ויום בפ\"ע רק כפי מדת אותו יום בלבד לא אתיהיב<sup data-n=\"10386\">260</sup> מיום זה ליום אוחרא כלום, כי אין לו רק לעצמו כפי מדתו [מ]מאמר קו המדה שמודד כל שפע אור במדה ושיעור וכלה אור שפע זו ביום זה ולא ישאר ממנו כלום ליום הב', וביום הב' מתחדש אור ושפע אחרת לגמרי מן השמים במדרגה ואופן מיוחד בפ\"ע ג\"כ במדה ושיעור לאותו היום כפי אופן מדריגתו במזיגה והרכבה פרטי' לא יוסיף ולא יגרע, וזה דבר יום ביומו. ולזאת ציוה משה שלא יותירו ממנו עד בוקר כלום כי בבוקר דיום הב' כבר כלה כח השפע דאור הנמשך ביום הא', וגם מה שנותר ממנו לא יצלח למזון כלל כמ\"ש ויותירו ממנו עד בוקר<sup data-n=\"10387\">261</sup> וירם תולעים ויבאש כי כלה האור והחיות הפנימי' ביום זה, וע\"כ מה שנשאר ממנו לבקר יום הבא יבאש ריחו ויפק<sup data-n=\"10388\">262</sup> טעמו וירום תולעים, אבל באותו יום וגם בלילה עד הבקר הי' ראוי למאכל ועומד בטוב טעמו וריחו ולא יבאש וירום תולעים כלל כי לא הי' בו פסולת ורע כלל (ואין הסרחון [ו]תולעים מצוי רק בפסולת [כ]בשר ולחם רקבון והרי הי' [ה]מן כולו בבחי' הטוב והפנימי' שלא יוכל לבא לידי רקבון וביאוש כלל (כי הי' למעלה מעה\"ד טו\"ר, שזהו למעלה מז' מדות דתהו שהי' בהן בחי' שביר[ה<sup data-n=\"10389\">263</sup> ו]נפילה שהוא המות והכליון כמ\"ש וימלוך וימ\"ת<sup data-n=\"10390\">264</sup> כו', ואם הי' המן בבחי' המדות דתהו שהי' בהן בחי' מיתה הי' בו פסולת ורע [ו]הי' נבאש וירם תולעים כתולעים הנמצאים בבשר המת, וא\"כ ודאי א\"א לומר כמ\"ש וירם תולעים ויבאש שזהו כמו וימלוך וימ\"ת כו' (ולפי <span data-k=\"pg\">620</span> ּ שאין מלכות נוגעת בחברתה<sup data-n=\"10391\">265</sup> אפי' כמלא נימא וזהו וימלוך תחתיו<sup data-n=\"10392\">266</sup> שהיו זת\"ז<sup data-n=\"10393\">267</sup> כידוע), דא\"כ הי' נבאש גם ביומו לעת הערב או בכלות הלילה ולא נא' וירם תולעים ויבאש רק כשנותר עד הבוקר דיום הב' דוקא, לפי שביום הב' דוקא יהי' הנותר מיום אתמול באוש ולא ביומו לפי שאין יום אחד מכין לחבירו כלל כנ\"ל.",[["10383","257","<b>דמע\"ב)</b>: בה: דמע\"ב."],["10384","258","<b>יהי אור</b>: בראשית א, ג."],["10385","259","<b>ויהי ערב כו' יום אחד</b>: בראשית א, ה."],["10386","260","<b>לא אתיהיב</b>: ב: ולא יהיב. ה: ולזאת לא יהיב."],["10387","261","<b>ויותירו ממנו עד בוקר</b>: בשלח טז, כ [בדילוג]."],["10388","262","<b>ויפק</b>: ה: ויפג."],["10389","263","<b>מז' מדות דתהו. . שביר[ה</b>: נסמן לעיל מב, ב."],["10390","264","<b>וימלוך וימ\"ת</b>: וישלח לו, לב ואילך."],["10391","265","<b>שאין מלכות נוגעת בחברתה</b>: ברכות מח, ב."],["10392","266","<b>וימלוך תחתיו</b>: וישלח לו, לג."],["10393","267","<b>זת\"ז</b>: נסמן לעיל פ' שמות מד, ג."]]],[2300540571,"<b>(ועכ\"ז</b> זהו פלא גדול האיך נמצא ריקבון במן גם בנותר ממנו לבקר דיום הב' אחר שהי' שרשו מבחי' עה\"ח שכולו טוב ואין שם אחיזה לרע ופסולת כלל וכמו פנימי' התורה בסודות ורזין דאורייתא שיתגלו לע\"ל כנ\"ל וכה\"ג, וכמ\"ש במן להודיעך כי לא על הלחם<sup data-n=\"10394\">268</sup> כו' כי על כל מוצא פי ה' כו'. אך הענין הוא דבאמת אם הי' המן למטה כמו שהוא למעלה ממש בבחי' הרוחניות דטל העליון שלמעלה מן ההשתל' דזמן ומקום שנק' טל השמים העליונים כו' הרי הי' המן לחיות נצחי ולא הי' צריך לבא בכל יום ויום, כמו הטל שיחי' בו המתים לע\"ל שיחיו חיי עולם כמ\"ש יחיינו מיומים כו' יקימנו ונחיה לפניו<sup data-n=\"10395\">269</sup> כו' לפי שרוח הטומאה יעבור מן הארץ<sup data-n=\"10396\">270</sup> ובלע המות לנצח<sup data-n=\"10397\">271</sup> כו' ויהי' הגוף שיחי'<sup data-n=\"10398\">272</sup> כלי לקבל חיות האלקי הנצחי ולא יכלה. אבל אור וחיות המזון דעכשיו שמתחדש בכ\"י [ויום] הרי בהכרח שבחידוש השפע הבאה יהי' כליון בשפע יום העבר, כמו חידוש השפע במע\"ב בכל יום ויום שבהכרח א\"א לבא חידוש השפע כ\"א בהסתלקות האור והשפע הראשונה דיום שעבר כמו החיות באדם, וכל חי שהוא בבחי' רו\"ש בנשימ' הרוח החיים באפיו וכן בדפק שבלב שאין התחדשות החיות בא בבחי' שוב כ\"א אחר הסתלקות החיים בבחי' רצוא תחלה כו', לפי שהשפע באה בחידוש מאין ליש בהשתלשלו' בצירופי' חדשים ושונים וכל יום יש לו שרש ומקור מיוחד<sup data-n=\"10399\">273</sup> במקור הכללי ובכלות שפעו יעלה למקורו ואז נמשך אור ושפע החדש דיום הב' כידוע ומבואר במ\"א. וא\"כ גם בירידת שפע המן מן השמים למטה בארץ מאחר שנתגשם והי' למזון גופני הרי הי' בא בבחי' חידוש השפע מיום ליום בזמן ומקום כמ\"ש דבר יום ביומו דוקא מטעם הנ\"ל, הרי בהכרח שהי' בחי' הסתלקות האור וחיות שלו בכלות יומו שהוא בהגיע אור הבוקר דיום הב' שעלה למקורו במקור הכללי בשמים העליונים ואז נמשך אור ושפע חדש מן השמים ולכך הי' כליון וריקבון בנותר דאתמול בהגיע אור הבקר דיום הב' דוקא ולא קודם לכן אפי' רגע וד\"ל (ועדיין אין זה מובן דמ\"מ מאחר שלא הי' במן פסולת כלל הרי הי' למטה כמו למעלה שהרי נק' לחם מן השמים כנ\"ל ולמה נבאש וירם תולעים כו' (שאין הריקבון ותולעים נמצא רק בבחי' הרע דנה\"ק כמו שא' בר' אחאי בר' יאשי' דגששי' והוה בי' מששא<sup data-n=\"10400\">274</sup>",[["10394","268","<b>להודיעך </b>[ב: למען הודיעך]<b> כי לא על הלחם</b>: עקב ח, ג."],["10395","269","<b>יחיינו מיומים. . לפניו</b>: הושע ו, ב."],["10396","270","<b>שרוח הטומאה יעבור מן הארץ</b>: זכרי' יג, ב."],["10397","271","<b>ובלע המות לנצח</b>: ישעי' כה, ח."],["10398","272","<b>ויהי'. . שיחי'</b>: ה: ויחי'. . שיהי'."],["10399","273","<b>וכל יום. . שרש ומקור מיוחד</b>: ראה לעיל פ' בא צג, א."],["10400","274","<b>בר' אחאי. . מששא</b>: שבת קנב, ב. ראה גם לקמן פ' משפטים שג, ג."]]],[2300540587,"כו' וא\"ל לפי שרקב עצמות קנאה<sup data-n=\"10401\">275</sup> כו' ובר\"א ב[ר]\"ש שהי' תולע באזנו<sup data-n=\"10402\">276</sup> לפי ששמע זילותא כו' (ע' באוה\"ח<sup data-n=\"10403\">277</sup> ).\n<b>אך</b> הענין הוא לפי ששרש המן הי' מבחי' הגבורות דע\"י שבח\"ס שזהו כעין הבדולח דגוונא סומקא <span data-k=\"pg\">שי</span> ּ אתחזי בי' כו' וכמו כל רשפי אש שמ[ת]פרר לחלקים ע\"כ יצא בהתחלקות כנ\"ל, וזהו מצד התוקף ותגבורת החזק שיש בו ולזאת יש בכחו לטהר ולזכך [ו]לדחות כל רע ופסולת כמו המצרף לכסף וכור לזהב<sup data-n=\"10404\">278</sup> כו' דכל דבר רע יגרש ויכלה ויבער (כמו מי המבול שהי' מבחי' גבורות עליונות דתהו שהיו מטהרים את הארץ למחות כל רע כמו הטובל במי מקוה<sup data-n=\"10405\">279</sup> כו', וכמו ביו\"כ שמים טהורים [מטהרים]<sup data-n=\"10406\">280</sup> כל ענין<sup data-n=\"10407\">281</sup> ולכלוך וכמאן דמסתחי בימא רבא<sup data-n=\"10408\">282</sup> כו' כמא' תבא האם<sup data-n=\"10409\">283</sup> כו', וכך יהי' ענין הטהרה בתח\"ה שהוא לטהר את הטמא כמתים בקבר שיעמדו ויחיו חיי עולם כמ\"ש יחיו מתיך נבלתו יקימנו<sup data-n=\"10410\">284</sup> כו', והוא ע\"י בחי' טל העליון שהוא מבחי' גבורות דע\"י כנ\"ל, ומצד בחי' הגבו' שבו יבער כל טומאה ורע גמור שא\"א לטהר אותו כמו ורוח הטומאה אעביר כו' ובאותו כח וגבו' שיחי' גופו המחי' הצדיקים ויבער<sup data-n=\"10411\">285</sup> הרשעים כמ\"ש ויתבררו ויתלבנו כו'<sup data-n=\"10412\">286</sup> אלה לחיי עולם ואלה לחרפות ולדיראון<sup data-n=\"10413\">287</sup> עולם, כי זהו מטבע כח המדה הזאת דבחי' הגבורות כידוע (כמו בי' מכות דמצרים שהי' רפואה לישראל ונגוף למצרים<sup data-n=\"10414\">288</sup> כמ\"ש במ\"א, וכמו\"כ שיוציא חמה בגבורתה<sup data-n=\"10415\">289</sup> צדיקים מתרפאי' בה ורשעים נידוני' בה, כמ\"ש אלה לחיי עולם כו' וכמ\"ש ויצאו וראו בפגרי האנשים<sup data-n=\"10416\">290</sup> הפושעים בי בגופא דמלכא<sup data-n=\"10417\">291</sup> כו' כי תולעתם לא תמות כו' והי' דיראון לכל בשר, וזהו בימות המשיח כמבואר שם ויהי' שמים חדשים וארץ חדשה<sup data-n=\"10418\">292</sup> בבירור דעה\"ד טו\"ר בתכלית כו'. וזהו ענין הטהרה שבתחה\"מ שהוא ענין בירור והבדלה לדחות כל רע [ו]להחיות כל טוב (שזהו כמו הרפואה ממש שנק' סם חיים לראוי לה, ולרע ופסולת גמור שאין לו תיקון יהי' לסם המות לאבדו לגמרי, וכך הוא בבירור דתורה הנגלית בעה\"ד טו\"ר שא' למיימינים בה סמא כו' כנ\"ל. וכך הוא ג\"כ בפנימי' וסודות התורה (דאורייתא סתים וגליא<sup data-n=\"10419\">293</sup> באופן וענין א') שהוא מבחי' גבו' דע\"י שבפנימי' ח\"ס כנ\"ל, למי שאינו ראוי לזה יזיקנו ויפילנו למטה שממית<sup data-n=\"10420\">294</sup> במיתה",[["10401","275","<b>שרקב עצמות קנאה</b>: משלי יד, ל."],["10402","276","<b>ובר\"א ב[ר]\"ש שהי' תולע באזנו</b>: ראה בבא מציעא פד, ב."],["10403","277","<b>ע' באוה\"ח</b>: בשלח כאן [טז, כ]."],["10404","278","<b>המצרף לכסף וכור לזהב</b>: ע\"פ משלי יז, ג. כז, כא."],["10405","279","<b>מי המבול. . במי מקוה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670581\" data-slug=\"torat-chaim\" data-id=\"2300670581\">תו\"ח נח נח</a>, ג ובהערה 50."],["10406","280","<b>ביו\"כ שמים טהורים [מטהרים]</b>: ראה יומא פה, ב (במשנה)."],["10407","281","<b>ענין</b>: בה: עון."],["10408","282","<b>וכמאן דמסתחי </b>[ב: וכמאמר דאסתחי]<b> בימא רבא</b>: ראה זהר [אד\"ר] נשא קלב, ב. קמ, א. הקדמת הזהר ט, ב. מאמרי אדה\"א דברים ח\"ב ע' תקסז. וש\"נ. ח\"ג ע' א'קלג."],["10409","283","<b>תבא האם</b>: ראה תנחומא חקת ח. במד\"ר פי\"ט, ח."],["10410","284","<b>יחיו מתיך נבלתו </b>[ה: נבלתי]<b> יקימנו [בה</b>: יקומון]: ישעי' כו, יט."],["10411","285","<b>גופו המחי' הצדיקים ויבער</b>: ב: גופי המתים הצדיקים יבער. ה: גופות הצדיקים המתים יבער."],["10412","286","<b>כמ\"ש ויתבררו ויתלבנו כו'</b>: דניאל יב, י [ושם: יתבררו — ראה לקמן פ' ויקהל תכג, א. תורת חיים ח\"ש קכה, ג הערה 28]. ב: כמ\"ש יתבררו ויתלבנו. ה: ויתבררו ויתלבנו כמ\"ש."],["10413","287","<b>אלה לחיי עולם. . ולדיראון</b>: דניאל יב, ב [ושם: לדראון — בה: ודראון — ראה לעיל קצד, א]."],["10414","288","<b>רפואה </b>[בה: רפוא]<b> לישראל ונגוף למצרים</b>: ראה גם לעיל פ' בא פז, א. וש\"נ."],["10415","289","<b>שיוציא חמה בגבורתה </b>[ה: מנרתיקה]: ראה ע\"ז ג, סע\"ב."],["10416","290","<b>ויצאו וראו בפגרי האנשים</b>: ישעי' סו, כב."],["10417","291","<b>בגופא דמלכא</b>: נסמן לעיל פ' שמות ו, ב הערה 281."],["10418","292","<b>שמים חדשים וארץ חדשה</b>: ישעי' שם, כא."],["10419","293","<b>דאורייתא סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א."],["10420","294","<b>שממית</b>: בה: שימות."]]],[2300540603,"וכרת לילך באבדון ובאר שחת (כמו ד' שנכנסו לפרדס<sup data-n=\"10421\">295</sup>, ב\"ע הציץ ומ\"ת<sup data-n=\"10422\">296</sup> שנסתלקה נשמתו באור החיים ונענש בגופו עכ\"פ (וכשריפת בני אהרן<sup data-n=\"10423\">297</sup> נדב ואביהו שהיו שתויי יין<sup data-n=\"10424\">298</sup> מיינ[ה] ש\"ת פנימי' התו' וא' בקרובי אקדש<sup data-n=\"10425\">299</sup> כו' כמ\"ש בזהר), ואלישע אחר<sup data-n=\"10426\">300</sup> יצא לת\"ר<sup data-n=\"10427\">301</sup> כי טינא הי' בלבו<sup data-n=\"10428\">302</sup> מכבר<sup data-n=\"10429\">303</sup>, ולא יסבול כל דבר רע ופסולת מצד בחי' הגבור[ות] עליונ[ות] שבפנימי' הח\"ע [עד ש]גם דק שבדקות הרע יהי' שם לחטא גדול, כענין שמים לא זכו<sup data-n=\"10430\">304</sup> כו' וסביביו נשערה מאד<sup data-n=\"10431\">305</sup> אפי' כחוט השערה מצד עוצם הרוממות ששם תכלית הבירור כמו לפני רוממו' העצמו' [דמלך] בקירובו יותר אל פנימי' וז\"ש בקרוב\"י דוקא אקד\"ש כו'. וכמו שנראה בחוש שבפנימי' התורה לא כל אדם זוכה לקבל וכמו בד' שנכנסו כו' רק ר\"ע יצא בשלום כו', וע\"כ [אמר] אין דורשי' כו' רק ליחיד וחכם ומבין מדעתו מוסרי' לו ר\"פ<sup data-n=\"10432\">306</sup> כו' וכמ\"ש אכתי לא קשאי<sup data-n=\"10433\">307</sup> כו', כי במעט פסולת דק שבו גם שהוא בהעלם גדול יוכל לקצץ <span data-k=\"pg\">622</span> ּ בנטיעות<sup data-n=\"10434\">308</sup> ולהיות בבחי' הפירוד כי לא יסבול שם שום שמץ רע, ולפי שהוא מבחי' כח הגבו' שבחסד יש בו היפוכו לטהר ולזכך כל פסולת דהיינו להוציא כל בחי' הטוב שברע בתכלית וזהו ענין טהר\"ה דתחה\"מ וד\"ל) (וכמו יסורים של אהבה<sup data-n=\"10435\">309</sup> לצדיקים שמתרפאים בזה שיבער הטוב מן הרע והרע נדחה לחוץ כיסורים שקיבל ראבר\"ש וא' חביבי' יסורים<sup data-n=\"10436\">310</sup> כו' כי זהו כמו טבע הרפואה בסממנים חריפים שיחזק כל הטוב והבריאות ויגרש כל רע ופסולת, ואמנם יוכל להיות שיכלה גם החיים והטוב, כי הרי יחלש מן סם הרפואה כשיגבר הרע על הטוב וגם לא יגרש כל העלם חיות הדק ברע ולא יגלה כל חי[ות] הטוב והנעלם ביותר. אבל עיקר הדמיון בכל הנ\"ל היינו כמו מים החמים שבוקעי' ונובעי' במקומות מיוחדי' בארץ כחמי טבריא<sup data-n=\"10437\">311</sup> שבטבעם לרפאות הבריאים, בעיקר יסודה לחדשה מכל בחי' ההעלם שיבא לגילוי במזיג' חיות הדם הוא הנפש ולגרש כל בחי' הרע ופסולת שבדמים וכחות הגוף אף הנעלמי' וסתומים משני' רבות מאד כחליי' גשמיי' קשי' שנתיישנו<sup data-n=\"10438\">312</sup> זמן רב, ולא נפסד בזה שום כח החיוני' הטוב כלל, אדרבה יחזק ביותר לכל חיות וכח הטוב ובאותו כח החזק הטוב הוא עצמו הכח החזק לגרש ולדחות כל רע ופסולת לחוץ בל יראה ובל ימצא כו', וע\"כ המים הללו מועילים יותר מכל הרפואות שבעולם גם לחולה המסוכן ביותר שלא יועיל לו כל רפואה כידוע).",[["10421","295","<b>ד' שנכנסו לפרדס</b>: ראה חגיגה יד, ב."],["10422","296","<b>ב\"ע הציץ ומ\"ת</b>: ראה גם לעיל פ' בא קב, ב. וש\"נ."],["10423","297","<b>וכשריפת בני אהרן</b>: שמיני י, ב."],["10424","298","<b>שתויי יין</b>: ויק\"ר פי\"ב, א. ה. זהר צו לד, א."],["10425","299","<b>בקרובי אקדש</b>: שמיני י, ג."],["10426","300","<b>ואלישע אחר</b>: חגיגה טו, א."],["10427","301","<b>לת\"ר</b>: ב: לתרבות רעה."],["10428","302","<b>טינא הי' בלבו</b>: חגיגה טו, ב."],["10429","303","<b>מכבר</b>: אוצ\"ל: מכבר)."],["10430","304","<b>שמים לא זכו</b>: נסמן לעיל קסז, ג."],["10431","305","<b>וסביביו נשערה מאד</b>: תהלים נ, ג. יבמות קכא, ב. ראה גם מאמרי אדה\"א קונטרסים ע' שג. וש\"נ."],["10432","306","<b>אין דורשי'. . מוסרי' לו ר\"פ </b>[בה: ראשי פרקים]: חגיגה יא, ב (במשנה). יג, א."],["10433","307","<b>אכתי לא קשאי</b>: חגיגה יג, א [כגי' הע\"י]."],["10434","308","<b>לקצץ בנטיעות</b>: חגיגה יד, ב."],["10435","309","<b>יסורים של אהבה</b>: ברכות ה, א."],["10436","310","<b>ראבר\"ש וא' חביבי' יסורים</b>: ראה בבא מציעא פד, ב. לקמן פ' תצוה שכד, ב. וש\"נ."],["10437","311","<b>כחמי טבריא</b>: סנהדרין קח, א. וראה גם שבת (לט, א). מ, א. פסחים ח, ב. מא, א. לקמן פ' ויקהל תט, ד."],["10438","312","<b>כחליי'. . שנתיישנו</b>: ה: כחולי קשה שנתיישן."]]],[2300540617,"<b>וזהו</b> כענין ויורהו ה' עץ<sup data-n=\"10439\">313</sup> שהוא מבחי' עה\"ח כידוע וישלך אל המים המרים ביותר וימתקו [המים] שזה הי' מבחי' גבו' דע\"י שבפנימי' ח\"ס כטל דתח\"ה כנ\"ל, וזהו שם שם לו חוק ומשפט ושם נסהו<sup data-n=\"10440\">314</sup> ויאמר אם [שמוע]<sup data-n=\"10441\">315</sup> כו')<sup data-n=\"10442\">316</sup> דהיינו הבירור בעה\"ד טו\"ר דע\"י הנסיון הזה דמי מרה הוא שהי' בחי' כח ומקור הבירור הזה מטעם הנ\"ל. וגם כאן במזון המן אמר למען אנסנו הילך בתורתי אם לא, כי ע\"י המן הזה שהוא שרש הבירור טו\"ר שיצא מן ההעלם לגילוי לפי שדוחה כל רע ופסולת ומחזק כל טוב ופנימי' הנעלם כנ\"ל במשל מים המרפאים כו' ע\"כ נק' נסיון, כמו הדבר הבא בנסיון הוא שבא כל בחי' ההעלם הדק שבו לגילוי מטוב ורע עד שנמצא ברור ונקי מכל סיג ופסולת וכמו והאלקים נסה את אברהם<sup data-n=\"10443\">317</sup> כו' ונמצא לבבו נאמן<sup data-n=\"10444\">318</sup> כו', או להיפוך שלא נמצא לבב כנס\"י נאמן בנסיון זה דמן במי שיש בו פסולת דק בהעלם שלא יסבלנו ויודחה לחוץ כענין ההבדלה בין צדיקים לרשעים שיהי' בטל דתח\"ה כנ\"ל וכמ\"ש בזהר דבמזונא דמן אבחינו ישראל בין חייבי[א]<sup data-n=\"10445\">319</sup> כו', ומטעם זה הי' מן זה קודם מ\"ת לנסותם אם ילכו כו' כענין הטהרה שקודם הקדושה כנ\"ל, וכ\"ז לפי ששרשו מבחי' גבו' עליונה<sup data-n=\"10446\">320</sup> שהוא מקור הבירור והתיקון כנ\"ל וד\"ל. ומטעם זה הי' שפע מזון המן בא בהתחלקות דבר יום ביומו דוקא ולא יזיף יום לחברי' כו' כנ\"ל, כי כל יום הי' חידוש השפע מבחי' גבו' דע\"י בח\"ס לברר ולתקן לאותו יום לבד (וכמו המזונו' שמתחדשי' בכל יום ויום כמ\"ש ברוך ה' יום יום<sup data-n=\"10447\">321</sup> כמ\"ש בזהר) לפי שבא מבחי' גבו' שבחסד) וכאשר פעל פעולתו באותו יום מסתלק למקורו <span data-k=\"pg\">שיא</span> ּ במקור הגבורות, והיינו שמיד בהגיע הבקר דיום הב' ירם תולעים בנותר דיום האתמול, כי בהסתלקות האור דקדושה שהוא בבחי' הגבו' יאחז בו פסולת הגבו' דק\"נ ששרשם בקו השמאל דגבורות דקדושה שהוא הכח המכלה ומפסיד כמ\"ש בזהר עמ\"ש<sup data-n=\"10448\">322</sup> קץ כל בשר<sup data-n=\"10449\">323</sup> כו', והן התולעי' שבאי' מן מקום ההפסד וכליון דוקא וזהו מצד בחי' הרע הנשאר למטה בתשלום הבירור דמן בגמר פעולתו דוקא, וזהו הטעם גם בנותר דקרבן שבאש דוקא ישרופו<sup data-n=\"10450\">324</sup> כו' וד\"ל).\n<b>והנה</b> מעתה יש להבין למה לא ירד המן בשבת כמ\"ש הוא אשר דיבר ה' שבתון שבת קדש לה' כו' היום לא תמצאוהו בשדה כו', ואם מפני ששרש המן ענין א' עם שרש השבת שהוא בפנימי' אבא בחי' אין דחכ' שבכתר כנ\"ל שהוא",[["10439","313","<b>ויורהו ה' עץ</b>: בשלח טו, כה. ראה גם מאמרי אדה\"א דברים ח\"א ע' קח. וש\"נ. קונטרסים ע' שמו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670122\" data-slug=\"torat-chaim\" data-id=\"2300670122\">תורת חיים בראשית לא, ג</a> ובהערה 23. לקמן פ' משפטים שג, ג."],["10440","314","<b>שם. . ושם נסהו</b>: המשך הכתוב ויורהו ה' עץ."],["10441","315","<b>ויאמר אם [שמוע]</b>: בשלח שם, כו."],["10442","316","<b>כו')</b>: בה: כו'."],["10443","317","<b>והאלקים נסה את אברהם</b>: וירא כב, א."],["10444","318","<b>ונמצא לבבו נאמן</b>: נחמי' ט, ח."],["10445","319","<b>דבמזונא דמן אבחינו ישראל בין חייבי[א]</b>: ראה זהר בשלח סב, ב."],["10446","320","<b>עליונה</b>: ב: העליונות דע\"י שבחכ'. ה: עליונות שבחכ'."],["10447","321","<b>ברוך ה' יום יום</b>: תהלים סח, כ. ראה זהר בשלח סב, א."],["10448","322","<b>עמ\"ש</b>: בה: ע\"פ."],["10449","323","<b>קץ כל בשר</b>: נח ו, יג. ראה זהר נח סג, ב."],["10450","324","<b>בנותר דקרבן. . ישרופו</b>: צו ז, יז."]]],[2300540631,"למעלה מן ההשתלשלו' דזמן ומקום כו', א\"כ אדרבה היא הנותנת שיומשך בהתחלקות בזמן ומקום דוקא כנ\"ל. ועוד יש להבין מה שהקשה בזהר עמ\"ש ויברך אלקי' את יום השביעי כו' דאם ברכת[א] דמזונא<sup data-n=\"10451\">325</sup> [דמן] לא אשתכח כו'<sup data-n=\"10452\">326</sup> מאי ברכתא אית בי' כו'. אמנם הענין הוא דאדרבה דזה שלא הי' יריד' המן ביום השבת זהו הוראה גמורה על עיקר ומקור הברכה דכל וי\"ו ימי החול שהוא בשבת דוקא ע\"כ לא ירד המן בשבת. כי הנה מבואר למעלה בשרש בחי' ההתחלקו' וההתכללות שבבחי' המקיף דח\"ע הוא בחי' מקור ההתחלקות דוקא לכל מדה ומדה בפ\"ע באופן מיוחד באו\"כ כו', וזהו בא מסיבת ההתכללות דכל ההפכיים יחד בבחי' המקיף כמו השמי\"ם מספרים כו' שהן בבחי' מקיף א' יום ליום יביע אמ\"ר בבחי' התכללות זע\"ז דוקא (וכמו ביריעות דמשכן שהי' התכללות מכל הגווני' ההפכיים שש משזר תכלת וארגמן כו'), ואח\"כ בא בהתחלקות בו' מדות דאו\"פ בכלי מיוחד (כמו התכללות דאוי\"ר שכליי' במוח בינה בהעלם כו'). וכך הוא בענין שרש המשכת המן בכל וי\"ו ימי החול שעיקר ומקור הברכה הכללי' שלהם הי' בשבת דוקא והוא מה שנמשך במקור הנעלם דמקיף דמדות דח\"ע שנק' שמים העליונים שכלולים שם הכל כא' כו', והמשכה כללי' זאת נמשך מלמעלה מן השמים העליונים לשמים תחלה (כמו שאו' בשבת השמים מספרים כו') ואח\"כ יורד מן השמים לארץ בכל יום ויום בכל וי\"ו יומין דחול בהתחלקות זמ\"ז, ונמצא דעיקר ומקור השפע הכללי' שנמשך הי'<sup data-n=\"10453\">327</sup> בשמים העליוני' על כל וי\"ו ימי החול הי' בשבת דוקא. ומ\"ש ביום הז' שבת לא יהיה בו היינו שלא הי' יורד המן מן השמים לארץ<sup data-n=\"10454\">328</sup> ביום השבת כמ\"ש היום לא תמצאוהו בשדה דוקא, אבל בחי' מקור השפע דמן הכללי' מלמעלה מן השמים לשמים תחלה הי' דוקא ביום השבת ומזה נמשך בהתחלקות כל וי\"ו ימי החול, כי הוא בחי' מקור הכללי לכל פרטי ההתחלקות דוי\"ו ימי החול שירד המן בכל יום ויום מן השמים לארץ כנ\"ל וד\"ל.\n<b>(והטעם</b> הוא כי בחי' ירידה זו שירד המן מן השמים לארץ הי' בחי' התגלות[ו] לבא בהגשמה ממש עד שדכו במדוכה כו' וזה א\"א להיות בשבת בבחי' פנימי' אור [ו]שפע כזו <span data-k=\"pg\">624</span> ּ שהוא המן ששרשו בבחי' פנימי' הכתר<sup data-n=\"10455\">329</sup> שהוא פנימי' דע\"י כנ\"ל, שבשבת בו שבת וינפש בבחי' פנימי' ועצמות התעה\"פ דפנימי' הכתר וגם בחי' החכמה עולה בפנימי' הכתר שהוא בעצמות המאציל ממש, ע\"כ לא יוכל לירד ולבא למטה בהגשמה להיות במזון גופני ממש. ואע\"פ שנק' מזונא דנפשא ורוחא",[["10451","325","<b>בזהר. . דאם ברכת[א] דמזונא</b>: ראה זהר יתרו פח, א."],["10452","326","<b>כו'</b>: בה: בי'."],["10453","327","<b>הי'</b>: ה: המן."],["10454","328","<b>לארץ</b>: בתו\"ח כאן נכפלו עוה\"פ התיבות (עם הוספת חצע\"ג ותיבת מזה): (בכל. . מזה דחול. מלעיל שו\"ה מספרים."],["10455","329","<b>הכתר</b>: בה: אור אבא."]]],[2300540644,"ונשמתא<sup data-n=\"10456\">330</sup> וכמ\"ש בזהר שהוא מזונא דקי'<sup data-n=\"10457\">331</sup> ביותר כו', עכ\"ז הרי בא בירידה והגשמה למטה למזון הנשמה והגוף יחד כמזון גשמי. אך עיקר המשכת המן הי' בשבת בבחי' הפנימי' הרוחניות שלו כמו שהוא במקומו למעלה, והוא מה שירד בשמים העליונים מלמעלה מן השמים דהיינו בחי' פנימי' התעה\"פ שנק' עדן העליון שיבא בגילוי בעוה\"ב, ובכל שבת יש מעין יום שכולו שבת<sup data-n=\"10458\">332</sup> דעוה\"ב ע\"כ עיקר זמן התגלות האור ההמשכה דמן מן ההעלם דעדן העליון במקור<sup data-n=\"10459\">333</sup> למעלה הי' ביום השבת דוקא על כל הו' יומין דחול כנ\"ל, אבל אינו יורד בהגשמה למטה כלל וד\"ל). ואע\"פ שבכל שארי שפע והמשכה גשמיות יורד ונמשך בשבת כמו בחול ממש כמו שיורדי' גשמים ומצמיחי' בארץ<sup data-n=\"10460\">334</sup> כל צמח תבואה ופירות וכה\"ג, זהו מפני ששרש שפע זו רק בבחי' החיצוני' ואחוריים דחכמה שהוא כללות השפע האלקי' [ה]חיצוניות דמע\"ב, ואם הי' השביתה והעלי' אל העצמי' גם בחיצוניות הי' הכל חוזר למקורא דכולא כו'<sup data-n=\"10461\">335</sup> גם בחי' הדבור די\"מ הי' חוזר למקורו והי' ב[י]ט[ו]ל במציאות בכל העולמות כו'. אך העלי' ושביתה דשבת בכלל ו[ב]פרט אינו רק בבחי' הפנימי' דחכ' ומדות ודו\"מ ולא בחיצוניות כמ\"ש במ\"א שהעלי' ושביתה גם בחיצוניות לא יהי' רק לע\"ל בעוה\"ב שאז נאמר ושבתה הארץ שבת לה'<sup data-n=\"10462\">336</sup> כו' שזהו ענין השביעית. אבל המן לפי שהי' מבחי' הפנימי' ועצמי' דאור החכ' והכתר כנ\"ל ע\"כ לא ירד למטה בהגשמה בשבת רק כמו שהוא במקורו למעלה בעצמות המאציל הוא שנתברך בשמים העליונים כנ\"ל וד\"ל) (ודוגמא לזה כמו סודות ופנימי' רזין דאוריי' שעיקר זמן התגלותם מן ההעלם דח\"ס בבחי' פנימי' כמו שהוא באצי' היינו בשבת דוקא שסוד ה' מתגלה ליריאיו בכל שבת בחידושי אור החכמה בחכמת הקבלה הפנימי' דוקא דהיינו כמו שהוא למעלה במקורו (כמו אסתכלנא ברזא דחכ[מתא])<sup data-n=\"10463\">337</sup>, כידוע דזמן לימוד הקבלה<sup data-n=\"10464\">338</sup> שהוא<sup data-n=\"10465\">339</sup> באצי'<sup data-n=\"10466\">340</sup> היא בשבת דוקא כר\"ת דהשתחוו לה'<sup data-n=\"10467\">341</sup> כו', אבל ירידתם למטה ממש בהגשמה גשמי' כמו להסביר במשל בנפש השכלית הוא בחול).\n<b>אך</b> עדיין אין זה מובן דאם מטעם זה שבחי' פנימי' העונג הנעלם שב[בחי'] פנימי' הח\"ע לא יוכל לבוא במורגש ובהגשמה למטה בשבת לפי ששרש השבת בפנימי' החו\"כ<sup data-n=\"10468\">342</sup> שנק' קדש מלה בגרמי' כנ\"ל, א\"כ למה א' וקראת לשבת ענג שזהו בחי' ירידת ההמשכה דעונג העליון דשבת עילאה שנק' שבת להוי' דאצי' למטה בהגשמה דוקא כמ\"ש בזהר דאתענוג מענגי' דישראל<sup data-n=\"10469\">343</sup> בסעודת השבת כמ\"ש בסעודת דשבת דא היא",[["10456","330","<b>מזונא דנפשא ורוחא ונשמתא</b>: ראה זהר בשלח סא, ב."],["10457","331","<b>דקי'</b>: ב: דק. ה: דקק — ראה זהר שם דקיק. . דקיקאי."],["10458","332","<b>ובכל שבת. . שבת</b>: נסמן לעיל פ' שמות לג, ג."],["10459","333","<b>במקור</b>: בה: במקומו."],["10460","334","<b>שיורדי' גשמים ומצמיחי' בארץ</b>: ראה ב\"ר פי\"א, ה. מאמרי אדה\"א ויקרא ח\"ב ע' תשסה. וש\"נ. קונטרסים ע' תקלז. וש\"נ."],["10461","335","<b>כו'</b>: בה: כי."],["10462","336","<b>ושבתה הארץ שבת לה'</b>: בהר כה, ב. ראה גם לעיל רי, א ובהערה 22."],["10463","337","<b>אסתכלנא ברזא דחכ[מתא]</b>: נסמן לעיל פ' בא קב, ד."],["10464","338","<b>לימוד הקבלה. . בשבת</b>: ראה פע\"ח (שער השבת) שי\"ח, ספכ\"א. שו\"ע האריז\"ל שחרית של שבת ס\"ד. ביאוה\"ז בהקדמה. מאמרי אדה\"א שמות ח\"א ע' קצג. לקמן פ' ויקהל תטז, א. ולהעיר מאור נערב — להרמ\"ק — ח\"ג ספ\"א."],["10465","339","<b>שהוא באצי' היא</b>: תוקן ע\"פ ה. בג: ובתו\"ח כאן: למעלה במקומו [ב: במקורו] — וראה בשורה שלפנ\"ז."],["10466","340","<b>הקבלה. . באצי'</b>: נסמן לעיל פ' שמות כא, א."],["10467","341","<b>כר\"ת דהשתחוו לה'</b>: נסמן לעיל שם."],["10468","342","<b>החו\"כ</b>: בה: החכ'."],["10469","343","<b>דאתענוג מענגי' דישראל</b>: לקמן פ' ויקהל תיח, ג מציין בזהר פ' ויקהל — ראה זהר ויקהל רד, ב. מאמרי אדה\"ז תקס\"ג ח\"א ע' רלז. מאמרי אדה\"א שמות ח\"א ע' קפז. וש\"נ."]]],[2300540656,"סעודתא דע\"י<sup data-n=\"10470\">344</sup> ממש כו', וע\"כ א' פרש חגיכם ולא פרש שבתכם שאין תבשיל שבת מגשם כ\"כ כי בחי' ענג האלקי' של נשמה יתירה דשבת מתלבש <span data-k=\"pg\">שיב</span> ּ בעונג גשמי בטעם המאכל דשבת. וזהו ק\"ו אם במאכל גשמי דעה\"ד טו\"ר דבשר ודגים דסעודת הבשר<sup data-n=\"10471\">345</sup> כמ\"ש במה מענגו בבשר ודגים<sup data-n=\"10472\">346</sup> אין בו פסולת ורע לגשם הגוף כ\"כ, כ\"ש במזון המן שהי' מעה\"ח שלמעלה מעה\"ד ולא הי' בו פסולת כלל כנ\"ל ודאי גם ביריד' שלו בהגשמה אין בו פגם וחסרון כלל וכלל שהרי היו אוכלין המן בשבת כמו בשר ודגים עכשיו א\"כ למה לא ירד המן בשבת, כי גם שהוא בבחי' פנימי' העונג העליון הרי בשבת דוקא הוא שיכול העונג הנעלם העליון לבא למטה בהגשמה כמו סעודת השבת כנ\"ל. וכמו לחה\"פ במקדש שהי' בשבת<sup data-n=\"10473\">347</sup> דוקא כידוע ולחם הפנים הי' כולו בחי' פנימי' הח\"ע בלא חיצוניות כלל וע\"כ נק' לחה\"פ ממש שהי' על השולחן לפני ה'<sup data-n=\"10474\">348</sup> כו' (וכסעודת לויתן ושור הבר<sup data-n=\"10475\">349</sup> לצדיקים לע\"ל כידוע) (וגם שפע העונג הרוחני יותר דבחי' פנימי' התענוג דחכמה להוליד נשמות קדושות בזיווג הגופני שנמשך מטפה הרוחני' שבמוח לגשמיות כזווגי דחכימא<sup data-n=\"10476\">350</sup> הוא בליל שבת דוקא כמ\"ש בו<sup data-n=\"10477\">351</sup> הטעם בזהר והכל ענין א' כידוע).\n<b>אך</b> צ\"ל הטעם לפי שמזון המן הי' בא בבחי' כח ומקור הב[י]רור<sup data-n=\"10478\">*352</sup> לנשמה בגוף ולהבדיל בין טו\"ר כנ\"ל במ\"ש בו למען אנסנו הילך כו' ע\"כ בא בהגשמה ליתן כח ועוז לבירור והבדלה זו כו' כנ\"ל, ובשבת הרי הוא למעלה מבחי' הבירורי'<sup data-n=\"10479\">352</sup> דל\"ט מלאכות<sup data-n=\"10480\">353</sup> כו' כי הוא בבחי' שביתה ונייחא דרוחא מכל מלאכה ועבודה כו' ע\"כ לא הי' בא המן בהגשמה למטה, כי זהו ענין ירידת והתפשטו' למטה מכמו שהוא למעלה בפנימי' דח\"ע כו'. ואע\"פ שהיו אוכלין המן בשבת ממה שנשאר והוכן ביום הוי\"ו זה לא הי' בבחי' בירור אלא ממה שכבר הוברר על ידו בחול בכללות שלהם ביום הוי\"ו שעולה בבחי' או\"ח (כמשי\"ת), וכמו אכילת סעודת השבת שהוא מי שטרח בע\"ש<sup data-n=\"10481\">354</sup> כו' כמ\"ש במ\"א. ואע\"פ שגם בשבת נעשה בחי' הבירור בעה\"ד טו\"ר בצמיחת תבואה וירידת גשמים וכל שפע הנמשך לצורך חיות העולמות, זהו בבחי' החיצוני' דחכמה בלבד כנ\"ל [ו]לא בפנימי'",[["10470","344","<b>דא היא סעודתא דע\"י</b>: סידור אדה\"ז סדר הקידוש ליום השבת. ראה מאמרי אדה\"א שמות שם. וש\"נ."],["10471","345","<b>הבשר</b>: בה: השבת."],["10472","346","<b>במה מענגו בבשר ודגים</b>: ראה שבת קיח, ב. שו\"ע אדה\"ז הל' שבת סרמ\"ב, ס\"ב."],["10473","347","<b>לחה\"פ. . בשבת</b>: אמור כד, ח. תו\"כ שם. מנחות ק, א."],["10474","348","<b>השולחן לפני ה'</b>: אמור שם, ו."],["10475","349","<b>וכסעודת לויתן ושור הבר</b>: נסמן לעיל פ' שמות ו, ד."],["10476","350","<b>כזווגי דחכימא. . בליל שבת</b>: ראה זהר בהקדמה יד, סע\"א. תרומה קלו, רע\"א. ויקהל רד, ב."],["10477","351","<b>בו</b>: בה: ליתא."],["10478","*352","<b>המן. . כח ומקור הב[י]רור</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161169\" data-slug=\"likkutei-sichot\" data-id=\"1300161169\">לקו\"ש בשלח (כרך טז) ע' 169</a> הערה 43."],["10479","352","<b>ובשבת. . למעלה מבחי' הבירורי'</b>: ראה שו\"ע אדה\"ז הל' שבת סשי\"ט. סידור שער בהמ\"ז קי, ג. תו\"א ח\"ש טו, ג ואילך. שע\"ת צז, א ואילך."],["10480","353","<b>דל\"ט מלאכות</b>: ראה שבת עג, א."],["10481","354","<b>מי שטרח בע\"ש</b>: ע\"ז ג, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380046\" data-slug=\"likkutei-torah\" data-id=\"4001380046\">לקו\"ת בשלח ב, א</a>. מאמרי אדה\"א שמות ח\"א ע' קצא. ע' רלא וע' רנג."]]]]});
